// Generated by tools/build_web.py from openppc/ and examples/. Do not edit by hand.
globalThis.OPENPPC_BUNDLE = {"files":{"openppc/__init__.py":"\"\"\"OpenPPC: read-only Google Ads audits where every number is traced back to your data.\"\"\"\n\n__version__ = \"0.1.2\"\n","openppc/__main__.py":"from .cli import main\n\nraise SystemExit(main())\n","openppc/checkfacts.py":"\"\"\"Facts for `openppc check`: every figure a reasonable audit of your files could cite.\n\nFor each export we register the account totals, every row, and every campaign, ad group\nand match type group: cost, clicks, impressions, conversions, CTR, CPC, cost per\nconversion, conversion rate, and each one's share of the total. Then we add every number\nour own templates would print. Template thresholds are left out on purpose: a threshold\nwe chose is not a fact about your account.\n\"\"\"\nfrom dataclasses import replace\n\nfrom .engine import benchmarks\nfrom .facts import Fact, FactBook\nfrom .ingest import load_report\nfrom .ingest.account import is_snapshot, read_json, snapshot\nfrom .templates import TEMPLATES, account_read, account_structure\nfrom .templates._common import register_group, totals\n\nROW_KEYS = (\"search_term\", \"keyword\", \"ad_group\", \"campaign\")\nGROUP_KEYS = (\"campaign\", \"ad_group\", \"match_type\")\n\n\ndef facts_for_report(report):\n    book = FactBook(report.currency)\n    grand = totals(report.rows)\n    register_group(book, \"\", grand, grand)\n    if report.days:\n        book.count(\"days in the date range\", report.days, \"days\")\n    row_key = next((k for k in ROW_KEYS if report.has(k)), None)\n    never_rows, word = [], \"\"\n    if row_key:\n        rows_of = {}  # Google lists a search term once per campaign, ad group and match type\n        for row in report.rows:\n            if row.get(row_key):\n                rows_of.setdefault(\" \".join(row[row_key].lower().split()), []).append(row)\n        start = len(book.facts)\n        for members in rows_of.values():\n            name = members[0][row_key].strip()\n            register_group(book, name, totals(members), grand)  # the term's total, as our reports print it\n            if len(members) > 1:\n                for row in members:  # and each row, as the export shows it\n                    register_group(book, name, totals([row]), grand)\n        book.facts[start:] = [replace(f, level=\"row\") for f in book.facts[start:]]\n        word = {\"search_term\": \"search terms\", \"keyword\": \"keywords\"}.get(row_key, row_key.replace(\"_\", \" \") + \"s\")\n        book.count(f\"{word} in this export\", len(rows_of), \"terms\")\n        never = [members for members in rows_of.values() if totals(members).conversions == 0]\n        never_rows = [r for members in never for r in members]\n        if never:  # what audits usually call waste: every term that never converted, whatever it cost\n            zt = totals(never_rows)\n            book.count(f\"{word} with no conversions\", len(never), \"terms\")\n            book.money(f\"cost of all {word} with no conversions\", zt.cost, \"cost\")\n            book.count(f\"clicks of all {word} with no conversions\", zt.clicks, \"clicks\")\n            if grand.cost:\n                book.pct(f\"cost of all {word} with no conversions as a share of total cost\",\n                         zt.cost / grand.cost * 100, \"cost\")\n    for key in GROUP_KEYS:\n        if key != row_key and report.has(key):\n            groups = {}\n            for row in report.rows:\n                if row.get(key):\n                    groups.setdefault(row[key], []).append(row)\n            start = len(book.facts)\n            for name, members in groups.items():\n                register_group(book, name, totals(members), grand)\n                if key == \"match_type\" and row_key and never_rows:  # \"broad match was 62% of the waste\"\n                    waste = totals(never_rows).cost\n                    mine = totals([r for r in never_rows if r.get(key) == name]).cost\n                    if waste:\n                        book.pct(f\"'{name}' share of the cost of {word} with no conversions\", mine / waste * 100,\n                                 \"cost\", name)\n            book.facts[start:] = [replace(f, level=\"group\") for f in book.facts[start:]]\n    for template in TEMPLATES.values():\n        if template.INPUT_KIND == \"report\" and template.accepts(report):\n            _, template_book = template.run(report)\n            book.facts.extend(template_book.facts)\n    return [f for f in book.facts if f.metric != \"rule\"]\n\n\ndef facts_for_paths(paths, industry=None):\n    facts = []\n    for path in paths:\n        if str(path).lower().endswith(\".json\"):\n            raw = read_json(path)\n            if is_snapshot(raw):\n                _, book, _ = account_structure.evaluate(snapshot(raw, source=str(path)))\n            else:\n                _, book = account_read.run(account_read.load_metrics(path))\n            facts += [f for f in book.facts if f.metric != \"rule\"]\n        else:\n            facts += facts_for_report(load_report(path))\n    if industry:\n        b = benchmarks.lookup(industry)\n        facts += [Fact(f\"{b['name']} average CPC\", b[\"cpc\"], \"money\", \"cpc\"),\n                  Fact(f\"{b['name']} average CTR\", b[\"ctr\"], \"pct\", \"ctr\"),\n                  Fact(f\"{b['name']} average conversion rate\", b[\"cvr\"], \"pct\", \"cvr\"),\n                  Fact(f\"{b['name']} average cost per lead\", b[\"cpl\"], \"money\", \"cpa\")]\n    return facts\n","openppc/cli.py":"\"\"\"OpenPPC command line.\n\n    openppc templates\n    openppc industries\n    openppc audit search-term-waste --sample\n    openppc check --sample\n    openppc audit search-term-waste exports/search_terms.csv --industry home-services\n    openppc check --audit their_audit.md --data exports/search_terms.csv\n\nExit codes: 0 clean, 1 bad input, 2 the check found problems, 3 our own report failed\nits number check (a bug in OpenPPC).\n\"\"\"\nimport argparse\nimport sys\nfrom pathlib import Path\n\nfrom . import __version__\nfrom .checkfacts import facts_for_paths\nfrom .engine import benchmarks\nfrom . import samples\nfrom .engine.trace import render_check, trace\nfrom .templates import TEMPLATES, run_template\n\n\ndef _emit(text, out):\n    if out:\n        Path(out).write_text(text + \"\\n\", encoding=\"utf-8\")\n        print(f\"wrote {out}\", file=sys.stderr)\n    else:\n        print(text)\n\n\ndef _parser():\n    ap = argparse.ArgumentParser(\n        prog=\"openppc\", description=\"Read-only Google Ads audits where every number traces back to your data.\")\n    ap.add_argument(\"--version\", action=\"version\", version=f\"openppc {__version__}\")\n    sub = ap.add_subparsers(dest=\"command\", required=True)\n    sub.add_parser(\"templates\", help=\"list the audit templates\")\n    sub.add_parser(\"industries\", help=\"list the benchmark industries\")\n    a = sub.add_parser(\"audit\", help=\"run a template on an export\")\n    a.add_argument(\"template\", choices=sorted(TEMPLATES))\n    a.add_argument(\"data\", nargs=\"?\", help=\"your export (.csv) or two-period totals (.json)\")\n    a.add_argument(\"--sample\", action=\"store_true\",\n                   help=\"run on the made-up Acme Plumbing account that ships with OpenPPC\")\n    a.add_argument(\"--industry\", help=\"compare against an industry average, e.g. home-services\")\n    a.add_argument(\"--min-cost\", type=float, default=None,\n                   help=\"cost threshold for a waste flag (default: about $20, in the export's currency)\")\n    a.add_argument(\"--brand\", help=\"your brand names, comma-separated; brand terms are never flagged as waste\")\n    a.add_argument(\"--out\", help=\"write the report here instead of printing it\")\n    c = sub.add_parser(\"check\", help=\"check the numbers in any audit against your data\")\n    c.add_argument(\"--audit\", help=\"the audit to check (.md or .txt)\")\n    c.add_argument(\"--data\", action=\"append\", help=\"an export or totals file; repeat for more\")\n    c.add_argument(\"--sample\", action=\"store_true\",\n                   help=\"check the sample AI audit against the made-up Acme Plumbing export\")\n    c.add_argument(\"--industry\", help=\"also accept this industry's published averages\")\n    c.add_argument(\"--out\", help=\"write the result here instead of printing it\")\n    return ap\n\n\ndef explain(error):\n    \"\"\"The message for an error the user can fix, in words rather than Python's error codes.\"\"\"\n    if isinstance(error, FileNotFoundError):\n        return f\"no file at {error.filename}. Check the path.\"\n    if isinstance(error, KeyError) and error.args:\n        return str(error.args[0])\n    return str(error)\n\n\ndef main(argv=None):\n    args = _parser().parse_args(argv)\n    try:\n        if args.command == \"templates\":\n            for t in TEMPLATES.values():\n                print(f\"{t.NAME:20} {t.TIER:5} reads a {t.INPUT}\\n{'':27}{t.SUMMARY}\")\n            return 0\n        if args.command == \"industries\":\n            for key, row in benchmarks.TABLE.items():\n                print(f\"{key:20} {row[0]}\")\n            return 0\n        if args.command == \"audit\":\n            if args.sample == bool(args.data):\n                raise ValueError(\"give your export's path, or --sample to try the made-up Acme Plumbing account\")\n            if args.sample:\n                args.data = str(samples.path(samples.EXPORTS[args.template]))\n                args.industry = args.industry or samples.INDUSTRY\n            markdown, _, passed = run_template(args.template, args.data, industry=args.industry,\n                                               min_cost=args.min_cost, brand=args.brand)\n            _emit(markdown, args.out)\n            return 0 if passed else 3\n        if args.command == \"check\":\n            if args.sample and (args.audit or args.data) or not args.sample and not (args.audit and args.data):\n                raise ValueError(\"give --audit and --data, or --sample to check the sample AI audit\")\n            if args.sample:\n                args.audit, args.data = samples.path(samples.AUDIT), [str(samples.path(samples.AUDIT_DATA))]\n                args.industry = args.industry or samples.INDUSTRY\n            text = Path(args.audit).read_text(encoding=\"utf-8\")\n            claims, contradictions = trace(text, facts_for_paths(args.data, args.industry))\n            _emit(render_check(claims, contradictions), args.out)\n            clean = all(c.verdict == \"traced\" for c in claims) and not contradictions\n            return 0 if clean else 2\n    except (ValueError, FileNotFoundError, KeyError) as e:\n        print(f\"openppc: {explain(e)}\", file=sys.stderr)\n        return 1\n    return 1\n","openppc/engine/__init__.py":"\"\"\"The engine: findings (the arithmetic), benchmarks (the baseline), trace (the checker).\"\"\"\n","openppc/engine/benchmarks.py":"\"\"\"Industry benchmarks: the public baseline an audit is compared against.\n\nPublished averages from WordStream / LocaliQ, \"Google Ads Benchmarks 2026\": US search\ncampaigns on Google Ads and Microsoft Ads, April 2025 to March 2026. Use them as a\nballpark, never a target: they are US-only, annual averages that blend both platforms,\nand every advertiser defines a conversion differently.\n\"\"\"\n\nSOURCE = \"WordStream / LocaliQ Google Ads Benchmarks 2026, US search, Apr 2025 to Mar 2026\"\n\n# key: (display name, CPC, CTR %, conversion rate %, cost per lead)\nTABLE = {\n    \"all\": (\"All industries\", 5.42, 6.64, 8.18, 66.69),\n    \"animals-pets\": (\"Animals & Pets\", 4.06, 7.49, 16.22, 31.50),\n    \"apparel\": (\"Apparel, Fashion & Jewelry\", 4.44, 6.64, 4.50, 97.51),\n    \"arts-entertainment\": (\"Arts & Entertainment\", 1.63, 12.75, 5.91, 26.84),\n    \"legal\": (\"Attorneys & Legal Services\", 9.87, 5.87, 5.55, 131.63),\n    \"auto-sales\": (\"Automotive, For Sale\", 2.27, 8.28, 6.01, 44.26),\n    \"auto-repair\": (\"Automotive, Repair, Service & Parts\", 4.35, 5.56, 15.51, 29.96),\n    \"beauty\": (\"Beauty & Personal Care\", 4.62, 6.75, 10.35, 39.25),\n    \"business-services\": (\"Business Services\", 5.87, 6.10, 4.85, 93.69),\n    \"career\": (\"Career & Employment\", 5.81, 5.88, 3.05, 67.36),\n    \"dental\": (\"Dentists & Dental Services\", 8.00, 5.66, 10.67, 72.97),\n    \"education\": (\"Education & Instruction\", 4.81, 7.56, 13.14, 77.48),\n    \"finance\": (\"Finance & Insurance\", 3.39, 9.83, 2.64, 74.44),\n    \"furniture\": (\"Furniture\", 3.97, 6.57, 2.99, 106.70),\n    \"health-fitness\": (\"Health & Fitness\", 6.17, 5.81, 6.94, 67.36),\n    \"home-services\": (\"Home & Home Improvement\", 8.33, 6.47, 8.05, 90.92),\n    \"industrial\": (\"Industrial & Commercial\", 5.87, 6.57, 8.20, 75.19),\n    \"personal-services\": (\"Personal Services\", 7.17, 7.16, 12.34, 54.60),\n    \"physicians\": (\"Physicians & Surgeons\", 4.76, 6.61, 12.43, 40.04),\n    \"real-estate\": (\"Real Estate\", 3.22, 7.61, 3.70, 102.51),\n    \"restaurants\": (\"Restaurants & Food\", 2.05, 6.83, 8.05, 30.57),\n    \"shopping\": (\"Shopping, Collectibles & Gifts\", 4.14, 8.28, 4.01, 49.40),\n    \"sports-recreation\": (\"Sports & Recreation\", 2.77, 8.75, 7.69, 44.26),\n    \"travel\": (\"Travel\", 2.14, 9.32, 5.83, 44.70),\n}\n\n\ndef lookup(industry):\n    key = (industry or \"\").strip().lower()\n    for k, (name, cpc, ctr, cvr, cpl) in TABLE.items():\n        if key in (k, name.lower()):\n            return {\"key\": k, \"name\": name, \"cpc\": cpc, \"ctr\": ctr, \"cvr\": cvr, \"cpl\": cpl}\n    raise ValueError(f\"unknown industry '{industry}'. Try one of: {', '.join(TABLE)}\")\n\n\ndef compare(book, industry, cost, clicks, impressions, conversions, currency=\"USD\"):\n    \"\"\"The account's ratios next to the industry's averages, every figure registered in the FactBook.\n    Returns the industry row and one dict per metric the data allows. The averages are in US dollars, so an\n    account in another currency is compared on rates only (CTR, conversion rate), never on costs.\"\"\"\n    b = lookup(industry)\n    dollars = (currency or \"USD\").upper() == \"USD\"\n    metrics = []\n    if clicks and dollars:\n        metrics.append((\"CPC\", cost / clicks, b[\"cpc\"], \"money\", \"cpc\", True))\n    if impressions:\n        metrics.append((\"CTR\", clicks / impressions * 100, b[\"ctr\"], \"pct\", \"ctr\", False))\n    if clicks:\n        metrics.append((\"Conversion rate\", conversions / clicks * 100, b[\"cvr\"], \"pct\", \"cvr\", False))\n    if conversions and dollars:\n        metrics.append((\"Cost per conversion\", cost / conversions, b[\"cpl\"], \"money\", \"cpa\", True))\n    rows = []\n    for name, yours, avg, kind, metric, lower_is_better in metrics:\n        if kind == \"money\":\n            y = book.money(f\"your {name}\", yours, metric)\n            a = book.money(f\"{b['name']} average {name}\", avg, metric)\n        else:\n            y = book.pct(f\"your {name}\", yours, metric, dp=2)\n            a = book.pct(f\"{b['name']} average {name}\", avg, metric, dp=2)\n        rows.append({\"name\": name, \"yours\": yours, \"average\": avg, \"yours_text\": y, \"average_text\": a,\n                     \"side\": \"lower\" if yours < avg else \"higher\",\n                     \"better\": (yours < avg) if lower_is_better else (yours > avg)})\n    return b, rows\n\n\ndef section(book, industry, cost, clicks, impressions, conversions, currency=\"USD\"):\n    \"\"\"Markdown lines comparing account ratios with the industry averages.\n    Every figure is registered in the FactBook, so the checker can trace it.\"\"\"\n    b, rows = compare(book, industry, cost, clicks, impressions, conversions, currency)\n    lines = [\"\", f\"## Against the {b['name']} average\", \"\",\n             f\"_Source: {SOURCE}. A ballpark, not a target: US-only, averaged over a year, and \"\n             \"every advertiser counts conversions differently. The industry figure for cost per \"\n             \"conversion is cost per lead._\", \"\"]\n    if (currency or \"USD\").upper() != \"USD\":\n        lines += [f\"_This account is in {currency.upper()} and the averages are in US dollars, so cost per click \"\n                  \"and cost per conversion are left out._\", \"\"]\n    if not rows:\n        return lines\n    lines += [\"| Metric | Yours | Industry average | Read |\", \"|---|---|---|---|\"]\n    for r in rows:\n        lines.append(f\"| {r['name']} | {r['yours_text']} | {r['average_text']} | \"\n                     f\"{r['side']} ({'better' if r['better'] else 'worse'}) |\")\n    return lines\n","openppc/engine/findings.py":"\"\"\"Findings block: the arithmetic and the pattern read, done in code, before any model.\n\nWHY: when we tested language models on real Google Ads accounts, they reversed spend,\nreach and CPA directions and invented figures, even after fine-tuning. Those are not\nlanguage tasks. This module computes every delta, names every direction, classifies\nthe account pattern with explicit rules, and hands any writer a block of facts it\ncannot get wrong.\n\nThe rules are a media buyer's playbook. Read them, argue with them, send a PR.\n\nPorted from the Second Step audit engine (September 2026). Every threshold is a named\nconstant below, and each one has a row in rulebook/rules.csv saying where it comes from.\n\nUsage:\n    from openppc.engine.findings import build_findings\n    block = build_findings(dict(cs=460, ps=1144, ci=11238, pi=38647, cc=279, pc=640,\n                                cv=41, pv=50), meta=dict(currency=\"USD\",\n                                business_model=\"sailing club (membership lead-gen)\"))\n\"\"\"\n\nFLAT = 0.03             # |change| below this is \"flat\"\nSMALL_SAMPLE = 10       # fewer conversions than this in BOTH periods: do not trend CPA\nNOISE_VOLUME = 50       # under this many conversions a period...\nNOISE_MOVE = 0.10       # ...a conversion move smaller than this is one or two events: flat\nHELD = 0.20             # spend cut and conversions within this of prior: they held\nCPA_BAND = 0.10         # CPA within this of prior: efficiency held\nDILUTION_REACH = 0.50   # impressions up at least this much...\nDILUTION_CTR = 0.70     # ...while CTR fell to this share of prior or less: reach dilution\nTIGHTEN_REACH = 0.30    # impressions down at least this much...\nTIGHTEN_CTR = 1.30      # ...while CTR rose to this multiple of prior or more: tightening\nCVR_DROP = 0.70         # conversion rate at or below this share of prior...\nCVR_DROP_CLICKS = 200   # ...on at least this many clicks\nMICRO_CVR = 0.25        # this share of clicks converting: engagement actions, not outcomes\nTHIN_DATA = 30          # conversions a period Google wants before automated bidding is judged\nSEASONAL_WORDS = (\"seasonal\", \"rafting\", \"ski\", \"charter\")\n\n\ndef _pct(c, p):\n    if not p:\n        return None\n    return (c - p) / p\n\n\ndef _dir(c, p):\n    d = _pct(c, p)\n    if d is None:\n        return \"n/a\"\n    if abs(d) < FLAT:\n        return \"flat\"\n    return \"up\" if d > 0 else \"down\"\n\n\ndef _fmt(v, dp=0):\n    if v is None:\n        return \"n/a\"\n    return f\"{v:,.{dp}f}\"\n\n\ndef _pc(c, p):\n    d = _pct(c, p)\n    if d is None:\n        return \"\"\n    if abs(d) < FLAT:\n        return \" (flat)\"\n    return f\" ({'+' if d > 0 else '-'}{abs(d) * 100:.0f}%)\"\n\n\ndef _line(name, c, p, dp=0, unit=\"\", lower_is_better=False):\n    \"\"\"'Spend: 460, from 1,144. DOWN 60%.'  Direction word is explicit and upper-case.\"\"\"\n    d = _dir(c, p)\n    word = {\"up\": \"UP\", \"down\": \"DOWN\", \"flat\": \"FLAT\", \"n/a\": \"no prior base\"}[d]\n    tail = \"\" if d in (\"flat\", \"n/a\") else f\" {abs(_pct(c, p)) * 100:.0f}%\"\n    verdict = \"\"\n    if lower_is_better and d in (\"up\", \"down\"):\n        verdict = \" (improved)\" if d == \"down\" else \" (worse)\"\n    return f\"- {name}: {_fmt(c, dp)}{unit}, from {_fmt(p, dp)}{unit}. {word}{tail}{verdict}.\"\n\n\ndef classify(m):\n    \"\"\"Return (primary_read, flags[]) from the eight raw metrics. Rules in priority order.\"\"\"\n    cs, ps, ci, pi, cc, pc, cv, pv = (m[k] for k in (\"cs\", \"ps\", \"ci\", \"pi\", \"cc\", \"pc\", \"cv\", \"pv\"))\n    cpa_c = cs / cv if cv else None\n    cpa_p = ps / pv if pv else None\n    ctr_c = cc / ci if ci else 0\n    ctr_p = pc / pi if pi else 0\n    cvr_c = cv / cc if cc else 0\n    cvr_p = pv / pc if pc else 0\n    sp = _dir(cs, ps)\n    cv_d = _dir(cv, pv)\n    if max(cv, pv) < NOISE_VOLUME and _pct(cv, pv) is not None and abs(_pct(cv, pv)) < NOISE_MOVE:\n        cv_d = \"flat\"\n    cpa_d = _dir(cpa_c, cpa_p) if (cpa_c and cpa_p) else \"n/a\"\n    flags = []\n\n    # ---- primary read: first matching rule wins ------------------------------------\n    if cv == 0 and pv == 0:\n        read = (\"NO TRACKED CONVERSIONS IN EITHER PERIOD. Verify tracking before reading \"\n                \"performance. Every cost figure here is meaningless until it fires.\")\n    elif cv == 0:\n        read = (f\"CONVERSIONS WENT TO ZERO, from {_fmt(pv, 1)}, on {sp} spend. Tracking is \"\n                \"the first suspect, before any performance conclusion.\")\n    elif pv == 0:\n        read = (f\"CONVERSIONS APPEARED FROM ZERO ({_fmt(cv, 1)}). Either tracking started \"\n                \"working or the account did. Confirm which before crediting the account.\")\n    elif max(cv, pv) < SMALL_SAMPLE:\n        read = (f\"SAMPLE TOO SMALL: {_fmt(cv, 1)} vs {_fmt(pv, 1)} conversions. Direction is \"\n                \"noise at this volume. Do not read CPA movement as a trend or act on it.\")\n    elif sp == \"down\" and -HELD <= _pct(cv, pv) <= FLAT and cpa_d == \"down\":\n        read = (f\"EFFICIENCY WIN. Spend cut {abs(_pct(cs, ps)) * 100:.0f}%, conversions held at \"\n                f\"{cv / pv * 100:.0f}% of prior, CPA improved {abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. \"\n                \"Volume is the constraint, not efficiency. Falling conversions here are a GOOD outcome.\")\n    elif sp == \"down\" and _pct(cv, pv) < -HELD and cpa_d == \"down\":\n        read = (f\"EFFICIENT CONTRACTION. Spend cut {abs(_pct(cs, ps)) * 100:.0f}% and conversions fell \"\n                f\"{abs(_pct(cv, pv)) * 100:.0f}%, less than spend, so CPA improved \"\n                f\"{abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. The cut removed waste first. Volume is now the constraint; \"\n                \"the falling conversion count is the price of the efficiency, not a failure.\")\n    elif sp == \"down\" and cv_d == \"down\" and (cpa_d in (\"flat\", \"n/a\") or\n            (cpa_c and cpa_p and abs(_pct(cpa_c, cpa_p)) <= CPA_BAND)):\n        read = (\"BUDGET REDUCTION, EFFICIENCY HELD. Spend, clicks and conversions fell together; \"\n                f\"CPA moved within {CPA_BAND * 100:.0f}%. Volume fell because spend fell, not because performance broke.\")\n    elif sp == \"down\" and cv_d == \"down\" and cpa_d == \"up\":\n        read = (f\"CONTRACTION WITH WORSENING EFFICIENCY. Spend down {abs(_pct(cs, ps)) * 100:.0f}% \"\n                f\"but conversions fell faster ({abs(_pct(cv, pv)) * 100:.0f}%), so CPA rose \"\n                f\"{abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. The cut removed converting volume, not just waste.\")\n    elif sp in (\"up\", \"flat\") and cv_d == \"down\" and cpa_d == \"up\":\n        if sp == \"up\":\n            read = (f\"OVER-EXPANSION. Spend up {abs(_pct(cs, ps)) * 100:.0f}% while conversions fell \"\n                    f\"{abs(_pct(cv, pv)) * 100:.0f}%; CPA up {abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. \"\n                    \"More money bought worse traffic, or the funnel broke after the click. This is the worst pattern.\")\n        else:\n            read = (f\"DETERIORATION AFTER THE CLICK. Spend flat, conversions down \"\n                    f\"{abs(_pct(cv, pv)) * 100:.0f}%, CPA up {abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. \"\n                    \"Traffic volume is similar; what changed is landing page, form, offer or tracking, not targeting.\")\n    elif cv_d == \"up\" and cpa_d == \"down\":\n        read = (f\"EFFICIENCY GAIN. Conversions up {abs(_pct(cv, pv)) * 100:.0f}% and CPA down \"\n                f\"{abs(_pct(cpa_c, cpa_p)) * 100:.0f}% on {sp} spend. More output at lower cost.\")\n    elif cv_d == \"up\" and sp == \"up\" and cpa_d == \"up\":\n        read = (f\"GROWTH AT A WORSENING RATE. Conversions up {abs(_pct(cv, pv)) * 100:.0f}% but spend up \"\n                f\"{abs(_pct(cs, ps)) * 100:.0f}% and CPA up {abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. \"\n                \"The marginal conversion costs far more than the average. Growth is real; efficiency is degrading.\")\n    elif cv_d == \"up\" and cpa_d in (\"flat\", \"n/a\"):\n        read = (f\"CLEAN SCALE. Conversions up {abs(_pct(cv, pv)) * 100:.0f}% with CPA flat. \"\n                \"Spend and output grew together at stable efficiency.\")\n    elif cv_d == \"flat\" and cpa_d == \"up\":\n        read = (f\"PAYING MORE FOR THE SAME. Conversions flat, CPA up {abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. \"\n                \"Extra spend or reach returned nothing.\")\n    elif cv_d == \"flat\" and cpa_d == \"down\":\n        read = (f\"SAME OUTPUT, CHEAPER. Conversions flat, CPA down {abs(_pct(cpa_c, cpa_p)) * 100:.0f}%. \"\n                \"Efficiency improved without volume changing.\")\n    else:\n        read = \"MIXED OR FLAT. No single dominant pattern; read the metric lines individually.\"\n\n    # ---- secondary flags: independent of the primary read ---------------------------\n    if _pct(ci, pi) is not None and _pct(ci, pi) >= DILUTION_REACH and ctr_p and ctr_c / ctr_p <= DILUTION_CTR:\n        flags.append(f\"REACH DILUTION: impressions up {_pct(ci, pi) * 100:.0f}% while CTR fell from \"\n                     f\"{ctr_p * 100:.2f}% to {ctr_c * 100:.2f}%. Broad matching or audience expansion is buying low-intent reach.\")\n    if _pct(ci, pi) is not None and _pct(ci, pi) <= -TIGHTEN_REACH and ctr_p and ctr_c / ctr_p >= TIGHTEN_CTR:\n        flags.append(f\"TIGHTENING: reach cut {abs(_pct(ci, pi)) * 100:.0f}% while CTR rose from \"\n                     f\"{ctr_p * 100:.2f}% to {ctr_c * 100:.2f}%. Targeting narrowed and relevance improved.\")\n    if cvr_p and cvr_c / cvr_p <= CVR_DROP and cc >= CVR_DROP_CLICKS:\n        flags.append(f\"CONVERSION RATE fell from {cvr_p * 100:.2f}% to {cvr_c * 100:.2f}%. \"\n                     \"Clicks are converting worse; suspect landing page, offer, tracking, or click quality.\")\n    if cvr_c >= MICRO_CVR:\n        flags.append(f\"MICRO-CONVERSIONS LIKELY: {cvr_c * 100:.0f}% of clicks convert. These are engagement \"\n                     \"actions, not outcomes. Do not read CPA as cost per lead or booking.\")\n    if 0 < max(cv, pv) < THIN_DATA:\n        flags.append(f\"THIN DATA: under {THIN_DATA} conversions a period is too few to judge automated bidding on.\")\n    return read, flags\n\n\ndef biggest_move(m):\n    \"\"\"Which metric moved most, dollar-weighted: CPA and conversions outrank reach.\"\"\"\n    cs, ps, cv, pv = m[\"cs\"], m[\"ps\"], m[\"cv\"], m[\"pv\"]\n    cpa_c = cs / cv if cv else None\n    cpa_p = ps / pv if pv else None\n    cands = []\n    if cpa_c and cpa_p:\n        cands.append((\"CPA\", _pct(cpa_c, cpa_p)))\n    if pv:\n        cands.append((\"conversions\", _pct(cv, pv)))\n    if ps:\n        cands.append((\"spend\", _pct(cs, ps)))\n    if not cands:\n        return \"not computable\"\n    name, d = max(cands, key=lambda x: abs(x[1]))\n    return f\"{name} {'up' if d > 0 else 'down'} {abs(d) * 100:.0f}%\"\n\n\ndef build_findings(m, meta=None):\n    meta = meta or {}\n    cs, ps, ci, pi, cc, pc, cv, pv = (m[k] for k in (\"cs\", \"ps\", \"ci\", \"pi\", \"cc\", \"pc\", \"cv\", \"pv\"))\n    cpa_c = cs / cv if cv else None\n    cpa_p = ps / pv if pv else None\n    ctr_c = cc / ci * 100 if ci else 0\n    ctr_p = pc / pi * 100 if pi else 0\n    read, flags = classify(m)\n    bm = (meta.get(\"business_model\") or \"\").lower()\n    if any(w in bm for w in SEASONAL_WORDS):\n        flags.append(\"SEASONAL BUSINESS: period-over-period is the wrong lens. Most of any change is the \"\n                     \"calendar. Compare against the same period last year before crediting the account.\")\n    cur = meta.get(\"currency\", \"USD\")\n    if cur and cur.upper() != \"USD\":\n        flags.append(f\"CURRENCY IS {cur.upper()}: do not compare these figures to USD accounts.\")\n\n    lines = [\n        \"COMPUTED FINDINGS (facts, already calculated; restate them, never recompute or reverse them):\",\n        _line(\"Spend\", cs, ps),\n        _line(\"Impressions\", ci, pi),\n        _line(\"Clicks\", cc, pc),\n        f\"- CTR: {ctr_c:.2f}%, from {ctr_p:.2f}%. {_dir(ctr_c, ctr_p).upper()}.\",\n        _line(\"Conversions\", cv, pv, dp=1 if (cv % 1 or pv % 1) else 0),\n        (_line(\"CPA\", cpa_c, cpa_p, dp=2, lower_is_better=True)\n         if (cpa_c and cpa_p) else f\"- CPA: {_fmt(cpa_c, 2)}, from {_fmt(cpa_p, 2)}.\"),\n        \"\",\n        f\"READ: {read}\",\n        f\"BIGGEST MOVE: {biggest_move(m)}\",\n    ]\n    if flags:\n        lines.append(\"FLAGS:\")\n        lines += [f\"- {f}\" for f in flags]\n    else:\n        lines.append(\"FLAGS: none\")\n    return \"\\n\".join(lines)\n","openppc/engine/trace.py":"\"\"\"The checker: find every number in a piece of text and trace it back to your data.\n\nEach number gets one of four verdicts:\n\n  traced        it equals a fact from your data, at the precision it was written.\n                \"$1.4k\" matches 1,361.04 because both round to 1,400; \"$1,500\" does not.\n  mismatch      it equals a fact, but the text attaches it to a different metric or row:\n                \"22 conversions\" when 22 is that search term's clicks.\n  not in data   nothing in your data produces it. It may be a guess, a typo, or a figure\n                from data you did not provide. Either way, nobody has checked it.\n  can't check   it is not a figure an export holds (a target, a threshold, a forecast, a\n                what-if: \"would cut CPA to $49\"), or it is the audit's own calculation over rows\n                we cannot rebuild (Performance Max against non-brand Search, \"the other $3,690\").\n                Shown apart, with a prompt to ask for the working, and never counted as failing.\n\nA number is only ever flagged when we know what it claims to be: a figure of a row or match type\nthe text names, of the rows it names together, of the terms that never converted, or of the whole\naccount. The flag then says what that figure really is. Everything else we cannot confirm is\n\"can't check\": flagging the audit's own arithmetic as wrong would be a guess.\n\nIt also flags sentences whose verb contradicts their own numbers (\"fell from 9% to 14%\").\n\nBesides each row and the account, it checks what audits usually work out: the sum, rates and\nshares of the rows a sentence names together (\"these three terms: 60 conversions, $44.99 per\nconversion\"), of a match type (\"broad\", \"exact/phrase\"), and of the rows under a heading. A\nsentence that says \"this term\" or \"it\" refers to the row named just before.\n\nSkipped on purpose: whole numbers up to 12 with no $ or % (\"top 5\", \"7 skills\", list\nmarkers), unless they count the clicks, conversions or impressions of a row the text names\nor of the whole account (\"'drain cleaning' got 7 conversions\"); years; day-of-month numbers\nafter a month name; and digits inside a search term or keyword that the text names\n(\"40 gallon water heater\"), quoted or not.\n\nA row's figure backs a number only when the text names that row. With no row named, only\naccount-level figures count: otherwise any made-up number would find some row that happens\nto share it. Round numbers with no metric word can still match an account figure by chance,\nso every trace names the fact it matched. Read the \"traced to\" column, don't just count.\n\"\"\"\nimport re\nfrom dataclasses import dataclass\n\nfrom ..facts import Fact\n\n# Money: a symbol before the number ($, A$, CA$, NZ$, \u20ac, \u00a3, \u20b9, \u00a5, Rs), or a currency code before or after it.\nCODES = (\"USD|INR|EUR|GBP|AUD|CAD|NZD|JPY|CHF|SEK|NOK|DKK|PLN|CZK|HUF|KRW|CNY|HKD|SGD|MYR|THB|IDR|PHP|VND|AED\"\n         \"|SAR|ILS|TRY|ZAR|BRL|MXN\")\nCUR = rf\"(?:(?:US|AU|A|CA|C|NZ|HK|S|R|MX)\\$|[$\u20ac\u00a3\u20b9\u00a5]|Rs\\.?\\s?|(?:{CODES})\\s)\"\n# Grouped in thousands (144,775) or the Indian way in lakhs (1,44,775); \"1.45 lakh\" and \"2 crore\" are magnitudes.\nNUM = re.compile(rf\"(?<![\\w.$])(?P<cur>{CUR})?\\s?(?P<num>\\d{{1,3}}(?:,\\d{{3}})+(?:\\.\\d+)?|\\d{{1,2}}(?:,\\d{{2}})+,\\d{{3}}\"\n                 rf\"(?:\\.\\d+)?|\\d+(?:\\.\\d+)?)(?P<mag>[kKmM](?![A-Za-z])|\\s?(?:[Ll]akhs?|[Ll]acs?|[Cc]rores?|[Cc]r)\\b)?\"\n                 rf\"(?P<pct>\\s?%)?(?P<code>\\s(?:{CODES})\\b)?\")\nLIST_MARKER = re.compile(r\"^\\s*(?:[-*>]\\s*)?(\\d+)[.):/]\\s\")\nMONTH_DAY = re.compile(r\"\\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\\.?\\s+(\\d{1,2})\\b\",\n                       re.I)\nCODE_SPAN = re.compile(r\"`[^`]*`\")  # file names and commands are identifiers, not claims\nTABLE_SEP = re.compile(r\"^\\s*\\|?\\s*:?-{3,}\")\nFROM_TO = re.compile(rf\"\\bfrom\\s+~?{CUR}?\\s?(\\d[\\d,]*(?:\\.\\d+)?)\\s*%?\\s*(?:to|\u2192|-)\\s*~?{CUR}?\\s?\"\n                     r\"(\\d[\\d,]*(?:\\.\\d+)?)\", re.I)\nVERB = re.compile(r\"\\b(fell|falls|fall|dropped|drops|declined|decreased|shrank|slipped|down|\"\n                  r\"rose|rises|grew|increased|climbed|jumped|up)\\b\", re.I)\nDOWN_VERBS = {\"fell\", \"falls\", \"fall\", \"dropped\", \"drops\", \"declined\", \"decreased\", \"shrank\", \"slipped\", \"down\"}\nMAG = {\"k\": 1e3, \"m\": 1e6, \"lakh\": 1e5, \"lakhs\": 1e5, \"lac\": 1e5, \"lacs\": 1e5, \"crore\": 1e7, \"crores\": 1e7, \"cr\": 1e7}\nGENERIC = (\"\", \"rule\")  # facts that fit any wording: account-level unlabeled figures and our own thresholds\nMONEY_METRICS = {\"cost\", \"cpc\", \"cpa\"}  # a dollar figure is a cost, a cost per click or a cost per conversion\nACCOUNT_ONLY = {\"days\"}  # no search term or keyword has a figure in days\nNEVER_METRICS = {\"cost\", \"clicks\", \"impressions\", \"terms\"}  # what the terms that never converted add up to\nGROUP = \"__group__\"  # the rows a sentence takes together; its figures are worked out per sentence\n\n# Longer phrases win over the words inside them (\"cost per click\" is CPC, not cost).\nMETRIC_WORDS = [(metric, re.compile(pattern)) for metric, pattern in (\n    (\"cpc\", r\"cost[- ]per[- ]click|\\bcpc\\b|\\bper click\\b\"),\n    (\"cpa\", r\"cost[- ]per[- ](?:conversion|conv|lead|acquisition|booking|sale|enquiry|inquiry|enquirie|inquirie)s?\"\n            r\"|\\bcpa\\b|\\bcpl\\b|cost\\s*/\\s*conv\\.?|\\bcost each\\b|(?<=\\d)\\s?each\\b\"\n            r\"|(?<=\\d)\\s?an? (?:lead|conversion|sale|booking|sign-?up|enquiry|inquiry|call|customer|student|admission)\\b\"\n            r\"|\\bper (?:conversion|lead|booking|enquiry|inquiry|sale|sign-?up|admission|student|customer)\\b\"),\n    (\"ctr\", r\"click[- ]?through(?:[- ]rate)?|\\bctr\\b\"),\n    (\"cvr\", r\"conv(?:ersion)?\\.?[- ]rate|\\bcvr\\b|\\bconvert(?:s|ed|ing)? at\\b\"\n            r\"|\\bof (?:its |their |the |all )?clicks? (?:became|become|turned into|turns? into|converted|convert|led to|resulted in)\"\n            r\"(?: (?:into |to )?(?:a |an )?(?:leads?|conversions?|sales|bookings?|sign-?ups?|enquir(?:y|ies)|inquir(?:y|ies)))?\\b\"\n            r\"|\\b(?:became|become|turned into|turns? into|converted into|resulted in|led to) (?:a |an )?\"\n            r\"(?:leads?|conversions?|sales|bookings?|sign-?ups?|enquir(?:y|ies)|inquir(?:y|ies))\\b\"),\n    (\"impressions\", r\"\\bimpressions?\\b|\\bimpr\\b\"),\n    (\"clicks\", r\"\\bclicks?\\b\"),\n    (\"conversions\", r\"\\bconversions?\\b|\\bconv\\b|\\bleads?\\b|\\bbookings?\\b|\\bsales\\b|\\bsign-?ups?\\b\"\n                    r\"|\\benquir(?:y|ies)\\b|\\binquir(?:y|ies)\\b\"),\n    (\"cost\", r\"\\bcost\\b|\\bspend(?:ing)?\\b|\\bspent\\b|\\bwaste[d]?\\b|\\bwasting\\b|\\bbudget\\b|\\bburn(?:ed|ing|t|s)?\\b\"),\n    (\"terms\", r\"\\bsearch terms?\\b|\\bkeywords?\\b|\\bterms\\b|\\bqueries\\b\"),  # \"30 search terms\" counts terms\n    (\"days\", r\"\\bdays\\b\"),  # plural only: \"31 days\" counts days, \"$24.75 a day\" is a rate\n)]\nCLAUSE_BREAK = re.compile(r\"[,;:.()]\")  # \"732 clicks, 85 conversions\": the comma ends clicks' claim on 85\n# A softer break: in \"CTR was 7.43% and cost per conversion $58.5\", \"and\" hands the next metric its own number.\nCONJUNCTION = re.compile(r\"\\b(?:and|but|while|whereas|versus|vs)\\b\")\n# Small whole numbers: checked only when they count something (\"7 conversions\"), never \"top 5\" or \"step 3\".\nSMALL_COUNT = re.compile(r\"\\s*(?:more\\s+|fewer\\s+|extra\\s+|new\\s+)?(?:conversions?|conv\\b|leads?|sales\\b|bookings?|\"\n                         r\"sign-?ups?|clicks?|impressions?|impr\\b)\", re.I)\nNOT_A_COUNT = re.compile(r\"(?:\\btop|\\bfirst|\\blast|\\bnext|\\bstep|\\bpriority|\\brank|\\bpage|\\bposition|#)\\s*$\", re.I)\nACCOUNT_CUE = re.compile(r\"\\b(?:account|total|overall|in all|altogether)\\b\", re.I)\nPERFORMANCE = {\"clicks\", \"conversions\", \"impressions\"}\n\nQUOTED = re.compile(r\"[\u201c\\\"]([^\u201d\\\"]{1,80})[\u201d\\\"]\")  # a quoted name counts at any length\nMATCH_TYPES = {\"broad match\", \"phrase match\", \"exact match\", \"broad\", \"phrase\", \"exact\",\n               \"exact match (close variant)\", \"phrase match (close variant)\"}\n# \"broad match\", \"6 broad keywords\", \"Broad:\"; a pair (\"exact/phrase\", \"Exact and Phrase deliver\") names both together\n# anywhere, while one word alone means nothing (\"a broad strategy\", \"the exact figure\")\nMATCH_ALIAS = re.compile(r\"\\b(broad|exact|phrase)\\s*(?:and|&|/|or|\\+)\\s*(broad|exact|phrase)\\b|\\b(broad|exact|phrase)\"\n                         r\"(?=\\s*(?:match|keywords?|terms?|queries|rows|:|\\)|spend|cost|cpa|cost per|conversions?|clicks|\"\n                         r\"\\(\\s*\\d+\\s*(?:keywords?|search terms?|terms?)))\",\n                         re.I)\nSENTENCE = re.compile(r\"(?<=[.!?])[*_]{0,2}\\s+(?=\\S)\")\nANAPHORA = re.compile(r\"\\b(?:this|it|its|these|those|they|their|both)\\b\", re.I)\nGROUP_CUE = re.compile(r\"\\b(?:combined|together|altogether|in total|between them|both|these|those)\\b\", re.I)\nTHESE_N = re.compile(r\"\\b(?:these|those|the|all)\\s+(two|three|four|five|six|seven|eight|nine|ten|\\d{1,2})\\b\", re.I)\nWORD_NUM = {\"two\": 2, \"three\": 3, \"four\": 4, \"five\": 5, \"six\": 6, \"seven\": 7, \"eight\": 8, \"nine\": 9, \"ten\": 10}\n# Words that make a number something an export cannot hold: a target or limit, or a forecast or what-if.\nTARGET = re.compile(r\"\\b(?:thresholds?|targets?|goals?|aim(?:ing)?|benchmarks?|limits?|caps?|minimum|maximum|\"\n                    r\"at least|at most|no more than|up to|under|over|more than|fewer than|less than|smaller than|\"\n                    r\"larger than|bigger than|above|below|measured against|compared (?:to|with)|relative to|\"\n                    r\"sure|confiden(?:t|ce)|significan(?:t|ce)|bar|reach(?:ed|es)?|industry|sector|vertical|niche|\"\n                    r\"typical|median)\\b|\\b[a-z]+-[a-z]+\\s+average\\b\",\n                    re.I)\nWHATIF = re.compile(r\"\\b(?:would|could|might|will|if|without|excluding|instead|expect(?:ed)?|forecasts?|\"\n                    r\"projected|projections?|estimated?|annuali[sz]ed|a year|per year|yearly|per month|monthly|\"\n                    r\"saves?|saved|savings?|frees? up|recover(?:ed|able)?|redeploy(?:ed)?|realloca\\w*|increase|decrease|raise|\"\n                    r\"(?<!or )lower|reduce|cuts?|cutting|boost|lift|improve(?:ment|s|d)?)\\b|\\d\\s?[x\u00d7]\\b|\"\n                    r\"\\bof (?:that|this|the|its) (?:ad group|campaign)\", re.I)\nLIST_LINE = re.compile(r\"^\\s*(?:[-*+]|\\d+[.)])\\s\")\nOF_PAIR = re.compile(r\"(\\d[\\d,]*(?:\\.\\d+)?)%?\\s+(?:of|out of)\\s+(?:the\\s+|all\\s+|its\\s+|their\\s+)?\"\n                     r\"(?:[$\\u20ac\\u00a3\\u20b9]\\s?)?(\\d[\\d,]*(?:\\.\\d+)?)\")  # \"60 of 85 conversions\"\nNEVER = re.compile(r\"never convert|zero[- ](?:conversions?|leads?|enquir(?:y|ies)|inquir(?:y|ies)|sales|bookings?)|\"\n                   r\"no (?:conversions?|leads|enquir(?:y|ies)|inquir(?:y|ies)|sales|bookings)|0 conversions?|\"\n                   r\"without (?:a |any )?(?:conversions?|leads?|enquir(?:y|ies))|did(?:n't| not) convert|\"\n                   r\"(?:non|zero)-?converting\", re.I)\nWASTE_WORDS = re.compile(r\"wast|never convert|zero[- ]conv|no conv|zero[- ](?:lead|enquir)|no (?:leads|enquir)|\"\n                         r\"(?:non|zero)-?converting\", re.I)\n# subjects we cannot rebuild from an export: subsets, segments, campaign types, unnamed groups\nSUBSET = re.compile(r\"\\b(?:the other|the rest|remaining|rest of|excluding|except|\"\n                    r\"other than|non-?brand|branded|brand|subtotal|only|just|of them|of which|each of|mobile|desktop|\"\n                    r\"tablet|devices?|weekends?|weekdays?|mornings?|evenings?|hours?|locations?|cit(?:y|ies)|\"\n                    r\"regions?|states?|countr(?:y|ies)|age|gender|audiences?|pmax|performance max|display|shopping|\"\n                    r\"video|demand gen|campaigns?|ad groups?|or (?:lower|below|less|fewer|higher|above|more)|low[- ]scor\\w*)\\b\", re.I)\nUNNAMED = re.compile(r\"\\b(?:one|a|an|another|some|each|any|the top|top|the best|the worst|the biggest|the largest|\"\n                     r\"the cheapest)\\s+(?:\\w+\\s+)?(?:search\\s+)?(?:terms?|keywords?|quer(?:y|ies)|campaigns?|\"\n                     r\"ad groups?|searches)\\b\", re.I)\nQUALIFIER = re.compile(r\"\\b(?:non-?brand|brand(?:ed)?|search(?!\\s+(?:terms?|quer(?:y|ies)))|pmax|performance max|\"\n                       r\"display|shopping|\"\n                       r\"video|demand gen|excluding|except|without|other than|only)\\b\", re.I)\n# \"the rows named together\" only when the text means them together; with no such rows, these words mean a subset\nGROUP_WORDS = re.compile(r\"\\b(?:combined|together|between them|both|these|those|they|them|their)\\b\", re.I)\n# \"five terms drove 71 of 85 conversions\": a counted set of rows, not the account, unless it is all of them\nCOUNTED = re.compile(r\"\\b(two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|\\d{1,3})\\s+(?:[a-z-]+\\s+){0,2}?\"\n                     r\"(?:search terms?|keywords?|terms|queries|searches)\\b\")\n# a list that goes on past the rows it names (\"..., plus teacher jobs\"; \"including X\"): the names are examples\nLIST_MORE = re.compile(r\"\\b(?:plus|including|includes|such as|among|e\\.g\\.|etc|and others|and more|led by)\\b\", re.I)\n# \"paused keywords\", \"tightly targeted keywords\", \"how-to queries\": rows the text describes but does not name\nSUBSET_NOUN = re.compile(r\"\\b([a-z][a-z'-]*)\\s+(?:keywords|search terms|search queries|terms|searches|queries)\\b\")\nNOT_A_SUBSET = {\"all\", \"the\", \"your\", \"our\", \"their\", \"its\", \"these\", \"those\", \"search\", \"total\", \"no\", \"zero\", \"non\",\n                \"any\", \"some\", \"each\", \"every\", \"other\", \"more\", \"fewer\", \"of\", \"and\", \"or\", \"in\", \"on\", \"to\", \"for\",\n                \"with\", \"from\", \"by\", \"at\", \"as\", \"into\", \"across\", \"between\", \"a\", \"an\", \"two\", \"three\", \"four\",\n                \"five\", \"six\", \"seven\", \"eight\", \"nine\", \"ten\", \"eleven\", \"twelve\", \"many\", \"several\", \"few\", \"both\",\n                \"which\", \"that\", \"were\", \"are\", \"is\", \"was\", \"have\", \"has\", \"had\", \"broad\", \"phrase\", \"exact\",\n                \"match\", \"matching\", \"same\", \"such\", \"whose\", \"where\", \"than\", \"word\", \"live\", \"active\", \"enabled\",\n                \"serving\", \"running\", \"current\"}\nPER_UNIT_GAP = re.compile(r\"\\s*(?:(?:to|-|\u2013|and)\\s*~?[$\u20ac\u00a3\u20b9]?\\s?[\\d,.]+[kKmM]?\\s*)?\")\nLABEL_COLON = re.compile(r\"[\\s*_]*:[\\s*_]*\")\n# \"$44 to $48\", \"9-14%\": the two ends of a range share their words\nRANGE = re.compile(rf\"(\\d[\\d,]*(?:\\.\\d+)?)\\s*%?\\s*(?:to|\u2013|-)\\s*~?{CUR}?\\s?(\\d[\\d,]*(?:\\.\\d+)?)\")\nCOST_WORD = re.compile(r\"\\bcosts?\\b|\\bcosting\\b\")  # \"cost $157.02\" may mean a price per lead as well as a total\n# a table on its side whose columns are the account: \"| Metric | July |\", \"| | Value |\"\nPERIOD_HEADER = re.compile(r\"^\\W*(?:values?|totals?|account|amounts?|figures?|results?|numbers?|this month|last month|\"\n                           r\"month|period|this period|last \\d+ days|jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\"\n                           r\"[a-z]*\\W*(?:\\d{4})?\\W*$\")\nOF_BASE = re.compile(r\"\\s*of\\s+(?:the\\s+|total\\s+|all\\s+|your\\s+|its\\s+|their\\s+|our\\s+)?\")\n# words that can stand before a number in its clause without naming anything: \"drove 31\", \"your account spent\"\nLABEL_STOP = set(\"\"\"a an the and or but yet nor so for of to in on at by with from into over under about around across\nbetween per each than then also just only still even nearly almost roughly approximately some any all both this that\nthese those its it they their them our your you we us which who whose what when where while whereas is was are were be\nbeen being has have had does did do got gets get gave give gives took take takes made make makes brought bring brings\ndrove drive drives used use uses spent spend spends cost costs paid pay pays earned earns generated generates delivered\ndelivers produced produces returned returns yielded yields converted converts scored scores ran runs sits stands came\ncomes went goes worth plus total overall average averaging avg rate share means giving leaving left more less fewer\nmost least top best worst biggest largest highest lowest alone combined together respectively one two three four five\nsix seven eight nine ten eleven twelve month months week weeks day days year last this next january february march\napril may june july august september october november december jan feb mar apr jun jul aug sep sept oct nov dec account\naccounts google ads adwords ppc paid there here now today currently ending ended landed fell rose dropped grew climbed\njumped declined increased decreased went moved stayed remained hit reached up down not exactly precisely actually really\nsimply already always never rather instead again once twice versus against compared though although because since\nafter before during within without via like such\"\"\".split())\nBRACKET_OPEN = re.compile(r\"\\s*\\(\\s*\")  # \"\u20b925,287 (17.5%)\": a bare share right after a figure, in brackets\nACCOUNT_LABEL = {\"cost\": \"cost\", \"clicks\": \"clicks\", \"conversions\": \"conversions\", \"impressions\": \"impressions\",\n                 \"ctr\": \"CTR\", \"cpc\": \"CPC\", \"cvr\": \"conversion rate\", \"cpa\": \"cost per conversion\"}\nCLAUSE_EDGE = re.compile(r\"(?<!\\d)[,;:](?!\\d)|[,;:](?=\\s)|\\.(?=[*_]{0,2}(?:\\s|$))|\\(|\\)\")  # not \"1,234\"\n# \"At this account's 11.0% conversion rate\", \"the account's $58.51 per conversion\": whatever else the sentence\n# compares or forecasts, this number is the account's own figure\nACCOUNT_ANCHOR = re.compile(r\"\\b(?:the|this|your) account(?:'s|s')?(?:\\s+[a-z./-]+){0,3}\\s*$\")\n# \"It converts, but at $90.63 each\": the one row the line named just before\nANAPHORA_START = re.compile(r\"^\\W*(?:it|its|this (?:term|keyword|search|query|one)|that (?:term|keyword|one))\\b\")\nCURRENT = {\"cost\": \"spend\", \"impressions\": \"impressions\", \"clicks\": \"clicks\", \"conversions\": \"conversions\",\n           \"ctr\": \"CTR\", \"cpa\": \"CPA\", \"cvr\": \"conversion rate\", \"cpc\": \"CPC\"}  # an account report's period figures\n\n\n@dataclass\nclass Claim:\n    line: int\n    written: str\n    value: float\n    verdict: str   # \"traced\" | \"mismatch\" | \"not in data\" | \"can't check\"\n    detail: str    # the fact it traced to, or why it did not\n    context: str\n\n\ndef _tolerance(num, mag, pct=False):\n    \"\"\"Half of one unit in the last digit written. '312' -> 0.5, '1.4k' -> 50, '16.8' -> 0.05.\n    Trailing zeros on large whole numbers are ambiguous ('4,200'), so they get at most 5% slack. Not on\n    percentages or numbers under 100: '60%' for 57% and '20 clicks' for 19 are wrong, not rounded.\"\"\"\n    s = num.replace(\",\", \"\")\n    mult = MAG.get((mag or \"\").strip().lower(), 1)\n    if \".\" in s:\n        return 10 ** -len(s.split(\".\", 1)[1]) / 2 * mult + 1e-9\n    stripped = s.rstrip(\"0\") or \"0\"\n    trailing = len(s) - len(stripped)\n    if pct or float(s) * mult < 100:\n        trailing = 0\n    half = 10 ** trailing / 2\n    if trailing:\n        half = min(half, 0.05 * float(s))\n    return half * mult + 1e-9\n\n\ndef _metric_spans(text):\n    spans = []\n    for prio, (metric, rx) in enumerate(METRIC_WORDS):\n        spans += [(m.start(), m.end(), metric, prio) for m in rx.finditer(text)]\n    return [a for a in spans\n            if not any(b[0] <= a[0] and a[1] <= b[1] and (b[1] - b[0]) > (a[1] - a[0]) for b in spans)]\n\n\ndef _evidence(text, spans, start, end, kind, numbers, partner=None, bounds=None, limit=45):\n    \"\"\"Every metric word near a number, ranked by distance. A clause break or an \"and\" makes a word\n    farther, and a dollar figure only listens to money words: it is never a click count or a rate.\n    A word with another number between it and this one belongs to that number (\"$1,361 / 31 conversions /\n    $43.90 CPA\": CPA is $43.90's), except a number's partner: \"from $45 to $58\" and \"60 of 85 conversions\"\n    share their words. A word in another sentence never counts.\"\"\"\n    found = {}\n    for s, e, metric, prio in spans:\n        if kind == \"money\" and metric not in MONEY_METRICS or kind != \"plain\" and metric in (\"terms\", \"days\"):\n            continue\n        if bounds and not (bounds[0] <= s < bounds[1]):\n            continue\n        lo, hi = (end, s) if s >= end else ((e, start) if e <= start else (None, None))\n        if lo is None:\n            continue\n        between = text[lo:hi]\n        if len(between) > limit or \";\" in between or between.count(\"(\") != between.count(\")\"):\n            continue  # \"...($157.02 each); its twin gets 22\": \"each\" is the bracket's, and the clause is over\n        if any(lo <= a < hi and a != partner for a, _ in numbers):\n            continue\n        if kind == \"pct\" and s >= end and OF_BASE.fullmatch(between):\n            rank = (0, prio)  # \"59% of spend\": the share is of the metric named right after it\n        elif kind == \"money\" and metric in (\"cpa\", \"cpc\") and s >= end and PER_UNIT_GAP.fullmatch(between):\n            rank = (0, prio)  # \"$45.82 a lead\", \"$44 to $48 a lead\": a price per lead, whatever \"cost\" said before\n        elif s < start and LABEL_COLON.fullmatch(between):\n            rank = (1, prio)  # \"Spend: $4,973.64\": a label and its value\n        else:\n            rank = (len(between) + (25 if CLAUSE_BREAK.search(between) else 0)\n                    + (10 if CONJUNCTION.search(between) else 0), prio)\n        found[metric] = min(rank, found.get(metric, rank))\n    return found\n\n\ndef _entities_in(low, entities):\n    found = []\n    for ent in entities:\n        i = low.find(ent)\n        while i != -1:\n            j = i + len(ent)\n            bounded = (i == 0 or not low[i - 1].isalnum()) and (j == len(low) or not low[j].isalnum())\n            negated = low[max(0, i - 4):i] in (\"non-\", \"non \")  # \"non-brand\" is everything but the Brand campaign\n            if bounded and not negated and not any(s <= i and j <= e for s, e, _ in found):\n                found.append((i, j, ent))\n            i = low.find(ent, i + 1)\n    return found\n\n\ndef _quoted(low, all_entities, found):\n    \"\"\"Rows named in quotes, at any length: \u201c\u65e5\u672c\u201d or \"tv\" is a name when it is exactly a row.\"\"\"\n    out = []\n    for m in QUOTED.finditer(low):\n        name = \" \".join(m.group(1).split()).strip(\" *\")\n        if name in all_entities and not any(s <= m.start(1) < e for s, e, _ in found + out):\n            out.append((m.start(1), m.end(1), name))\n    return out\n\n\ndef _row_name(line, all_entities):\n    \"\"\"The row a table line is about: its first cell, when that cell is exactly a row in the data. Exact, so a\n    short name counts here (\"got\", \"tv\") though it is too short to look for in running text. Works for markdown\n    tables and for the \"cell | cell |\" lines the app reads off a finished PDF.\"\"\"\n    if \"|\" not in line:\n        return None\n    first = line.strip().strip(\"|\").split(\"|\", 1)[0].strip(\" *\u201c\u201d\\\"'`\").lower()\n    if first in all_entities:\n        return first\n    kind = re.match(r\"(broad|exact|phrase)(?:\\s+match)?\\b(?!\\s*(?:and|&|/|or|\\+))\", first)\n    return f\"{kind.group(1)} match\" if kind and f\"{kind.group(1)} match\" in all_entities else None\n\n\ndef _mask(text, spans):\n    chars = list(text)\n    for s, e, _ in spans:\n        chars[s:e] = \" \" * (e - s)\n    return \"\".join(chars)\n\n\ndef _cells(line):\n    out, start = [], None\n    for i, ch in enumerate(line):\n        if ch == \"|\":\n            if start is not None:\n                out.append((start, i))\n            start = i + 1\n    return out\n\n\ndef _tables(lines):\n    \"\"\"line index -> [(cell start, cell end, header text)] for each markdown table body row.\"\"\"\n    ctx, i = {}, 0\n    while i < len(lines):\n        if lines[i].lstrip().startswith(\"|\") and i + 1 < len(lines) and TABLE_SEP.match(lines[i + 1]):\n            headers = [lines[i][s:e].strip() for s, e in _cells(lines[i])]\n            j = i + 2\n            while j < len(lines) and lines[j].lstrip().startswith(\"|\"):\n                ctx[j] = [(s, e, headers[k] if k < len(headers) else \"\")\n                          for k, (s, e) in enumerate(_cells(lines[j]))]\n                j += 1\n            i = j\n        else:\n            i += 1\n    return ctx\n\n\ndef _header_metric(header):\n    low = header.lower()\n    low = _mask(low, [(m.start(), m.end(), \"\") for m in NEVER.finditer(low) if not m.group(0)[0].isdigit()])\n    spans = _metric_spans(low)\n    return min(spans, key=lambda s: s[3])[2] if spans else None\n\n\ndef _small_count(line, m, cell, named):\n    \"\"\"Whether a whole number up to 12 is a claim to check: a click, conversion or impression count of a row\n    the text names, or of the whole account. A Clicks or Conversions column counts as the metric word.\"\"\"\n    if NOT_A_COUNT.search(line[:m.start()]):\n        return False\n    counted = (cell is not None and _header_metric(cell) in PERFORMANCE) or bool(SMALL_COUNT.match(line[m.end():]))\n    return counted and (bool(named) or bool(ACCOUNT_CUE.search(line)))\n\n\ndef _bases(facts):\n    \"\"\"Each row's own cost, clicks, conversions and impressions, and the account's: what group figures add up.\"\"\"\n    base, grand = {}, {}\n    for f in facts:\n        for metric, kind in ((\"cost\", \"money\"), (\"clicks\", \"count\"), (\"conversions\", \"count\"),\n                             (\"impressions\", \"count\")):\n            if f.metric != metric or f.kind != kind:\n                continue\n            if f.entity and f.label == f\"{metric} of '{f.entity}'\":\n                row = base.setdefault(f.entity.lower(), {\"level\": f.level})\n                row.setdefault(metric, f.value)  # the first is the row's total\n            elif not f.entity and f.label == f\"{metric} of the account\":\n                grand.setdefault(metric, f.value)\n    return base, grand\n\n\ndef _group_facts(members, base, grand):\n    \"\"\"Sum, rates and shares of rows named together. Like with like: search terms with search terms, a match\n    type with a match type, never a campaign plus the terms inside it.\"\"\"\n    uniq = [m for m in dict.fromkeys(members) if m in base]\n    terms = [m for m in uniq if base[m].get(\"level\") == \"row\"]\n    groups = [m for m in uniq if base[m].get(\"level\") == \"group\"]\n    pick = terms if len(terms) >= 2 else groups if len(groups) >= 2 else uniq if not terms and not groups else []\n    rows = [base[m] for m in pick]\n    if len(rows) < 2:\n        return []\n    s = {k: sum(r.get(k) or 0 for r in rows) for k in (\"cost\", \"clicks\", \"conversions\", \"impressions\")}\n    tag = f\"the {len(rows)} rows named together\"\n    out = [Fact(f\"cost of {tag}\", s[\"cost\"], \"money\", \"cost\", GROUP),\n           Fact(f\"clicks of {tag}\", s[\"clicks\"], \"count\", \"clicks\", GROUP),\n           Fact(f\"conversions of {tag}\", s[\"conversions\"], \"count\", \"conversions\", GROUP)]\n    if s[\"impressions\"]:\n        out += [Fact(f\"impressions of {tag}\", s[\"impressions\"], \"count\", \"impressions\", GROUP),\n                Fact(f\"CTR of {tag}\", s[\"clicks\"] / s[\"impressions\"] * 100, \"pct\", \"ctr\", GROUP)]\n    if s[\"clicks\"]:\n        out += [Fact(f\"CPC of {tag}\", s[\"cost\"] / s[\"clicks\"], \"money\", \"cpc\", GROUP),\n                Fact(f\"conversion rate of {tag}\", s[\"conversions\"] / s[\"clicks\"] * 100, \"pct\", \"cvr\", GROUP)]\n    if s[\"conversions\"]:\n        out.append(Fact(f\"cost per conversion of {tag}\", s[\"cost\"] / s[\"conversions\"], \"money\", \"cpa\", GROUP))\n    for metric in (\"cost\", \"clicks\", \"conversions\"):\n        if grand.get(metric):\n            out.append(Fact(f\"share of total {metric} of {tag}\", s[metric] / grand[metric] * 100, \"pct\", metric, GROUP))\n    return out\n\n\ndef _cant_check(clause):\n    \"\"\"Why a number that traced to nothing is not a figure an export holds, judged on its own clause.\"\"\"\n    if WHATIF.search(clause):\n        return \"a forecast, what-if or calculation an export cannot confirm: check it yourself\"\n    if TARGET.search(clause):\n        return \"a target, threshold or comparison, not a figure in your data\"\n    return None\n\n\ndef _show(f):\n    if f.kind == \"money\":\n        return f\"{f.value:,.2f}\"\n    if f.kind == \"pct\":\n        return f\"{f.value:.2f}%\" if abs(f.value) < 1 else f\"{f.value:.1f}%\"\n    return f\"{f.value:,.1f}\" if f.value % 1 else f\"{f.value:,.0f}\"\n\n\ndef _canonical(subject, metric, kind, facts, sentence):\n    \"\"\"The figure a subject has for a metric, when there is exactly one sensible one to compare with.\"\"\"\n    who, name = subject\n    if who == \"account\" and kind == \"pct\" and VERB.search(sentence) and not FROM_TO.search(sentence):\n        label = f\"{CURRENT.get(metric, metric)} change\"  # \"CPA down 20%\": the change on the period before\n        change = next((f for f in facts if not f.entity and f.label == label), None)\n        if change:\n            return change\n    want = \"money\" if metric in MONEY_METRICS else (\"pct\" if metric in (\"ctr\", \"cvr\") else \"count\")\n    if kind == \"pct\" and metric in (\"cost\", \"clicks\", \"conversions\"):\n        want = \"pct\"  # a share of total cost, clicks or conversions\n    if kind != \"plain\" and kind != want:\n        return None\n    pool = [f for f in facts if f.metric == metric and f.kind == want]\n    if who == \"account\":\n        if metric == \"terms\":\n            return next((f for f in facts if not f.entity and f.label.endswith(\" in this export\")), None)\n        labels = {f\"{ACCOUNT_LABEL.get(metric, metric)} of the account\", f\"current {CURRENT.get(metric, metric)}\"}\n        return next((f for f in pool if not f.entity and f.label in labels), None)\n    if who == \"never\":\n        return next((f for f in pool if not f.entity and \"with no conversions\" in f.label), None)\n    if who == \"group\":\n        return next((f for f in pool if f.entity == GROUP), None)  # the sum, or for a percentage the share\n    own = [f for f in pool if f.entity.lower() == name]\n    if want == \"pct\" and metric in (\"cost\", \"clicks\", \"conversions\"):\n        waste = [f for f in own if \"with no conversions\" in f.label]\n        share = [f for f in own if \"share of total\" in f.label]\n        own = waste if (waste and WASTE_WORDS.search(sentence)) else share\n    return own[0] if own else None\n\n\ndef _settle(value, kind, about, subject, facts, sentence, detail=\"\"):\n    \"\"\"For a number that traced to nothing: flag it only when we know what it claims to be, and say what that\n    figure really is; otherwise it is the audit's own calculation, which we cannot confirm.\"\"\"\n    open_calc = (\"can't check\", \"the audit's own calculation over rows OpenPPC cannot rebuild: ask it to show \"\n                                \"which rows it added up\")\n    if subject is None:\n        return open_calc\n    if subject[0] == \"unnamed\":\n        return \"can't check\", \"about a row the text doesn't name: name the search term or campaign to check it\"\n    if subject[0] == \"earlier\":\n        return \"can't check\", \"an earlier figure: an export of one period cannot confirm it\"\n    if about is None:\n        if subject[0] == \"row\":  # a named row, and none of its figures is this number\n            return \"not in data\", (detail if detail.startswith(\"that figure is the\")\n                                   else f\"none of the figures for '{subject[1]}' is this number\")\n        return open_calc\n    fact = _canonical(subject, about, kind, facts, sentence)\n    if fact is None:\n        return open_calc\n    return \"not in data\", f\"no: the {fact.label} is {_show(fact)}\"\n\n\ndef _judge(value, tol, kind, evidence, ents, facts, implied=False, loose=False):\n    \"\"\"Weigh every fact the number could be, then pick the one the sentence most likely means.\n\n    The closest metric word says what the number is about. A row the sentence names counts unless the\n    metric is one no row has (\"Acme audit, last 30 days\": the brand is also a search term, but\n    days belong to the account). The named row's own figure on another metric is a mismatch, but only\n    when the text names the row itself: a row carried over from \"this term\" is a guess, never grounds to accuse.\n    A mismatch also needs the metric word right at the number (\"22 conversions\", \"CTR of 7.4%\", \"Spend: $312\"):\n    a word further off may belong to something else, so that is \"can't check\", with the figure it matches.\n    \"\"\"\n    cands = [f for f in facts if (kind == \"plain\" or f.kind == kind) and abs(f.value - value) <= tol]\n    if not cands:\n        return \"not in data\", \"no figure in your files matches it at the precision written\"\n    about = min(evidence, key=evidence.get) if evidence else None\n    named = set() if about in ACCOUNT_ONLY else ents\n\n    strong = about is not None and evidence[about][0] <= 6\n\n    def fits(f):\n        return (about is None or f.metric in GENERIC or f.metric == about\n                or (loose and f.metric in MONEY_METRICS))  # \"cost $157.02\": a total, or the cost of each lead\n\n    def accuse(f):\n        if strong:\n            return \"mismatch\", f\"that figure is the {f.label}\"\n        return \"can't check\", f\"it matches the {f.label}: check which figure the text means\"\n\n    def closest(fs):\n        return min(fs, key=lambda f: (abs(f.value - value), evidence.get(f.metric, (99, 99))))\n\n    if named:\n        own = [f for f in cands if f.entity.lower() in named]\n        if any(fits(f) for f in own):\n            return \"traced\", closest([f for f in own if fits(f)]).label\n        overall = [f for f in cands if not f.entity and fits(f)]\n        if overall:  # an account figure that fits the words beats a named row's figure on another metric\n            return \"traced\", closest(overall).label\n        if own and not implied:\n            return accuse(closest(own))\n        other = closest(cands)\n        if not other.entity:  # an account figure on another metric: a mix-up we can name for sure\n            return accuse(other)\n        # another row's figure: a wrong row, or a row named in a way we did not recognise; flag it, don't accuse\n        return \"not in data\", f\"that figure is the {other.label}, not a figure of what the text names\"\n    good = [f for f in cands if fits(f)]\n    account = [f for f in good if not f.entity]\n    if account:  # no row named: only an account-level figure can back it\n        return \"traced\", closest(account).label\n    if good:  # only some row's figure, and the text never says which row: chance until it names one\n        return \"not in data\", (f\"only a row the text doesn't name has this figure (the {closest(good).label}); \"\n                               \"name the search term or campaign to check it\")\n    account = [f for f in cands if not f.entity]\n    if account:  # \"309 conversions\" when the account had 309 clicks\n        return accuse(closest(account))\n    # the only match is some unnamed row's figure on another metric: a coincidence, not a mix-up\n    return \"not in data\", \"no figure in your files matches it at the precision written\"\n\n\ndef _contradictions(lines):\n    found = []\n    for n, line in enumerate(lines, 1):\n        for m in FROM_TO.finditer(line):\n            verbs = list(VERB.finditer(line[max(0, m.start() - 45):m.start()]))\n            if not verbs:\n                continue\n            verb = verbs[-1].group(1).lower()\n            a, b = float(m.group(1).replace(\",\", \"\")), float(m.group(2).replace(\",\", \"\"))\n            if a == b:\n                continue\n            said_down = verb in DOWN_VERBS\n            if said_down != (b < a):\n                movement = \"a fall\" if b < a else \"a rise\"\n                found.append((n, f\"says '{verb}', but {m.group(1)} to {m.group(2)} is {movement}\", line.strip()[:140]))\n    return found\n\n\ndef _names(line, low, entities, all_entities, families):\n    \"\"\"The rows a line names: in running text (four letters or more), in quotes, as a table row's first cell,\n    or as a match type (\"broad keywords\"; \"exact/phrase\" names both together, as one group).\"\"\"\n    ents = _entities_in(low, entities)\n    ents += _quoted(low, all_entities, ents)\n    row = _row_name(line, all_entities)\n    named = [(s, e, n) for s, e, n in ents]\n    if row and not any(n == row for _, _, n in named):\n        named.append((0, 0, row))\n    unions = []\n    for m in MATCH_ALIAS.finditer(low):\n        if any(s <= m.start() < e for s, e, _ in ents):\n            continue\n        before = low[:m.start()].rstrip(\" *(\")\n        if any(before.endswith(n) for _, _, n in ents):  # \"plumber near me (exact)\" is that term's match type\n            continue\n        words = [w.lower() for w in m.groups() if w]\n        members = [e for w in words for e in families.get(w, [])]\n        if len(words) == 2:\n            unions.append((m.start(), m.end(), members))\n        else:\n            named += [(m.start(), m.end(), e) for e in members]\n    return ents, named, unions\n\n\ndef _column(header, entities, all_entities, families):\n    \"\"\"What a column of a table on its side is about, from its header: one row or match type (\"Broad (6 keywords)\"),\n    two match types together (\"Exact/phrase\"), the account (\"July\", \"Value\"), or None when we can't tell.\"\"\"\n    low = \" \".join(header.lower().replace(\"*\", \" \").split())\n    kind = re.fullmatch(r\"(broad|exact|phrase)(?:\\s+match)?(?:\\s*\\(.*\\))?\", low)\n    if kind and f\"{kind.group(1)} match\" in all_entities:\n        return (\"row\", f\"{kind.group(1)} match\")\n    _, named, unions = _names(low, low, entities, all_entities, families)\n    if unions:\n        return (\"group\", unions[0][2])\n    found = list(dict.fromkeys(n for _, _, n in named))\n    if len(found) == 1:\n        return (\"row\", found[0])\n    if not found and (not low or PERIOD_HEADER.match(low)):\n        return (\"account\", None)\n    return None\n\n\ndef _counted(sentence, own):\n    \"\"\"Whether the sentence is about a counted set of rows (\"five terms\", \"3 broad keywords\") other than all of them.\n    The count that is itself the number being checked does not count.\"\"\"\n    for m in COUNTED.finditer(sentence):\n        if m.start() <= own < m.end():\n            continue\n        before = sentence[:m.start()].rstrip().split()[-1:] or [\"\"]\n        if before[0] not in (\"all\", \"your\", \"account's\", \"the\"):\n            return True\n    return False\n\n\ndef _subset_noun(text):\n    \"\"\"Whether the text describes rows without naming them: \"paused keywords\", \"tightly targeted keywords\".\"\"\"\n    return any(m.group(1) not in NOT_A_SUBSET and m.group(1).split(\"-\")[0] not in NOT_A_SUBSET\n               for m in SUBSET_NOUN.finditer(text))\n\n\ndef _labelled(before):\n    \"\"\"Whether the words before a number in its clause name something we did not recognise: \"IAS salary \u20b92,930\",\n    \"hostel (\u20b92,710)\". The number belongs to that, not to a row named elsewhere in the sentence.\"\"\"\n    return any(w not in LABEL_STOP for w in re.findall(r\"[a-z][a-z'-]{2,}\", before))\n\n\ndef _subject(named, unions, row, here, implied, lo, hi, a, b, start, sentence, clause, cell, line, base, about,\n             groups=1, before=\"\"):\n    \"\"\"What a number claims to be a figure of, read from the closest words out: a table row; the one row or match\n    type its own clause names, or the rows it names together; the terms that never converted; the one row or the\n    rows its sentence names; or else the whole account. None when it is a slice we cannot rebuild (\"Search broad\n    match\", \"excluding brand\", \"paused keywords\", a list that goes on with \"plus ...\"), or a row only implied by\n    \"this\". The flag that follows is only as sure as this reading, so every doubt answers None.\"\"\"\n    if implied:\n        return None\n    header = (cell or \"\").lower()\n    first = line.strip().strip(\"|\").split(\"|\", 1)[0].strip(\" *\").lower() if \"|\" in line else \"\"\n    if row:\n        return None if SUBSET.search(header) else (\"row\", row)\n    if cell is not None:  # a table row we could not name: its first cell says what it is, or we can't tell\n        if QUALIFIER.search(first) or SUBSET.search(header + \" \" + first):\n            return None  # \"All Search\", \"Non-brand\"\n        if about in NEVER_METRICS and (NEVER.search(first) or WASTE_WORDS.search(first)):\n            return (\"never\", None)\n        return (\"account\", None) if ACCOUNT_CUE.search(first) or PERIOD_HEADER.match(first) else None\n    # names after \"including\" or \"plus\", when that word comes after the number, are examples of what it covers\n    cut = min([a + m.start() for m in LIST_MORE.finditer(sentence) if a + m.start() > start], default=len(line) + 1)\n    in_clause = list(dict.fromkeys(n for s, _, n in named if lo <= s < hi and s < cut))\n    in_sentence = list(dict.fromkeys(n for s, _, n in named if a <= s < b and s < cut))\n    clause_union = any(lo <= s < hi for s, _, _ in unions)\n    sentence_union = any(a <= s < b for s, _, _ in unions)\n\n    def one(name):\n        if base.get(name, {}).get(\"level\") != \"row\" and (QUALIFIER.search(sentence) or _subset_noun(sentence)):\n            return None  # \"Search broad match\", \"water heater keywords ... broad\": a slice of the match type\n        return (\"row\", name)\n\n    def together():\n        if not here or groups != 1 or QUALIFIER.search(sentence) or LIST_MORE.search(sentence):\n            return None  # a slice of these rows, a list that goes on past them, or two groups to choose from\n        return (\"group\", GROUP)\n\n    if _subset_noun(clause):\n        return None\n    if len(in_clause) == 1 and not clause_union:\n        return one(in_clause[0])\n    if in_clause or clause_union:\n        return together()\n    named_before = list(dict.fromkeys(n for s, _, n in named if s < a))\n    if not in_sentence and ANAPHORA_START.search(sentence) and len(named_before) == 1:\n        return one(named_before[0])\n    if about in NEVER_METRICS and (NEVER.search(sentence) or WASTE_WORDS.search(sentence)):\n        return (\"never\", None)\n    if UNNAMED.search(clause):\n        return (\"unnamed\", None)\n    if WHATIF.search(sentence) or TARGET.search(sentence) or _labelled(before):\n        return None  # the sentence compares or forecasts, or the number has a label of its own we don't know\n    if SUBSET.search(sentence) or _subset_noun(sentence) or (not here and (GROUP_WORDS.search(sentence)\n                                                                            or _counted(sentence, start - a))):\n        return None\n    if UNNAMED.search(sentence):\n        return (\"unnamed\", None)\n    if len(in_sentence) == 1 and not sentence_union:\n        return one(in_sentence[0])\n    if in_sentence or sentence_union or (here and GROUP_CUE.search(sentence)):\n        return together()\n    return (\"account\", None)\n\n\ndef trace(text, facts):\n    \"\"\"Return (claims, contradictions) for every checkable number in the text.\"\"\"\n    facts = list(facts)\n    entities = sorted({f.entity.lower() for f in facts if len(f.entity) >= 4}, key=len, reverse=True)\n    all_entities = {f.entity.lower() for f in facts if f.entity}\n    base, grand = _bases(facts)\n    families = {w: sorted(e for e in base if e in MATCH_TYPES and e.startswith(w)) for w in (\"broad\", \"exact\", \"phrase\")}\n    lines = text.splitlines()\n    tables = _tables(lines)\n    parsed = [_names(line, line.lower(), entities, all_entities, families) for line in lines]\n    under = {}  # a heading's line -> the rows its numbers usually sum up: its first list, or its whole section\n    for i, line in enumerate(lines):\n        if line.lstrip().startswith(\"#\"):\n            section, first, in_list, done, j = [], [], False, False, i + 1\n            while j < len(lines) and not lines[j].lstrip().startswith(\"#\"):\n                rows = [n for _, _, n in parsed[j][1] if n in base]\n                section += rows\n                if not done and LIST_LINE.match(lines[j]) and rows:\n                    first, in_list = first + rows, True\n                elif in_list and lines[j].strip() and not LIST_LINE.match(lines[j]):\n                    done = True\n                j += 1\n            under[i] = [first, section]\n    claims, history, block, carried, quiet = [], [], [], set(), 0\n    for i, line in enumerate(lines):\n        low = line.lower()\n        ents, named, unions = parsed[i]\n        row = _row_name(line, all_entities)\n        masked = _mask(low, ents)\n        # \"zero conversions\" says which rows, not what a number is: \"\u20b924,427 on nine zero-conversion terms\" is a cost\n        spans = _metric_spans(_mask(masked, [(m.start(), m.end(), \"\") for m in NEVER.finditer(masked)\n                                             if not m.group(0)[0].isdigit()]))\n        # the line with metric words, numbers and markup blanked: what is left before a number is its label, if any\n        wordless = _mask(masked, [(sp[0], sp[1], \"\") for sp in spans]\n                         + [(m.start(), m.end(), \"\") for m in NUM.finditer(masked)])\n        skip = {m.start(1) for m in MONTH_DAY.finditer(line)}\n        skip |= {p for m in CODE_SPAN.finditer(line) for p in range(m.start(), m.end())}\n        marker = LIST_MARKER.match(line)\n        if marker:\n            skip.add(marker.start(1))\n        names = {n for _, _, n in named}\n        if row:  # a table row is about its first cell; its match type column is a description, not a subject\n            names = {n for n in names if n not in MATCH_TYPES or n == row}\n        implied = False\n        if not names and ANAPHORA.search(low) and carried:\n            names, implied = set(carried), True  # \"This term generated 2 conversions\": the row named just before\n        numbers = [(m.start(\"cur\") if m.group(\"cur\") else m.start(\"num\"), m.end()) for m in NUM.finditer(line)]\n        partners = {}  # \"from $45 to $58\" and \"60 of 85 conversions\": one number may use its partner's words\n        earlier = {m.start(1) for m in FROM_TO.finditer(masked)}  # \"fell from 9%\": a figure from before the export\n        for m in FROM_TO.finditer(masked):\n            partners[m.start(2)] = next((a for a, b in numbers if a <= m.start(1) < b), m.start(1))\n        for m in OF_PAIR.finditer(masked):\n            partners.setdefault(m.start(1), next((a for a, b in numbers if a <= m.start(2) < b), m.start(2)))\n        for m in RANGE.finditer(masked):\n            partners.setdefault(m.start(1), next((a for a, b in numbers if a <= m.start(2) < b), m.start(2)))\n            partners.setdefault(m.start(2), next((a for a, b in numbers if a <= m.start(1) < b), m.start(1)))\n        # the rows each sentence takes together, and the figures they add up to\n        sentences, pos = [], 0\n        for cut in [m.start() for m in SENTENCE.finditer(line)] + [len(line)]:\n            sentences.append((pos, cut))\n            pos = cut\n        local, prev_rows = [], []\n        for a, b in sentences:\n            rows = [n for s, _, n in named if a <= s < b and n in base]\n            sentence = low[a:b]\n            group = rows if len(set(rows)) >= 2 else []\n            if not group and GROUP_CUE.search(sentence):\n                n = THESE_N.search(sentence)\n                k = None\n                if n:\n                    w = n.group(1).lower()\n                    k = WORD_NUM.get(w) or (int(w) if w.isdigit() else None)\n                if k:  # \"these four\": the last four rows of one kind named before, or none at all\n                    order = list(dict.fromkeys(reversed(history)))\n                    for level in (\"row\", \"group\"):\n                        same = [n for n in order if base.get(n, {}).get(\"level\") == level]\n                        if len(same) >= k:\n                            group = same[:k]\n                            break\n                elif len(set(prev_rows)) >= 2:\n                    group = prev_rows\n                elif len(set(block)) >= 2:\n                    group = block\n            if not group and i in under and not rows:\n                for cand in under[i]:\n                    if len(set(cand)) >= 2:\n                        local.append((a, b, _group_facts(cand, base, grand)))\n            for s, e, members in unions:\n                if a <= s < b:\n                    local.append((a, b, _group_facts(members, base, grand)))\n            if group:\n                local.append((a, b, _group_facts(group, base, grand)))\n            prev_rows = rows or prev_rows\n        last = None  # the figure just before: a bare share in brackets after it is a share of it\n        for m in NUM.finditer(line):\n            pos = m.start(\"num\")\n            if pos in skip or any(s <= pos < e for s, e, _ in ents):\n                continue\n            raw, cur, mag, pct = m.group(\"num\"), m.group(\"cur\"), m.group(\"mag\"), bool(m.group(\"pct\"))\n            code = m.group(\"code\")\n            value = float(raw.replace(\",\", \"\")) * MAG.get((mag or \"\").strip().lower(), 1)\n            money = bool(cur or code)\n            plain = not (money or pct or mag)\n            kind = \"money\" if money else (\"pct\" if pct else \"plain\")\n            start = m.start(\"cur\") if cur else pos\n            here = [f for a, b, fs in local if a <= start < b for f in fs]\n            groups = sum(1 for a, b, fs in local if a <= start < b and fs)\n            seen = names | ({GROUP} if here else set())\n            cell = next((header for s, e, header in tables.get(i, []) if s <= start < e), None)\n            side = None  # a table on its side: metrics down the first column, what they are of across the top\n            if cell is not None and row is None and _header_metric(cell) in (None, \"terms\"):\n                metric = _header_metric(line.strip().strip(\"|\").split(\"|\", 1)[0].strip(\" *\").lower())\n                # the cell's own words come first: \"| Leads | 85 (from 732 clicks) |\"\n                own = _evidence(masked, spans, start, m.end(), kind, [n for n in numbers if n[0] != start],\n                                partners.get(pos), next(((s0, e0) for s0, e0, _ in tables[i] if s0 <= start < e0), None))\n                if metric and not own:\n                    side = (metric, _column(cell, entities, all_entities, families))\n                    col = side[1]\n                    if col and col[0] == \"group\":\n                        here, groups, seen = _group_facts(col[1], base, grand), 1, {GROUP}\n                    else:\n                        seen = {col[1]} if col and col[0] == \"row\" else set()\n            if plain and value <= 12 and not (side and side[0] in PERFORMANCE and seen) \\\n                    and not _small_count(line, m, cell, seen):\n                continue\n            if plain and \",\" not in raw and \".\" not in raw and 1900 <= value <= 2100:\n                continue\n            evidence = {}\n            if side:\n                if not (kind == \"money\" and side[0] not in MONEY_METRICS):\n                    evidence = {side[0]: (0, 0)}\n            elif cell is not None:\n                metric = _header_metric(cell)\n                if metric and not (kind == \"money\" and metric not in MONEY_METRICS):\n                    evidence = {metric: (0, 0)}\n            if not evidence:\n                bounds = next(((a, b) for a, b in sentences if a <= start < b), None)\n                others = [n for n in numbers if n[0] != start]\n                if kind == \"pct\" and last and BRACKET_OPEN.fullmatch(line[last[0]:start]):\n                    close = line.find(\")\", m.end())\n                    evidence = _evidence(masked, spans, start, m.end(), kind, others, partners.get(pos),\n                                         (start, close if close != -1 else len(line)))\n                    if not evidence:  # \"\u20b925,287 (17.5%)\": a share of that cost; \"113 clicks (15%)\": of the clicks\n                        evidence = {\"cost\": (0, 0)} if last[1] == \"money\" else dict(last[2])\n                else:\n                    evidence = _evidence(masked, spans, start, m.end(), kind, others, partners.get(pos), bounds)\n            last = (m.end(), kind, evidence)\n            tol = _tolerance(raw, mag, pct)\n            if kind == \"money\" and value >= 100:\n                tol = max(tol, value * 0.001)  # \"\u20b91,087\" for 1,086.48: a slip in the last digit, not a wrong figure\n            about = min(evidence, key=evidence.get) if evidence else None\n            loose = about == \"cost\" and kind == \"money\" and bool(COST_WORD.search(masked[max(0, start - 20):start]))\n            verdict, detail = _judge(value, tol, kind, evidence, seen, facts + here, implied and not here, loose)\n            if verdict != \"traced\":\n                a, b = next(((a, b) for a, b in sentences if a <= start < b), (0, len(line)))\n                edges = [e.start() for e in CLAUSE_EDGE.finditer(masked)]\n                lo = max([e for e in edges if e < start], default=a - 1) + 1\n                if lo > 0 and masked[lo - 1] == \"(\":  # \"pipe repair ($269.40, 38 clicks)\": the row before it\n                    lo = max([e for e in edges if e < lo - 1], default=a - 1) + 1\n                hi = min([e for e in edges if e >= m.end()], default=len(line))\n                lo, hi = max(lo, a), min(hi, b)\n                anchored = bool(ACCOUNT_ANCHOR.search(masked[lo:start]))\n                why = None if anchored else _cant_check(masked[lo:hi])  # names blanked: \"free ... estimate\" is a term\n                if why:\n                    verdict, detail = \"can't check\", why\n                elif not anchored and detail.startswith(\"only a row the text doesn't name\") and tol < 0.005 * value:\n                    verdict = \"can't check\"  # too exact to be chance: a real row's figure, under a name we don't know\n                elif verdict == \"not in data\":\n                    about = min(evidence, key=evidence.get) if evidence else None\n                    if about is None:  # \"We spent $1.4k, exactly $1,361.04, not $1,500\": the sentence's one metric\n                        said = {mt for s0, _, mt, _ in spans if a <= s0 < b and mt not in (\"terms\", \"days\")}\n                        if len(said) == 1 and (kind != \"money\" or said <= MONEY_METRICS):\n                            about = said.pop()\n                    column = side and side[1] and ((\"group\", GROUP) if side[1][0] == \"group\" else side[1])\n                    subject = ((\"earlier\", None) if pos in earlier else (\"account\", None) if anchored else\n                               column if side else _subject(named, unions, row, here, implied, lo, hi, a, b, start, masked[a:b],\n                                        masked[lo:hi], cell, line, base, about, groups, wordless[lo:start]))\n                    verdict, detail = _settle(value, kind, about, subject, facts + here, masked[a:b], detail)\n            a, b = next(((a, b) for a, b in sentences if a <= start < b), (0, len(line)))\n            claims.append(Claim(i + 1, m.group(0).strip(), value, verdict, detail, _quote(line, a, b, start, m.end())))\n        rows_here = [n for _, _, n in named if n in base] + ([row] if row and row in base else [])\n        if rows_here:\n            history += rows_here\n            block = (block if quiet == 0 else []) + rows_here\n            carried = set(rows_here)\n            quiet = 0\n        elif line.strip():\n            quiet += 1\n    return claims, _contradictions(lines)\n\n\ndef _quote(line, a, b, start, end, width=200):\n    \"\"\"The sentence a number is in, cut to whole words around the number when it is longer than 200 characters.\"\"\"\n    text = line[a:b].strip()\n    if len(text) <= width:\n        return text\n    lo = max(a, min(start - width // 2, b - width))\n    hi = min(b, lo + width)\n    lo = line.rfind(\" \", a, lo + 1) + 1 if lo > a else a  # whole words only\n    cut = line.find(\" \", hi)\n    hi = b if cut == -1 or cut >= b else cut\n    return (\"...\" if lo > a else \"\") + line[lo:hi].strip() + (\"...\" if hi < b else \"\")\n\n\ndef _esc(text):\n    return str(text).replace(\"|\", \"\\\\|\")\n\n\ndef render_check(claims, contradictions):\n    traced = [c for c in claims if c.verdict == \"traced\"]\n    flagged = [c for c in claims if c.verdict in (\"mismatch\", \"not in data\")]\n    unchecked = [c for c in claims if c.verdict == \"can't check\"]\n    mismatched = sum(c.verdict == \"mismatch\" for c in claims)\n    out = [\"# Number check\", \"\",\n           f\"**{len(claims)} numbers found: {len(traced)} traced to your data, {mismatched} mismatched, \"\n           f\"{len(flagged) - mismatched} not in your data\"\n           + (f\", {len(unchecked)} can't be checked from an export\" if unchecked else \"\") + \".** \"\n           f\"{len(contradictions)} sentence(s) contradict their own numbers.\"]\n    if not flagged and not contradictions:\n        out += [\"\", \"Every number an export can confirm traces back to your data. That checks the numbers, \"\n                    \"not the advice.\"]\n    if flagged:\n        out += [\"\", \"## Needs attention\", \"\", \"| Line | As written | Verdict | Detail | Context |\",\n                \"|---|---|---|---|---|\"]\n        out += [f\"| {c.line} | {_esc(c.written)} | {c.verdict} | {_esc(c.detail)} | {_esc(c.context)} |\"\n                for c in flagged]\n    if contradictions:\n        out += [\"\", \"## Contradictions\", \"\", \"| Line | Problem | Context |\", \"|---|---|---|\"]\n        out += [f\"| {n} | {_esc(p)} | {_esc(ctx)} |\" for n, p, ctx in contradictions]\n    if unchecked:\n        out += [\"\", \"## Can't be checked from an export\", \"\", \"| Line | As written | Why | Context |\",\n                \"|---|---|---|---|\"]\n        out += [f\"| {c.line} | {_esc(c.written)} | {_esc(c.detail)} | {_esc(c.context)} |\" for c in unchecked]\n        out += [\"\", \"_To check these, ask whoever wrote the audit to show, for each one, which rows of the export it \"\n                    \"added up, divided or compared._\"]\n    if traced:\n        out += [\"\", \"## Traced\", \"\", \"| Line | As written | Traced to |\", \"|---|---|---|\"]\n        out += [f\"| {c.line} | {_esc(c.written)} | {_esc(c.detail)} |\" for c in traced]\n    out += [\"\", \"_Not in your data means nothing in the files you provided backs that figure: no account figure \"\n                \"matches it, and no row the text names. It may be wrong, rounded differently, about a row the text \"\n                \"doesn't name, or from data you did not include. Can't be checked means it is a target, a forecast, \"\n                \"a what-if, or the audit's own working over rows an export can't rebuild._\"]\n    return \"\\n\".join(out)\n","openppc/engine/waste_model.py":"\"\"\"Waste model: how sure can we be that a search term is bad, not just unlucky?\n\nA fixed dollar threshold treats a term with 3 clicks and one with 300 the same way. This model\nasks the account instead. Nobody knows a search term's true conversion rate, but the account's\nown terms show how rates spread around the account average (an empirical-Bayes beta prior).\nEach term's clicks and conversions then update that prior, and the answer is the probability\nthat the term truly converts at less than half the account's rate: P(bad).\n\nWith few clicks, P(bad) stays close to the account's baseline whatever the term cost. With\nmany clicks and no conversions it climbs toward 1. Adding up 1 - P(bad) over the flagged terms\nsays how many of the flags are probably bad luck.\n\nStandard library only. The regularized incomplete beta function is the continued fraction in\nNumerical Recipes (Press et al., 3rd edition, section 6.4).\n\"\"\"\nimport math\n\nBAD_RATIO = 0.5                 # \"bad\" means converting at less than this share of the account's rate\nCONFIDENT = 0.9                 # flag a term once P(bad) reaches this\nMIN_CONCENTRATION = 1.0         # the prior's strength (alpha + beta) stays in this range: the floor keeps\nMAX_CONCENTRATION = 10_000.0    # the prior from saying most terms are bad before any click, the cap bounds the search\n\n\ndef fit_prior(terms):\n    \"\"\"Beta prior (alpha, beta) for the account's term-level conversion rates.\n\n    terms: (clicks, conversions) pairs. The mean is the account's own conversion rate; the\n    spread is fit by maximum marginal likelihood (the beta-binomial model), which weighs each\n    term by what its clicks can actually say, so one big brand term cannot set the spread and\n    an account whose terms really are alike is not mistaken for a noisy one. None if there is\n    nothing to learn from (no clicks, or no conversions at all).\"\"\"\n    counts = {}\n    for n, k in terms:\n        if n > 0:\n            key = (n, min(k, n))\n            counts[key] = counts.get(key, 0) + 1\n    clicks = sum(n * c for (n, _), c in counts.items())\n    conversions = sum(k * c for (_, k), c in counts.items())\n    if not clicks or not conversions or conversions >= clicks:\n        return None\n    mu = conversions / clicks\n\n    def loglik(log_kappa):\n        kappa = math.exp(log_kappa)\n        a, b = mu * kappa, (1 - mu) * kappa\n        norm = math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)\n        return sum(c * (norm + math.lgamma(a + k) + math.lgamma(b + n - k) - math.lgamma(a + b + n))\n                   for (n, k), c in counts.items())\n\n    lo, hi = math.log(MIN_CONCENTRATION), math.log(MAX_CONCENTRATION)\n    golden = (math.sqrt(5) - 1) / 2\n    x1, x2 = hi - golden * (hi - lo), lo + golden * (hi - lo)\n    f1, f2 = loglik(x1), loglik(x2)\n    for _ in range(100):  # golden-section search: the likelihood has one peak in log(kappa)\n        if f1 < f2:\n            lo, x1, f1 = x1, x2, f2\n            x2 = lo + golden * (hi - lo)\n            f2 = loglik(x2)\n        else:\n            hi, x2, f2 = x2, x1, f1\n            x1 = hi - golden * (hi - lo)\n            f1 = loglik(x1)\n    kappa = math.exp((lo + hi) / 2)\n    return mu * kappa, (1 - mu) * kappa\n\n\ndef p_bad(clicks, conversions, prior, ratio=BAD_RATIO):\n    \"\"\"Probability that the term's true conversion rate is below ratio x the account's rate.\"\"\"\n    a, b = prior\n    k = min(conversions, clicks)\n    return incomplete_beta(a + k, b + clicks - k, ratio * a / (a + b))\n\n\ndef clicks_to_flag(prior, conversions=0, sure=CONFIDENT, ratio=BAD_RATIO, limit=10 ** 7):\n    \"\"\"The fewest clicks at which a term with this many conversions reaches P(bad) >= sure.\n    P(bad) only rises with clicks at a fixed conversion count, so a doubling search and a\n    bisection find it exactly. None if it would take more than `limit` clicks.\"\"\"\n    lo = hi = max(1, math.ceil(conversions))\n    if p_bad(hi, conversions, prior, ratio) >= sure:\n        return hi\n    while p_bad(hi, conversions, prior, ratio) < sure:\n        if hi > limit:\n            return None\n        lo, hi = hi, hi * 2\n    while hi - lo > 1:\n        mid = (lo + hi) // 2\n        if p_bad(mid, conversions, prior, ratio) >= sure:\n            hi = mid\n        else:\n            lo = mid\n    return hi\n\n\ndef incomplete_beta(a, b, x):\n    \"\"\"Regularized incomplete beta function I_x(a, b): the CDF of Beta(a, b) at x.\"\"\"\n    if x <= 0:\n        return 0.0\n    if x >= 1:\n        return 1.0\n    front = math.exp(math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b) + a * math.log(x) + b * math.log1p(-x))\n    if x < (a + 1) / (a + b + 2):\n        return front * _continued_fraction(a, b, x) / a\n    return 1.0 - front * _continued_fraction(b, a, 1 - x) / b\n\n\ndef _continued_fraction(a, b, x, iterations=5000, eps=1e-15):\n    tiny = 1e-300\n    c, d = 1.0, 1.0 - (a + b) * x / (a + 1)\n    d = 1.0 / (d if abs(d) > tiny else tiny)\n    h = d\n    for m in range(1, iterations + 1):\n        m2 = 2 * m\n        for num in (m * (b - m) * x / ((a - 1 + m2) * (a + m2)),\n                    -(a + m) * (a + b + m) * x / ((a + m2) * (a + 1 + m2))):\n            d = 1.0 + num * d\n            d = 1.0 / (d if abs(d) > tiny else tiny)\n            c = 1.0 + num / c\n            c = c if abs(c) > tiny else tiny\n            h *= d * c\n        if abs(d * c - 1.0) < eps:\n            return h\n    return h\n","openppc/facts.py":"\"\"\"Facts: the only numbers OpenPPC is allowed to print.\n\nTemplates print a number only by registering it here first, as a labeled fact. That\nmakes it impossible for a report to contain a figure the checker cannot trace, and it\ngives `openppc check` the same list to judge anyone else's audit against.\n\"\"\"\nfrom dataclasses import dataclass, field\n\nSYMBOLS = {\"USD\": \"$\", \"CAD\": \"CA$\", \"AUD\": \"A$\", \"NZD\": \"NZ$\", \"EUR\": \"\u20ac\", \"GBP\": \"\u00a3\", \"INR\": \"\u20b9\"}\n\n\n@dataclass(frozen=True)\nclass Fact:\n    label: str        # what the number is, in words: \"cost of 'free plumbing estimate'\"\n    value: float\n    kind: str         # \"money\" | \"pct\" | \"count\"\n    metric: str = \"\"  # cost, clicks, impressions, conversions, ctr, cpc, cpa, cvr, days, rule\n    entity: str = \"\"  # the row or group it belongs to; \"\" for account-level figures\n    level: str = \"\"   # \"row\" (a search term or keyword) or \"group\" (a campaign, ad group or match type)\n\n\ndef fmt_money(value, currency=\"USD\"):\n    symbol = SYMBOLS.get((currency or \"\").upper())\n    return f\"{symbol}{value:,.2f}\" if symbol else f\"{value:,.2f} {currency}\"\n\n\n@dataclass\nclass FactBook:\n    currency: str = \"USD\"\n    facts: list = field(default_factory=list)\n    cards: dict = field(default_factory=dict)  # a template's results as data, for the web app; numbers as printed\n    client: dict = field(default_factory=dict)  # the branded client report's pages as blocks; numbers as printed\n\n    def add(self, label, value, kind, metric=\"\", entity=\"\"):\n        if value is not None:\n            self.facts.append(Fact(label, float(value), kind, metric, entity))\n        return value\n\n    def money(self, label, value, metric=\"cost\", entity=\"\"):\n        self.add(label, value, \"money\", metric, entity)\n        return fmt_money(value, self.currency)\n\n    def pct(self, label, value, metric=\"\", entity=\"\", dp=1):\n        self.add(label, value, \"pct\", metric, entity)\n        return f\"{value:.{dp}f}%\"\n\n    def count(self, label, value, metric=\"\", entity=\"\", dp=0):\n        self.add(label, value, \"count\", metric, entity)\n        return f\"{value:,.{dp}f}\"\n","openppc/ingest/__init__.py":"from .google_ads_csv import Report, load_report, parse_number\n\n__all__ = [\"Report\", \"load_report\", \"parse_number\"]\n","openppc/ingest/account.py":"\"\"\"Account snapshot: how an account is built (campaigns, ad groups, keywords, negatives, ads,\nassets), in one normalized shape whatever file it came from.\n\nToday it reads OpenPPC's own snapshot JSON. A Google Ads Editor whole-account export will be\nread into this same shape, so the structure checks never care which file the account came from.\n\n    {\"meta\": {\"account\": \"Acme Plumbing\", \"currency\": \"USD\", \"captured\": \"2026-09-28\"},\n     \"campaigns\": [{\"id\": \"1\", \"name\": \"Acme | Search\", \"status\": \"ENABLED\", \"channel\": \"SEARCH\",\n                    \"bidding\": \"MAXIMIZE_CONVERSIONS\", \"enhanced_cpc\": false,\n                    \"display_network\": false, \"geo_target_type\": \"PRESENCE\"}],\n     \"ad_groups\": [{\"id\": \"11\", \"campaign_id\": \"1\", \"name\": \"Plumbing repair\", \"status\": \"ENABLED\"}],\n     \"keywords\": [{\"ad_group_id\": \"11\", \"text\": \"plumbing repair\", \"match_type\": \"PHRASE\",\n                   \"status\": \"ENABLED\", \"serving\": \"ELIGIBLE\", \"quality_score\": 7,\n                   \"expected_ctr\": \"AVERAGE\", \"ad_relevance\": \"AVERAGE\", \"landing_page\": \"AVERAGE\"}],\n     \"negatives\": [{\"level\": \"CAMPAIGN\", \"owner_id\": \"1\", \"text\": \"free\", \"match_type\": \"BROAD\"}],\n     \"ads\": [{\"ad_group_id\": \"11\", \"type\": \"RESPONSIVE_SEARCH_AD\", \"status\": \"ENABLED\",\n              \"strength\": \"GOOD\", \"headlines\": [{\"text\": \"Same-day plumbing repair\", \"pin\": null}],\n              \"descriptions\": [{\"text\": \"Licensed and insured.\", \"pin\": null}]}],\n     \"assets\": [{\"level\": \"CAMPAIGN\", \"owner_id\": \"1\", \"type\": \"SITELINK\", \"status\": \"ENABLED\"}]}\n\nEverything but the ids is optional. A section left out of the file is None, not an empty list,\nso a check can say \"not in this file\" instead of reporting a clean account it never saw.\n\"\"\"\nimport json\nimport re\n\nSECTIONS = (\"campaigns\", \"ad_groups\", \"keywords\", \"negatives\", \"ads\", \"assets\")\nALIASES = {  # the words Editor and the UI use, mapped to the Google Ads API's names\n    \"MAXIMIZE_CLICKS\": \"TARGET_SPEND\",\n    \"LOW_SEARCH_VOLUME\": \"RARELY_SERVED\",\n}\n\n\ndef enum(value):\n    \"\"\"'Maximize conversions' or 'MAXIMIZE_CONVERSIONS' -> 'MAXIMIZE_CONVERSIONS'.\"\"\"\n    if value is None or str(value).strip() in (\"\", \"--\"):\n        return None\n    key = re.sub(r\"[^A-Z0-9]+\", \"_\", str(value).strip().upper()).strip(\"_\")\n    return ALIASES.get(key, key)\n\n\ndef words(text):\n    \"\"\"Keyword text as plain lowercase words, match-type marks dropped: '+pipe \"repair\"' -> ['pipe', 'repair'].\"\"\"\n    return re.findall(r\"[a-z0-9]+(?:['&.][a-z0-9]+)*\", str(text or \"\").lower())\n\n\ndef _geo(value):\n    \"\"\"Editor spells the option out ('Presence or interest: People in, regularly in, ...').\"\"\"\n    key = enum(value)\n    if key and key.startswith(\"PRESENCE_OR_INTEREST\"):\n        return \"PRESENCE_OR_INTEREST\"\n    return \"PRESENCE\" if key and key.startswith(\"PRESENCE\") else key\n\n\ndef _flag(value):\n    if value is None or value == \"\":\n        return None\n    if isinstance(value, str):\n        return value.strip().lower() in (\"true\", \"yes\", \"enabled\", \"on\", \"1\")\n    return bool(value)\n\n\ndef _int(value):\n    try:\n        return int(float(value))\n    except (TypeError, ValueError):\n        return None\n\n\ndef _text_assets(items):\n    return [{\"text\": str(i.get(\"text\", \"\")) if isinstance(i, dict) else str(i),\n             \"pin\": enum(i.get(\"pin\")) if isinstance(i, dict) else None} for i in items or []]\n\n\nNORMALIZE = {\n    \"campaigns\": lambda r: {\n        \"id\": str(r[\"id\"]), \"name\": str(r.get(\"name\") or r[\"id\"]), \"status\": enum(r.get(\"status\")),\n        \"channel\": enum(r.get(\"channel\")), \"bidding\": enum(r.get(\"bidding\")),\n        \"enhanced_cpc\": _flag(r.get(\"enhanced_cpc\")), \"display_network\": _flag(r.get(\"display_network\")),\n        \"geo_target_type\": _geo(r.get(\"geo_target_type\"))},\n    \"ad_groups\": lambda r: {\n        \"id\": str(r[\"id\"]), \"campaign_id\": str(r[\"campaign_id\"]), \"name\": str(r.get(\"name\") or r[\"id\"]),\n        \"status\": enum(r.get(\"status\"))},\n    \"keywords\": lambda r: {\n        \"ad_group_id\": str(r[\"ad_group_id\"]), \"text\": str(r.get(\"text\", \"\")), \"match_type\": enum(r.get(\"match_type\")),\n        \"status\": enum(r.get(\"status\")), \"serving\": enum(r.get(\"serving\")), \"quality_score\": _int(r.get(\"quality_score\")),\n        \"expected_ctr\": enum(r.get(\"expected_ctr\")), \"ad_relevance\": enum(r.get(\"ad_relevance\")),\n        \"landing_page\": enum(r.get(\"landing_page\"))},\n    \"negatives\": lambda r: {\n        \"level\": enum(r.get(\"level\")), \"owner_id\": str(r.get(\"owner_id\", \"\")), \"text\": str(r.get(\"text\", \"\")),\n        \"match_type\": enum(r.get(\"match_type\")), \"status\": enum(r.get(\"status\"))},\n    \"ads\": lambda r: {\n        \"ad_group_id\": str(r[\"ad_group_id\"]), \"type\": enum(r.get(\"type\")), \"status\": enum(r.get(\"status\")),\n        \"strength\": enum(r.get(\"strength\")), \"headlines\": _text_assets(r.get(\"headlines\")),\n        \"descriptions\": _text_assets(r.get(\"descriptions\"))},\n    \"assets\": lambda r: {\n        \"level\": enum(r.get(\"level\")), \"owner_id\": str(r.get(\"owner_id\", \"\")), \"type\": enum(r.get(\"type\")),\n        \"status\": enum(r.get(\"status\"))},\n}\n\n\ndef is_snapshot(data):\n    return isinstance(data, dict) and isinstance(data.get(\"campaigns\"), list)\n\n\ndef snapshot(data, source=\"\"):\n    if not is_snapshot(data):\n        raise ValueError(\"This is not an account snapshot: it needs a list of campaigns.\")\n    out = {\"meta\": dict(data.get(\"meta\") or {}), \"source\": source}\n    for name in SECTIONS:\n        rows = data.get(name)\n        out[name] = None if rows is None else [NORMALIZE[name](r) for r in rows]\n    return out\n\n\ndef read_json(path):\n    \"\"\"A JSON file's content, or an error that says plainly what is wrong with it.\"\"\"\n    try:\n        with open(path, encoding=\"utf-8\") as f:\n            return json.load(f)\n    except (UnicodeDecodeError, json.JSONDecodeError):\n        raise ValueError(f\"{path}: this is not valid JSON.\") from None\n\n\ndef load_snapshot(path):\n    return snapshot(read_json(path), source=str(path))\n","openppc/ingest/google_ads_csv.py":"\"\"\"Read a report exported from the Google Ads UI (Download > .csv).\n\nReal exports are messy, so this handles: a report title and a date-range line above\nthe header (US or day-first dates), UTF-16 \"Excel\" exports (tab separated), thousands\nseparators, European number style (\"1.361,04\", usually with semicolons), currency and\npercent signs, \"--\" for empty cells, and the \"Total:\" rows Google appends. Those totals\nare ignored; every total is recomputed from the rows.\n\nRead-only by construction: this module opens one local file and nothing else.\n\"\"\"\nimport csv\nimport datetime as dt\nimport io\nimport re\nfrom dataclasses import dataclass, field\n\n# canonical column -> header names Google has used for it (lower-case)\nALIASES = {\n    \"search_term\": [\"search term\"],\n    \"keyword\": [\"keyword\", \"search keyword\"],\n    \"match_type\": [\"match type\", \"search keyword match type\", \"search term match type\"],\n    \"added_excluded\": [\"added/excluded\"],\n    \"campaign\": [\"campaign\"],\n    \"campaign_type\": [\"campaign type\"],\n    \"ad_group\": [\"ad group\"],\n    \"clicks\": [\"clicks\"],\n    \"impressions\": [\"impr.\", \"impressions\"],\n    \"cost\": [\"cost\"],\n    \"conversions\": [\"conversions\"],\n    \"quality_score\": [\"quality score\", \"qual. score\"],\n    \"currency\": [\"currency code\", \"currency\"],\n}\nNUMERIC = {\"clicks\", \"impressions\", \"cost\", \"conversions\", \"quality_score\"}\nDATE_RANGE = re.compile(r\"([A-Z][a-z]+\\.? \\d{1,2}, \\d{4}|\\d{1,2} [A-Z][a-z]+\\.? \\d{4})\\s*[-\u2013\u2014]\\s*\"\n                        r\"([A-Z][a-z]+\\.? \\d{1,2}, \\d{4}|\\d{1,2} [A-Z][a-z]+\\.? \\d{4})\")\nTOTAL_ROW = re.compile(r\"^\\s*total\\s*:\", re.I)  # \"Total: Account\"; a search term like \"total gym\" is data\nEU_NUMBER = re.compile(r\"^-?[\\d.]*\\d,\\d{1,2}%?$\")  # \"1.361,04\", \"5,23%\"\nUS_NUMBER = re.compile(r\"^-?(?:\\d{1,3}(?:,\\d{3})+(?:\\.\\d+)?|\\d+\\.\\d{1,2})%?$\")  # \"1,361.04\", \"5.23%\"\n\n\n@dataclass\nclass Report:\n    rows: list = field(default_factory=list)\n    columns: set = field(default_factory=set)\n    source: str = \"\"\n    title: str = \"\"\n    start: dt.date = None\n    end: dt.date = None\n    currency: str = \"USD\"\n\n    @property\n    def days(self):\n        return (self.end - self.start).days + 1 if (self.start and self.end) else None\n\n    def has(self, *columns):\n        return all(c in self.columns for c in columns)\n\n\ndef parse_number(cell, european=False):\n    \"\"\"'1,361.04' -> 1361.04, '$6.42' -> 6.42, '9.86%' -> 9.86, '--' or '' -> None.\n    European style swaps the two marks: '1.361,04' -> 1361.04.\"\"\"\n    if cell is None:\n        return None\n    text = str(cell).strip()\n    if european:\n        text = text.replace(\".\", \"\").replace(\",\", \".\")\n    text = text.replace(\",\", \"\").replace(\"%\", \"\")\n    text = re.sub(r\"^[^\\d.\\-]+\", \"\", text)\n    if text in (\"\", \"-\", \".\", \"--\"):\n        return None\n    try:\n        return float(text)\n    except ValueError:\n        return None\n\n\ndef _date(text):\n    text = text.replace(\".\", \"\")\n    for fmt in (\"%B %d, %Y\", \"%b %d, %Y\", \"%d %B %Y\", \"%d %b %Y\"):\n        try:\n            return dt.datetime.strptime(text, fmt).date()\n        except ValueError:\n            continue\n    return None\n\n\ndef _decode(raw):\n    if raw[:2] in (b\"\\xff\\xfe\", b\"\\xfe\\xff\"):\n        return raw.decode(\"utf-16\")\n    try:\n        return raw.decode(\"utf-8-sig\")\n    except UnicodeDecodeError:\n        return raw.decode(\"latin-1\")\n\n\ndef _canonical(header):\n    name = (header or \"\").strip().lower()\n    for key, names in ALIASES.items():\n        if name in names:\n            return key\n    return None\n\n\ndef _find_header(lines):\n    for i, line in enumerate(lines[:15]):\n        for delim in (\",\", \"\\t\", \";\"):\n            keys = [_canonical(c) for c in next(csv.reader([line], delimiter=delim), [])]\n            if \"clicks\" in keys and \"cost\" in keys:\n                return i, delim, keys\n    return None\n\n\ndef _not_a_report(path, raw):\n    \"\"\"Why a file is plainly not a report export, or None. Google Ads offers .xlsx and .pdf in the same\n    Download menu as .csv, so those are the usual mix-ups.\"\"\"\n    if raw.startswith(b\"PK\\x03\\x04\"):\n        if str(path).lower().endswith(\".zip\"):\n            return \"this is a zip file. Unzip it, then add the .csv inside.\"\n        return (\"this is an Excel workbook, not a .csv. In Google Ads choose Download > .csv, or open the file \"\n                \"in Excel or Google Sheets and save it as .csv.\")\n    if raw.startswith(b\"\\xd0\\xcf\\x11\\xe0\"):\n        return (\"this is an old Excel workbook (.xls), not a .csv. In Google Ads choose Download > .csv, or open \"\n                \"the file in Excel and save it as .csv.\")\n    if raw.startswith(b\"%PDF\"):\n        return \"this is a PDF. OpenPPC needs the data itself: in Google Ads choose Download > .csv.\"\n    return None\n\n\ndef _european(rows, keys, path, delim):\n    \"\"\"Whether the numbers are written European style (\"1.361,04\"). The cells decide; a semicolon file whose\n    only marks are dots between thousands (\"1.450\") is European too. A file that mixes both styles cannot be\n    read safely, so it is refused rather than guessed.\"\"\"\n    cols = [i for i, k in enumerate(keys) if k in NUMERIC]\n    cells = [r[i].strip() for r in rows for i in cols if i < len(r) and r[i].strip()]\n    eu = sum(bool(EU_NUMBER.match(c)) for c in cells)\n    us = sum(bool(US_NUMBER.match(c)) for c in cells)\n    if eu and us:\n        raise ValueError(f\"{path}: the numbers mix two styles (1,234.56 and 1.234,56), so they cannot be read \"\n                         \"safely. Download the report again with Download > .csv.\")\n    dotted = any(re.fullmatch(r\"-?\\d{1,3}(?:\\.\\d{3})+\", c) for c in cells)\n    return eu > 0 or (delim == \";\" and not us and dotted)\n\n\ndef load_report(path):\n    with open(path, \"rb\") as f:\n        raw = f.read()\n    problem = _not_a_report(path, raw)\n    if problem:\n        raise ValueError(f\"{path}: {problem}\")\n    text = _decode(raw)\n    if not text.strip():\n        raise ValueError(f\"{path}: the file is empty.\")\n    lines = text.splitlines()\n    found = _find_header(lines)\n    if not found:\n        raise ValueError(\n            f\"{path}: no header row with Clicks and Cost columns in the first 15 lines. \"\n            \"Export the report from the Google Ads UI with Download > .csv. If Google Ads is set to another \"\n            \"language, the column names will not match: switch it to English and download again.\")\n    idx, delim, keys = found\n    report = Report(columns={k for k in keys if k}, source=str(path))\n    for line in lines[:idx]:\n        m = DATE_RANGE.search(line)\n        if m:\n            report.start, report.end = _date(m.group(1)), _date(m.group(2))\n        elif line.strip() and not report.title:\n            report.title = line.strip().strip('\"').strip()\n    body = list(csv.reader(io.StringIO(\"\\n\".join(lines[idx + 1:])), delimiter=delim))\n    name_at = next((keys.index(k) for k in (\"search_term\", \"keyword\") if k in keys), None)\n    data = [cells for cells in body\n            if any(c.strip() for c in cells)\n            and not TOTAL_ROW.match(next(c for c in cells if c.strip()))\n            and not (name_at is not None and name_at < len(cells) and TOTAL_ROW.match(cells[name_at]))]\n    european = _european(data, keys, path, delim)\n    for cells in data:\n        row = {}\n        for key, cell in zip(keys, cells):\n            if key:\n                row[key] = parse_number(cell, european) if key in NUMERIC else cell.strip()\n        report.rows.append(row)\n    currency = next((r.get(\"currency\") for r in report.rows if r.get(\"currency\")), None)\n    if currency:\n        report.currency = currency.upper()\n    return report\n","openppc/mcp_server.py":"\"\"\"MCP server: run OpenPPC inside Claude, Cursor, ChatGPT or any MCP client.\n\nOn your computer (Claude Code, Claude Desktop, Cursor), over stdio, reading local files:\n\n    claude mcp add openppc -- uvx --from \"openppc[mcp]\" openppc-mcp\n\nAs a web connector (ChatGPT, claude.ai), over streamable HTTP at /mcp:\n\n    openppc-mcp --http --host 0.0.0.0 --port 8000\n\nLocal tools take file paths. The web connector never reads paths: its tools take the export's\ncontents, work in a temporary folder that is deleted when the call ends, and keep nothing. Every\ntool is annotated read-only so clients know it never changes anything.\n\"\"\"\nimport argparse\nimport functools\nimport re\nimport tempfile\nfrom pathlib import Path\n\ntry:  # MCP Python SDK 2.x\n    from mcp.server.mcpserver import MCPServer as Server\nexcept ImportError:\n    try:  # MCP Python SDK 1.x\n        from mcp.server.fastmcp import FastMCP as Server\n    except ImportError:  # the MCP extra is optional\n        Server = None\ntry:  # the error a tool raises on purpose: the model gets its message (SDK 2.x, then 1.x)\n    from mcp.server.mcpserver.exceptions import ToolError\nexcept ImportError:\n    try:\n        from mcp.server.fastmcp.exceptions import ToolError\n    except ImportError:\n        ToolError = None\ntry:\n    from mcp.types import ToolAnnotations\n    READ_ONLY = ToolAnnotations(readOnlyHint=True, destructiveHint=False, openWorldHint=False)\nexcept ImportError:\n    READ_ONLY = None\n\nfrom . import __version__\nfrom .checkfacts import facts_for_paths\nfrom .cli import explain\nfrom .engine.trace import render_check, trace\nfrom .templates import TEMPLATES, run_template\n\nEXPORT_LIMIT = 3_500_000  # characters in one export sent to the web connector; a request is capped at 4 MB\nINSTRUCTIONS = (\"OpenPPC audits Google Ads exports read-only. Code computes every number in its reports and a \"\n                \"checker traces each one back to the export. Quote its numbers as they are and do not add \"\n                \"figures of your own; use check_numbers or check_audit to verify any other audit's numbers.\")\n\n\ndef list_templates() -> str:\n    \"\"\"List the audit templates, the export each one reads, and what it returns.\"\"\"\n    return \"\\n\".join(f\"- {t.NAME} ({t.TIER}): reads a {t.INPUT}. {t.SUMMARY}\" for t in TEMPLATES.values())\n\n\ndef audit_account(template: str, data_path: str, industry: str = \"\", min_cost: float | None = None,\n                  brand: str = \"\") -> str:\n    \"\"\"Run an audit template on a local Google Ads export and return the report as markdown.\n    Every number in the report is computed from the file and traced back to it. Pass the\n    account's brand names (comma-separated) so brand terms are never flagged as waste.\"\"\"\n    markdown, _, _ = run_template(template, data_path, industry=industry or None, min_cost=min_cost,\n                                  brand=brand or None)\n    return markdown\n\n\ndef check_numbers(audit_text: str, data_paths: list[str], industry: str = \"\") -> str:\n    \"\"\"Check every number in an audit, written by any AI or person, against local export files.\n    Reports which numbers trace to the data, which are attached to the wrong metric or row,\n    which are not in the data at all, and which sentences contradict their own numbers.\"\"\"\n    claims, contradictions = trace(audit_text, facts_for_paths(data_paths, industry or None))\n    return render_check(claims, contradictions)\n\n\ndef _export_file(folder, text, name):\n    \"\"\"Write an export's contents into the call's temporary folder, under a safe name.\"\"\"\n    if len(text) > EXPORT_LIMIT:\n        raise ValueError(f\"The export is too large for the web connector ({len(text):,} characters; the limit is \"\n                         f\"{EXPORT_LIMIT:,}). Export a shorter date range, or run OpenPPC on your computer.\")\n    stem = re.sub(r\"[^\\w.\\-]+\", \"_\", Path(name or \"\").name).strip(\"._\")[:80] or \"export\"\n    if not stem.lower().endswith((\".csv\", \".tsv\", \".txt\", \".json\")):\n        stem += \".json\" if text.lstrip().startswith(\"{\") else \".csv\"\n    path = Path(folder) / stem\n    path.write_text(text, encoding=\"utf-8\")\n    return str(path)\n\n\ndef audit_export(template: str, export_text: str, export_name: str = \"export.csv\", industry: str = \"\",\n                 min_cost: float | None = None, brand: str = \"\") -> str:\n    \"\"\"Run an audit template on the contents of a Google Ads export and return the report as markdown.\n    Pass the whole file's text: a Search terms or Keywords report as CSV, or the JSON for snapshot and\n    two-period templates. Every number in the report is computed from it and traced back to it. Pass the\n    account's brand names (comma-separated) so brand terms are never flagged as waste.\"\"\"\n    with tempfile.TemporaryDirectory(prefix=\"openppc-\") as folder:\n        return audit_account(template, _export_file(folder, export_text, export_name), industry, min_cost, brand)\n\n\ndef check_audit(audit_text: str, export_text: str, export_name: str = \"export.csv\", industry: str = \"\") -> str:\n    \"\"\"Check every number in an audit, written by any AI or person, against the contents of the Google Ads\n    export it was written from (pass the whole file's text). Reports which numbers trace to the data,\n    which are attached to the wrong metric or row, which are not in the data at all, and which sentences\n    contradict their own numbers.\"\"\"\n    with tempfile.TemporaryDirectory(prefix=\"openppc-\") as folder:\n        return check_numbers(audit_text, [_export_file(folder, export_text, export_name)], industry)\n\n\ndef _plain_errors(tool):\n    \"\"\"Hand the errors a user can fix to the model as plain messages, the ones the command line prints. The SDK\n    reports any other exception as only \"Error executing tool <name>\", which looks like OpenPPC is broken.\"\"\"\n    @functools.wraps(tool)\n    def call(*args, **kwargs):\n        try:\n            return tool(*args, **kwargs)\n        except (ValueError, FileNotFoundError, KeyError) as e:\n            if ToolError is None:\n                raise\n            raise ToolError(explain(e)) from None\n    return call\n\n\nLOCAL_TOOLS = (list_templates, audit_account, check_numbers)\nWEB_TOOLS = (list_templates, audit_export, check_audit)  # contents in, never paths\n\n\ndef build_server(web=False):\n    try:\n        server = Server(\"openppc\", instructions=INSTRUCTIONS, version=__version__)\n    except TypeError:  # an SDK 1.x server takes no version\n        try:\n            server = Server(\"openppc\", instructions=INSTRUCTIONS)\n        except TypeError:  # an SDK without server instructions\n            server = Server(\"openppc\")\n    for tool in WEB_TOOLS if web else LOCAL_TOOLS:\n        try:\n            server.tool(annotations=READ_ONLY)(_plain_errors(tool))\n        except TypeError:  # an SDK too old for tool annotations\n            server.tool()(_plain_errors(tool))\n    return server\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(\n        prog=\"openppc-mcp\",\n        description=\"OpenPPC as an MCP server: over stdio for Claude Code, Claude Desktop and Cursor, \"\n                    \"or over HTTP (--http) as a connector for ChatGPT and claude.ai.\")\n    parser.add_argument(\"--http\", action=\"store_true\",\n                        help=\"serve streamable HTTP at /mcp; the tools then take file contents, never paths\")\n    parser.add_argument(\"--host\", default=\"127.0.0.1\", help=\"address to listen on with --http (default 127.0.0.1)\")\n    parser.add_argument(\"--port\", type=int, default=8000, help=\"port to listen on with --http (default 8000)\")\n    args = parser.parse_args(argv)\n    if Server is None:\n        raise SystemExit('The MCP server needs the optional extra: uv pip install \"openppc[mcp]\"')\n    server = build_server(web=args.http)\n    if not args.http:\n        server.run()\n        return\n    try:  # SDK 2.x takes the HTTP options as arguments\n        server.run(\"streamable-http\", host=args.host, port=args.port, stateless_http=True, json_response=True)\n    except TypeError:  # SDK 1.x reads them from settings\n        server.settings.host, server.settings.port = args.host, args.port\n        server.settings.stateless_http, server.settings.json_response = True, True\n        server.run(transport=\"streamable-http\")\n\n\nif __name__ == \"__main__\":\n    main()\n","openppc/samples.py":"\"\"\"The made-up Acme Plumbing sample: one export per template, and an AI-written audit to check.\n\nIt ships inside the package (pyproject.toml copies these files from examples/ into openppc/samples/), so after\na plain `pip install openppc` the command line can try any template with --sample. In a clone of the repo the\nfiles are read straight from examples/.\n\"\"\"\nimport errno\nfrom pathlib import Path\n\nEXPORTS = {\n    \"search-term-waste\": \"search_terms_acme.csv\",\n    \"keyword-audit\": \"keywords_acme.csv\",\n    \"account-structure\": \"account_structure_acme.json\",\n    \"account-read\": \"account_acme.json\",\n}\nAUDIT = \"ai_audit_sample.md\"\nAUDIT_DATA = \"search_terms_acme.csv\"  # the export the sample audit was written from\nINDUSTRY = \"home-services\"            # a plumbing company\n\n\ndef path(name):\n    \"\"\"Where a sample file is: inside the installed package, or in examples/ in a clone.\"\"\"\n    here = Path(__file__).resolve().parent\n    for folder in (here / \"samples\", here.parent / \"examples\"):\n        if (folder / name).is_file():\n            return folder / name\n    raise FileNotFoundError(errno.ENOENT, \"a sample file is missing from this install\", name)\n","openppc/templates/__init__.py":"\"\"\"Audit templates. Each one is a recipe: which export it reads, what it computes, how it reports.\n\nA template module defines NAME, TITLE, TIER, INPUT, SUMMARY, INPUT_KIND (\"report\" or\n\"metrics\" or \"account\"), accepts(data) and run(data, **params) -> (markdown lines, FactBook).\n\"\"\"\nfrom ..engine.trace import trace\nfrom ..ingest import load_report\nfrom . import account_read, account_structure, keyword_audit, search_term_waste\n\nTEMPLATES = {t.NAME: t for t in (search_term_waste, keyword_audit, account_structure, account_read)}\n\n\ndef load_input(template, path):\n    if template.INPUT_KIND == \"metrics\":\n        return account_read.load_metrics(path)\n    if template.INPUT_KIND == \"account\":\n        return account_structure.load(path)\n    return load_report(path)\n\n\ndef run_template(name, path, **params):\n    \"\"\"Run a template on a file. Returns (markdown, facts, number_check_passed).\"\"\"\n    markdown, book, passed = run_template_book(name, path, **params)\n    return markdown, book.facts, passed\n\n\ndef run_template_book(name, path, **params):\n    \"\"\"Same as run_template, but hands back the whole FactBook, cards included.\"\"\"\n    if name not in TEMPLATES:\n        raise ValueError(f\"unknown template '{name}'. Available: {', '.join(TEMPLATES)}\")\n    template = TEMPLATES[name]\n    lines, book = template.run(load_input(template, path), **params)\n    markdown = \"\\n\".join(lines)\n    claims, contradictions = trace(markdown, book.facts)\n    passed = all(c.verdict == \"traced\" for c in claims) and not contradictions\n    markdown += \"\\n\\n---\\n\\n\" + (\n        \"Number check: every number in this report traces back to your data.\"\n        if passed else\n        \"Number check FAILED: this report contains a number the checker could not trace. \"\n        \"That is a bug in OpenPPC, please report it.\")\n    return markdown, book, passed\n","openppc/templates/_common.py":"\"\"\"Helpers shared by the templates.\"\"\"\nimport difflib\nimport hashlib\nimport os\nimport re\nfrom collections import namedtuple\n\nTotals = namedtuple(\"Totals\", \"cost clicks impressions conversions\")\n\nBRAND_MIN_LETTERS = 3      # brand names shorter than this are ignored\nBRAND_TYPO_MIN_LETTERS = 5  # a brand's first word needs this many letters before typos of it count\nBRAND_TYPO_RATIO = 0.8     # a word at least this similar to that first word is a typo of the brand\nMIN_COST_USD = 20.0        # cost a zero-conversion search term or keyword needs before it is listed\n# The same threshold in other currencies: about $20, rounded to a figure people type. Exchange rates drift, so\n# these are starting points; --min-cost (Waste threshold in the app) always wins.\nMIN_COST = {\"USD\": MIN_COST_USD, \"CAD\": 25, \"AUD\": 30, \"NZD\": 35, \"EUR\": 20, \"GBP\": 15, \"CHF\": 20, \"SEK\": 200,\n            \"NOK\": 200, \"DKK\": 150, \"PLN\": 80, \"CZK\": 450, \"HUF\": 7_000, \"INR\": 1_500, \"JPY\": 3_000, \"KRW\": 25_000,\n            \"CNY\": 150, \"HKD\": 150, \"SGD\": 25, \"MYR\": 90, \"THB\": 700, \"IDR\": 300_000, \"PHP\": 1_000,\n            \"VND\": 500_000, \"AED\": 75, \"SAR\": 75, \"ILS\": 75, \"TRY\": 700, \"ZAR\": 350, \"BRL\": 100, \"MXN\": 350}\n\n\ndef min_cost_for(currency):\n    \"\"\"(threshold, known): the default threshold in the export's currency. For a currency without a\n    default it is 20 of that currency, and known is False so the report can say so.\"\"\"\n    code = (currency or \"USD\").upper()\n    return float(MIN_COST.get(code, MIN_COST_USD)), code in MIN_COST\n\n\ndef val(row, key):\n    return row.get(key) or 0\n\n\ndef totals(rows):\n    return Totals(*(sum(val(r, k) for r in rows) for k in (\"cost\", \"clicks\", \"impressions\", \"conversions\")))\n\n\ndef conv_dp(*values):\n    \"\"\"Conversions print as whole numbers unless the account records fractional ones.\"\"\"\n    return 1 if any((v or 0) % 1 for v in values) else 0\n\n\ndef esc(text):\n    return str(text).replace(\"|\", \"\\\\|\")\n\n\ndef plural(n, one, many=None):\n    return one if n == 1 else (many or one + \"s\")\n\n\ndef brand_matcher(brand):\n    \"\"\"Return is_brand(text) for comma-separated brand names (\"Pipewell Plumbing, Pipewell\").\n\n    A term is brand when it contains a brand name, or a word within a typo or two of a brand\n    name's first word when that word has 5+ letters: \"pipewel plumbing\" counts for \"Pipewell Plumbing\".\n    Brand terms are never flagged as waste, so they never become negative keywords.\"\"\"\n    names = [\" \".join(re.findall(r\"[a-z0-9]+\", n.lower())) for n in re.split(r\"[,;\\n]\", brand or \"\")]\n    names = [n for n in names if len(n) >= BRAND_MIN_LETTERS]\n    firsts = {n.split()[0] for n in names if len(n.split()[0]) >= BRAND_TYPO_MIN_LETTERS}\n\n    def is_brand(text):\n        words = re.findall(r\"[a-z0-9]+\", str(text).lower())\n        padded = f\" {' '.join(words)} \"\n        return (any(f\" {n} \" in padded for n in names)\n                or any(difflib.SequenceMatcher(None, f, w).ratio() >= BRAND_TYPO_RATIO for f in firsts for w in words))\n    return is_brand\n\n\ndef need(report, column, export_name, how_to_export):\n    if not report.has(column, \"clicks\", \"cost\", \"conversions\"):\n        raise ValueError(f\"This template needs a {export_name} export with Clicks, Cost and \"\n                         f\"Conversions columns. {how_to_export}\")\n\n\ndef header(book, report, title):\n    bits = [f\"Source: `{os.path.basename(report.source)}`\"]\n    if report.start and report.end:\n        s, e = report.start, report.end\n        days = book.count(\"days in the date range\", report.days, \"days\")\n        bits.append(f\"{s:%B} {s.day}, {s.year} to {e:%B} {e.day}, {e.year} ({days} days)\")\n    bits.append(f\"currency {report.currency}\")\n    return [f\"# {title}\", \"\", \" \u00b7 \".join(bits), \"\",\n            \"_Built by OpenPPC, read-only: computed from this file alone, with no network calls._\", \"\"]\n\n\ndef fingerprint(path):\n    \"\"\"SHA-256 of the export, so a reader can tell exactly which file a report was computed from.\"\"\"\n    try:\n        with open(path, \"rb\") as f:\n            return hashlib.sha256(f.read()).hexdigest()\n    except (OSError, TypeError):\n        return None\n\n\ndef period(report, compact=False):\n    \"\"\" \"July 1, 2026 to July 31, 2026\", or \"July 1 to July 31, 2026\" when compact and within one year.\"\"\"\n    s, e = report.start, report.end\n    if not (s and e):\n        return None\n    if compact and s.year == e.year:\n        return f\"{s:%B} {s.day} to {e:%B} {e.day}, {e.year}\"\n    return f\"{s:%B} {s.day}, {s.year} to {e:%B} {e.day}, {e.year}\"\n\n\ndef month_label(report):\n    \"\"\" \"July 2026\" for a report inside one month, else the compact period.\"\"\"\n    s, e = report.start, report.end\n    if not (s and e):\n        return None\n    return f\"{s:%B} {s.year}\" if (s.year, s.month) == (e.year, e.month) else period(report, compact=True)\n\n\ndef register_group(book, entity, t, grand):\n    \"\"\"Register every standard figure for one row or group (entity) or the account (entity '').\"\"\"\n    name = f\"'{entity}'\" if entity else \"the account\"\n    book.money(f\"cost of {name}\", t.cost, \"cost\", entity)\n    book.count(f\"clicks of {name}\", t.clicks, \"clicks\", entity)\n    if t.impressions:\n        book.count(f\"impressions of {name}\", t.impressions, \"impressions\", entity)\n    book.count(f\"conversions of {name}\", t.conversions, \"conversions\", entity, dp=conv_dp(t.conversions))\n    if t.impressions:\n        book.pct(f\"CTR of {name}\", t.clicks / t.impressions * 100, \"ctr\", entity)\n    if t.clicks:\n        book.money(f\"CPC of {name}\", t.cost / t.clicks, \"cpc\", entity)\n        book.pct(f\"conversion rate of {name}\", t.conversions / t.clicks * 100, \"cvr\", entity)\n    if t.conversions:\n        book.money(f\"cost per conversion of {name}\", t.cost / t.conversions, \"cpa\", entity)\n    if entity:\n        if grand.cost:\n            book.pct(f\"{name} share of total cost\", t.cost / grand.cost * 100, \"cost\", entity)\n        if grand.clicks:\n            book.pct(f\"{name} share of total clicks\", t.clicks / grand.clicks * 100, \"clicks\", entity)\n        if grand.conversions:\n            book.pct(f\"{name} share of total conversions\", t.conversions / grand.conversions * 100,\n                     \"conversions\", entity)\n","openppc/templates/account_read.py":"\"\"\"Account read: what changed between two periods, classified by explicit rules.\n\nInput: a small .json file with the account's totals for two periods:\n\n    {\"meta\": {\"currency\": \"USD\", \"window\": \"July 2026 vs June 2026\",\n              \"business_model\": \"plumbing (lead-gen)\"},\n     \"current\": {\"spend\": 4973.64, \"impressions\": 9852, \"clicks\": 732, \"conversions\": 85},\n     \"prior\":   {\"spend\": 5210.00, \"impressions\": 11890, \"clicks\": 760, \"conversions\": 71}}\n\nEvery direction and percentage is computed in code (engine/findings.py). Nothing here\nis left for a model to work out, because that is where models go wrong.\n\"\"\"\nimport os\n\nfrom ..engine import benchmarks\nfrom ..engine.findings import CPA_BAND, FLAT, THIN_DATA, build_findings\nfrom ..facts import FactBook\nfrom ..ingest.account import read_json\nfrom ._common import conv_dp\n\nNAME = \"account-read\"\nTITLE = \"Account read: period over period\"\nTIER = \"free\"\nINPUT_KIND = \"metrics\"\nINPUT = \"two-period totals (.json)\"\nSUMMARY = (\"What changed between two periods, classified by explicit rules: efficiency win, \"\n           \"over-expansion, broken tracking, and more. Every direction is computed, never guessed.\")\nKEYS = (\"cs\", \"ps\", \"ci\", \"pi\", \"cc\", \"pc\", \"cv\", \"pv\")\n\n\ndef accepts(data):\n    return isinstance(data, dict) and \"metrics\" in data\n\n\ndef load_metrics(path):\n    d = read_json(path)\n    try:\n        if \"current\" in d and \"prior\" in d:\n            c, p = d[\"current\"], d[\"prior\"]\n            m = {\"cs\": c[\"spend\"], \"ps\": p[\"spend\"], \"ci\": c[\"impressions\"], \"pi\": p[\"impressions\"],\n                 \"cc\": c[\"clicks\"], \"pc\": p[\"clicks\"], \"cv\": c[\"conversions\"], \"pv\": p[\"conversions\"]}\n        else:\n            m = {k: d[k] for k in KEYS}\n        metrics = {k: float(v) for k, v in m.items()}\n    except (KeyError, TypeError, ValueError):\n        raise ValueError(f\"{path}: this JSON is not an account file OpenPPC reads. It needs an account snapshot \"\n                         \"(a list of campaigns) or two-period totals (current and prior spend, impressions, \"\n                         \"clicks and conversions).\") from None\n    return {\"metrics\": metrics, \"meta\": d.get(\"meta\", {}), \"source\": str(path)}\n\n\ndef _register(book, m):\n    for key, word, metric in ((\"s\", \"spend\", \"cost\"), (\"i\", \"impressions\", \"impressions\"),\n                              (\"c\", \"clicks\", \"clicks\"), (\"v\", \"conversions\", \"conversions\")):\n        cur, prior = m[\"c\" + key], m[\"p\" + key]\n        if key == \"s\":\n            book.money(f\"current {word}\", cur, metric)\n            book.money(f\"prior {word}\", prior, metric)\n        else:\n            dp = conv_dp(cur, prior) if key == \"v\" else 0\n            book.count(f\"current {word}\", cur, metric, dp=dp)\n            book.count(f\"prior {word}\", prior, metric, dp=dp)\n        if prior:\n            book.pct(f\"{word} change\", abs(cur - prior) / prior * 100, metric)\n            book.pct(f\"current {word} as a share of prior\", cur / prior * 100, metric)\n    ratios = ((\"CTR\", \"ctr\", \"pct\", lambda s, i, c, v: c / i * 100 if i else None),\n              (\"CPA\", \"cpa\", \"money\", lambda s, i, c, v: s / v if v else None),\n              (\"conversion rate\", \"cvr\", \"pct\", lambda s, i, c, v: v / c * 100 if c else None),\n              (\"CPC\", \"cpc\", \"money\", lambda s, i, c, v: s / c if c else None))\n    for name, metric, kind, fn in ratios:\n        cur = fn(m[\"cs\"], m[\"ci\"], m[\"cc\"], m[\"cv\"])\n        prior = fn(m[\"ps\"], m[\"pi\"], m[\"pc\"], m[\"pv\"])\n        add = book.money if kind == \"money\" else book.pct\n        if cur is not None:\n            add(f\"current {name}\", cur, metric)\n        if prior is not None:\n            add(f\"prior {name}\", prior, metric)\n        if cur is not None and prior:\n            book.pct(f\"{name} change\", abs(cur - prior) / prior * 100, metric)\n    book.pct(\"rule: a move smaller than this is flat\", FLAT * 100, \"rule\")\n    book.pct(\"rule: CPA band for 'efficiency held'\", CPA_BAND * 100, \"rule\")\n    book.count(\"rule: thin-data threshold (conversions per period)\", THIN_DATA, \"rule\")\n\n\ndef _markdown(block):\n    out = []\n    for line in block.splitlines():\n        if line.startswith(\"COMPUTED FINDINGS\"):\n            out += [\"## Period over period\", \"\"]\n        elif line.startswith(\"READ: \"):\n            out += [\"\", \"## Read\", \"\", line[len(\"READ: \"):]]\n        elif line.startswith(\"BIGGEST MOVE: \"):\n            out += [\"\", f\"**Biggest move:** {line[len('BIGGEST MOVE: '):]}\"]\n        elif line == \"FLAGS: none\":\n            out += [\"\", \"## Flags\", \"\", \"None.\"]\n        elif line == \"FLAGS:\":\n            out += [\"\", \"## Flags\", \"\"]\n        elif line.strip():\n            out.append(line)\n    return out\n\n\ndef run(data, industry=None, **_):\n    m, meta = data[\"metrics\"], data.get(\"meta\", {})\n    book = FactBook((meta.get(\"currency\") or \"USD\").upper())\n    _register(book, m)\n    bits = [f\"Source: `{os.path.basename(data.get('source', ''))}`\"]\n    if meta.get(\"window\"):\n        bits.append(meta[\"window\"])\n    bits.append(f\"currency {book.currency}\")\n    out = [f\"# {TITLE}\", \"\", \" \u00b7 \".join(bits), \"\",\n           \"_Built by OpenPPC, read-only: computed from this file alone, with no network calls._\", \"\"]\n    out += _markdown(build_findings(m, meta))\n    if industry:\n        out += benchmarks.section(book, industry, cost=m[\"cs\"], clicks=m[\"cc\"],\n                                  impressions=m[\"ci\"], conversions=m[\"cv\"], currency=book.currency)\n    out += [\"\", \"## How this was computed\", \"\",\n            f\"- Every change is current minus prior, divided by prior. A move smaller than \"\n            f\"{FLAT * 100:.0f}% is called flat.\",\n            \"- The read is the first rule that matches, in priority order: tracking problems, small samples, \"\n            \"then the spend, conversion and CPA patterns. The rules live in `openppc/engine/findings.py`.\",\n            \"- A conversion is whatever this account counts as one. Seasonal businesses should compare against \"\n            \"the same period last year, not the previous one.\"]\n    return out, book\n","openppc/templates/account_structure.py":"\"\"\"Account structure audit: how the account is built, not how it performed.\n\nReads an account snapshot (openppc/ingest/account.py). Every check is a row in\nrulebook/rules.csv, and where Google and practitioners disagree the report shows both sides\ninstead of picking one. Only live Search is judged: a keyword or ad counts when it, its ad\ngroup and its campaign are all enabled.\n\"\"\"\nimport os\nfrom collections import Counter, defaultdict, namedtuple\nfrom datetime import date\n\nfrom ..facts import FactBook\nfrom ..ingest.account import load_snapshot, words\nfrom ._common import brand_matcher, esc, plural\n\nNAME = \"account-structure\"\nTITLE = \"Account structure audit\"\nTIER = \"free\"\nINPUT_KIND = \"account\"\nINPUT = \"Account snapshot (.json)\"\nSUMMARY = (\"How the account is built: broad match without Smart Bidding, brand mixed with non-brand, \"\n           \"duplicate keywords, negatives that block your own keywords, thin or pinned ads, missing \"\n           \"sitelinks, retired bidding and more.\")\n\nSMART_BIDDING = frozenset({\"TARGET_CPA\", \"TARGET_ROAS\", \"MAXIMIZE_CONVERSIONS\", \"MAXIMIZE_CONVERSION_VALUE\"})\nCLICK_BIDDING = frozenset({\"MANUAL_CPC\", \"TARGET_SPEND\", \"ENHANCED_CPC\"})\nRSA_MAX_HEADLINES = 15      # Google: a responsive search ad holds up to 15 headlines; fill them...\nRSA_MAX_DESCRIPTIONS = 4    # ...and all 4 descriptions\nRSA_FEW_HEADLINES = 8       # Optmyzr's audit fails ads with fewer headlines than this\nMIN_RSAS_PER_AD_GROUP = 2   # Google: at least 2 responsive search ads in every ad group\nMIN_SITELINKS = 4           # Google and Optmyzr: at least 4 sitelinks\nMIN_CALLOUTS = 4            # Optmyzr: at least 4 callouts...\nMIN_SNIPPETS = 1            # ...and 1 structured snippet per Search campaign\nNICE = {\"TARGET_SPEND\": \"Maximize clicks\", \"MANUAL_CPC\": \"Manual CPC\", \"ENHANCED_CPC\": \"Enhanced CPC\",\n        \"TARGET_CPA\": \"Target CPA\", \"TARGET_ROAS\": \"Target ROAS\", \"PRESENCE_OR_INTEREST\": \"Presence or interest\"}\n\nCheck = namedtuple(\"Check\", \"title rule status summary lines\")  # status: found, passed, info, missing, needs brand\n\n\ndef accepts(data):\n    return isinstance(data, dict) and data.get(\"campaigns\") is not None\n\n\ndef load(path):\n    return load_snapshot(path)\n\n\ndef nice(value):\n    return NICE.get(value, (value or \"unknown\").replace(\"_\", \" \").capitalize())\n\n\ndef blocks(negative, match_type, keyword):\n    \"\"\"Would this negative stop this keyword's own searches? Exact: the same words. Phrase: the\n    words together and in order. Broad, or match type unknown: every word, in any order.\"\"\"\n    n, k = words(negative), words(keyword)\n    if not n:\n        return False\n    if match_type == \"EXACT\":\n        return n == k\n    if match_type == \"PHRASE\":\n        return any(k[i:i + len(n)] == n for i in range(len(k) - len(n) + 1))\n    return set(n) <= set(k)\n\n\ndef _live(data):\n    camps = {c[\"id\"]: c for c in data[\"campaigns\"] if c[\"status\"] == \"ENABLED\" and c[\"channel\"] in (None, \"SEARCH\")}\n    groups = {g[\"id\"]: g for g in data[\"ad_groups\"] or [] if g[\"status\"] == \"ENABLED\" and g[\"campaign_id\"] in camps}\n    kws = [dict(k, campaign_id=groups[k[\"ad_group_id\"]][\"campaign_id\"]) for k in data[\"keywords\"] or []\n           if k[\"status\"] == \"ENABLED\" and k[\"ad_group_id\"] in groups]\n    ads = [a for a in data[\"ads\"] or []\n           if a[\"status\"] == \"ENABLED\" and a[\"ad_group_id\"] in groups and a[\"type\"] == \"RESPONSIVE_SEARCH_AD\"]\n    return camps, groups, kws, ads\n\n\ndef _named(book, *names):\n    \"\"\"Register names a table prints, so digits inside them (\"40 gallon water heater\") read as part of the\n    name, not as claims the checker has to trace.\"\"\"\n    for n in names:\n        book.add(\"name printed in this report\", 0, \"count\", \"\", n)\n\n\ndef _missing(title, rule, what):\n    return Check(title, rule, \"missing\", f\"Not in this file ({what})\", [])\n\n\ndef _broad(book, camps, kws, top):\n    title, rule = \"Broad match without Smart Bidding\", \"search-broad-match-needs-smart-bidding\"\n    if not kws or all(c[\"bidding\"] is None for c in camps.values()):\n        return _missing(title, rule, \"keywords and bid strategies\")\n    rows = []\n    for c in camps.values():\n        n = sum(1 for k in kws if k[\"campaign_id\"] == c[\"id\"] and k[\"match_type\"] == \"BROAD\")\n        if c[\"bidding\"] and c[\"bidding\"] not in SMART_BIDDING and n:\n            rows.append((c, n))\n    if not rows:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    total = sum(n for _, n in rows)\n    t = book.count(\"broad match keywords in campaigns without Smart Bidding\", total, \"\")\n    k = book.count(\"campaigns running broad match without Smart Bidding\", len(rows))\n    lines = [\"Google: broad match keywords should only run in campaigns that use Smart Bidding (Target CPA, \"\n             \"Target ROAS, Maximize conversions or Maximize conversion value). On any other strategy, broad \"\n             \"match buys loosely related searches with nothing steering it toward conversions.\", \"\",\n             \"| Campaign | Bidding | Broad keywords |\", \"|---|---|---|\"]\n    for c, n in sorted(rows, key=lambda x: -x[1])[:top]:\n        v = book.count(f\"broad match keywords in {c['name']}\", n, \"\", c[\"name\"])\n        lines.append(f\"| {esc(c['name'])} | {nice(c['bidding'])} | {v} |\")\n    return Check(title, rule, \"found\", f\"{t} {plural(total, 'keyword')} in {k} {plural(len(rows), 'campaign')}\", lines)\n\n\ndef _brand_mix(book, camps, kws, brand, top):\n    title, rule = \"Brand and non-brand in one campaign\", \"struct-brand-nonbrand\"\n    if not brand:\n        return Check(title, rule, \"needs brand\", \"Add --brand to check\", [])\n    if not kws:\n        return _missing(title, rule, \"keywords\")\n    is_brand = brand_matcher(brand)\n    rows = []\n    for c in camps.values():\n        texts = [k[\"text\"] for k in kws if k[\"campaign_id\"] == c[\"id\"]]\n        b = sum(1 for t in texts if is_brand(t))\n        if b and len(texts) - b:\n            rows.append((c, b, len(texts) - b))\n    if not rows:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    k = book.count(\"campaigns mixing brand and non-brand keywords\", len(rows))\n    lines = [\"Practitioners keep brand keywords in their own campaigns. Brand searches convert cheaply, so \"\n             \"mixed in they hide how the other keywords really perform, and the two need different budgets \"\n             \"and bids.\", \"\", \"| Campaign | Brand keywords | Other keywords |\", \"|---|---|---|\"]\n    for c, b, other in rows[:top]:\n        bs = book.count(f\"brand keywords in {c['name']}\", b, \"\", c[\"name\"])\n        os_ = book.count(f\"non-brand keywords in {c['name']}\", other, \"\", c[\"name\"])\n        lines.append(f\"| {esc(c['name'])} | {bs} | {os_} |\")\n    return Check(title, rule, \"found\", f\"{k} {plural(len(rows), 'campaign')}\", lines)\n\n\ndef _duplicates(book, groups, kws, top):\n    title, rule = \"Duplicate keywords\", \"kw-duplicates\"\n    if not kws:\n        return _missing(title, rule, \"keywords\")\n    where = defaultdict(set)\n    for k in kws:\n        where[(\" \".join(words(k[\"text\"])), k[\"match_type\"])].add(k[\"ad_group_id\"])\n    dups = sorted(((text, mt, ags) for (text, mt), ags in where.items() if len(ags) >= 2), key=lambda d: -len(d[2]))\n    if not dups:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"keywords live in more than one ad group\", len(dups), \"\")\n    lines = [\"The same keyword and match type is live in more than one ad group, so your own ad groups compete \"\n             \"for the same searches. Keep the one in the best-fitting ad group and pause the others. Google's \"\n             \"structure guide says the same; practitioners add: don't let Google's auto-applied \\\"remove \"\n             \"redundant keywords\\\" pick for you.\", \"\", \"| Keyword | Match type | Ad groups |\", \"|---|---|---|\"]\n    for text, mt, ags in dups[:top]:\n        names = [groups[a][\"name\"] for a in sorted(ags)]\n        _named(book, text, *names)\n        lines.append(f\"| {esc(text)} | {nice(mt)} | {', '.join(esc(g) for g in names)} |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(dups), 'keyword')}\", lines)\n\n\ndef _conflicts(book, camps, groups, kws, negatives, top):\n    title, rule = \"Negatives that block your own keywords\", \"neg-conflicts\"\n    if negatives is None or not kws:\n        return _missing(title, rule, \"negative keywords\")\n    scoped = [n for n in negatives if n[\"status\"] in (None, \"ENABLED\") and n[\"level\"] in (\"AD_GROUP\", \"CAMPAIGN\")]\n    found = [(n, k) for k in kws for n in scoped\n             if n[\"owner_id\"] == (k[\"ad_group_id\"] if n[\"level\"] == \"AD_GROUP\" else k[\"campaign_id\"])\n             and blocks(n[\"text\"], n[\"match_type\"], k[\"text\"])]\n    lists = sum(1 for n in negatives if n[\"level\"] == \"LIST\")\n    note = \" (shared lists not checked)\" if lists else \"\"\n    if not found:\n        return Check(title, rule, \"passed\", \"Passed\" + note, [])\n    n = book.count(\"negative keywords that block a live keyword\", len(found), \"\")\n    lines = [\"A negative keyword that matches one of your own keywords stops that keyword from serving. Remove \"\n             \"the negative, or narrow it to exact match.\", \"\",\n             \"| Negative | Level | Blocks keyword | Ad group |\", \"|---|---|---|---|\"]\n    for neg, k in found[:top]:\n        mt = nice(neg[\"match_type\"]) if neg[\"match_type\"] else \"match type unknown\"\n        _named(book, neg[\"text\"], k[\"text\"], groups[k[\"ad_group_id\"]][\"name\"])\n        lines.append(f\"| -{esc(neg['text'])} ({mt}) | {nice(neg['level'])} | {esc(k['text'])} | \"\n                     f\"{esc(groups[k['ad_group_id']]['name'])} |\")\n    if any(neg[\"match_type\"] is None for neg, _ in found):\n        lines += [\"\", \"Where the file does not give a negative's match type, it is read as broad, the widest \"\n                      \"reading, so check those by hand.\"]\n    if lists:\n        lines += [\"\", \"Negatives in shared lists are not checked yet: this file does not say which campaigns use \"\n                      \"each list.\"]\n    return Check(title, rule, \"found\", f\"{n} {plural(len(found), 'conflict')}{note}\", lines)\n\n\ndef _rsa_assets(book, groups, ads, top):\n    title, rule = \"Headlines and descriptions\", \"search-rsa-asset-count\"\n    if ads is None:\n        return _missing(title, rule, \"ads\")\n    if not ads:\n        return Check(title, rule, \"passed\", \"No live responsive search ads\", [])\n    short = [a for a in ads if len(a[\"headlines\"]) < RSA_MAX_HEADLINES or len(a[\"descriptions\"]) < RSA_MAX_DESCRIPTIONS]\n    few = sum(1 for a in ads if len(a[\"headlines\"]) < RSA_FEW_HEADLINES)\n    if not short:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    s = book.count(\"live responsive search ads with empty headline or description slots\", len(short))\n    total = book.count(\"live responsive search ads\", len(ads))\n    slots = book.count(\"headline slots in a responsive search ad (Google)\", RSA_MAX_HEADLINES, \"rule\")\n    lines = [f\"Google: a responsive search ad holds up to {slots} headlines and {RSA_MAX_DESCRIPTIONS} descriptions, \"\n             \"and filling them gives the system more combinations to test. Optmyzr's open audit fails ads with \"\n             f\"fewer than {RSA_FEW_HEADLINES} headlines; here {book.count('live ads under that line', few)} \"\n             f\"{plural(few, 'ad is', 'ads are')} under it. Adalysis warns that a full ad makes more combinations \"\n             \"than a small account can test, so fill slots with genuinely different messages.\", \"\",\n             \"| Ad group | Headlines | Descriptions |\", \"|---|---|---|\"]\n    for a in sorted(short, key=lambda a: len(a[\"headlines\"]))[:top]:\n        g = groups[a[\"ad_group_id\"]][\"name\"]\n        h = book.count(f\"headlines in an ad in {g}\", len(a[\"headlines\"]), \"\", g)\n        d = book.count(f\"descriptions in an ad in {g}\", len(a[\"descriptions\"]), \"\", g)\n        lines.append(f\"| {esc(g)} | {h} | {d} |\")\n    return Check(title, rule, \"found\", f\"{s} of {total} ads\", lines)\n\n\ndef _rsa_per_group(book, groups, ads, top):\n    title, rule = \"Ads per ad group\", \"search-rsa-per-ad-group\"\n    if ads is None:\n        return _missing(title, rule, \"ads\")\n    per = Counter(a[\"ad_group_id\"] for a in ads)\n    thin = [g for g in groups.values() if per[g[\"id\"]] < MIN_RSAS_PER_AD_GROUP]\n    if not thin:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"live ad groups with fewer than 2 responsive search ads\", len(thin))\n    lines = [f\"Google: run at least {MIN_RSAS_PER_AD_GROUP} responsive search ads rated Good or Excellent in every \"\n             \"ad group (3 at most), so the system can compare them.\", \"\",\n             \"| Ad group | Live responsive search ads |\", \"|---|---|\"]\n    for g in sorted(thin, key=lambda g: per[g[\"id\"]])[:top]:\n        v = book.count(f\"live responsive search ads in {g['name']}\", per[g[\"id\"]], \"\", g[\"name\"])\n        lines.append(f\"| {esc(g['name'])} | {v} |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(thin), 'ad group')}\", lines)\n\n\ndef _pinning(book, ads):\n    title, rule = \"Pinning\", \"search-rsa-pinning\"\n    if ads is None:\n        return _missing(title, rule, \"ads\")\n    lone = full = 0\n    for a in ads:\n        pins = Counter(h[\"pin\"] for h in a[\"headlines\"] if h[\"pin\"])\n        lone += any(v == 1 for v in pins.values())\n        full += bool(a[\"headlines\"]) and all(h[\"pin\"] for h in a[\"headlines\"])\n    if not lone and not full:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    ln = book.count(\"ads with a position pinned to a single headline\", lone)\n    fn = book.count(\"ads with every headline pinned\", full)\n    lines = [f\"{ln} {plural(lone, 'ad pins', 'ads pin')} a position to a single headline, and {fn} \"\n             f\"{plural(full, 'ad pins', 'ads pin')} every headline. Google: pin only when you must, and then pin \"\n             \"2 or 3 headlines to the same position so the system still has a choice. Optmyzr's data found fully \"\n             \"pinned ads had the worst cost per conversion. Both sides are under \\\"Where Google and \"\n             \"practitioners disagree\\\".\"]\n    return Check(title, rule, \"found\", f\"{ln} with a lone pin, {fn} fully pinned\", lines)\n\n\ndef _singles(book, groups, kws, top):\n    title, rule = \"Single-keyword ad groups\", \"search-structure-themed-ad-groups\"\n    if not kws:\n        return _missing(title, rule, \"keywords\")\n    per = Counter(k[\"ad_group_id\"] for k in kws)\n    singles = [g for g in groups.values() if per[g[\"id\"]] == 1]\n    if not singles:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"live ad groups with a single keyword\", len(singles))\n    lines = [\"Google: group keywords into tightly themed ad groups, and fold single-keyword ad groups into \"\n             \"themed ones so Smart Bidding learns from pooled data. Restructure deliberately: moving keywords \"\n             \"resets their history.\", \"\", \"| Ad group | Live keywords |\", \"|---|---|\"]\n    for g in singles[:top]:\n        v = book.count(f\"live keywords in {g['name']}\", 1, \"\", g[\"name\"])\n        lines.append(f\"| {esc(g['name'])} | {v} |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(singles), 'ad group')}\", lines)\n\n\ndef _rarely_served(book, groups, kws, top):\n    title, rule = \"Keywords that rarely serve\", \"search-structure-cleanup\"\n    if not kws or all(k[\"serving\"] is None for k in kws):\n        return _missing(title, rule, \"keyword serving status\")\n    rare = [k for k in kws if k[\"serving\"] == \"RARELY_SERVED\"]\n    if not rare:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"live keywords Google marks as rarely served\", len(rare), \"\")\n    share = book.pct(\"share of live keywords that rarely serve\", len(rare) / len(kws) * 100, \"\")\n    one = len(rare) == 1\n    lines = [f\"{n} of {book.count('live keywords', len(kws), '')} live keywords ({share}) \"\n             f\"{'is' if one else 'are'} marked low search volume, so {'it almost never shows' if one else 'they almost never show'}. \"\n             \"Google's structure guide says to clean up non-serving keywords; many practitioners keep them only \"\n             \"when they are the exact wording customers use.\", \"\",\n             \"| Keyword | Match type | Ad group |\", \"|---|---|---|\"]\n    for k in rare[:top]:\n        _named(book, k[\"text\"], groups[k[\"ad_group_id\"]][\"name\"])\n        lines.append(f\"| {esc(k['text'])} | {nice(k['match_type'])} | {esc(groups[k['ad_group_id']]['name'])} |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(rare), 'keyword')} ({share})\", lines)\n\n\ndef _quality_parts(book, groups, kws, top):\n    title, rule = \"Quality Score parts below average\", \"search-quality-score-diagnostic\"\n    parts = ((\"expected_ctr\", \"Expected CTR\"), (\"ad_relevance\", \"Ad relevance\"), (\"landing_page\", \"Landing page\"))\n    if not kws or all(k[p] is None for k in kws for p, _ in parts):\n        return _missing(title, rule, \"Quality Score parts\")\n    weak = [k for k in kws if any(k[p] == \"BELOW_AVERAGE\" for p, _ in parts)]\n    if not weak:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"live keywords with a Quality Score part below average\", len(weak), \"\")\n    below = [(label[0].lower() + label[1:], sum(k[p] == \"BELOW_AVERAGE\" for k in kws)) for p, label in parts]\n    counts = \", \".join(f\"{label} {book.count('keywords below average on ' + label, v)}\" for label, v in below)\n    lines = [\"Google: use Quality Score's three parts as a diagnostic to find the weak link, not as a number to \"\n             f\"average. Below average here: {counts}. Expected CTR and ad relevance point at the ad copy; \"\n             \"landing page points at the page.\", \"\",\n             \"| Keyword | Expected CTR | Ad relevance | Landing page |\", \"|---|---|---|---|\"]\n    for k in weak[:top]:\n        _named(book, k[\"text\"])\n        lines.append(f\"| {esc(k['text'])} | \" + \" | \".join(nice(k[p]) for p, _ in parts) + \" |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(weak), 'keyword')}\", lines)\n\n\ndef _bidding(book, camps, kws):\n    title, rule = \"Bidding for clicks, not conversions\", \"bidding-ecpc-deprecated\"\n    if all(c[\"bidding\"] is None for c in camps.values()):\n        return _missing(title, rule, \"bid strategies\")\n    ecpc = [c for c in camps.values() if c[\"bidding\"] == \"ENHANCED_CPC\" or (c[\"bidding\"] == \"MANUAL_CPC\" and c[\"enhanced_cpc\"])]\n    clicks = [c for c in camps.values() if c[\"bidding\"] in CLICK_BIDDING and c not in ecpc]\n    if not ecpc and not clicks:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"live Search campaigns bidding for clicks\", len(ecpc) + len(clicks))\n    lines = [\"Google stopped Enhanced CPC for Search in March 2025, so those campaigns now run on plain Manual CPC. \"\n             \"Manual CPC and Maximize clicks bid for clicks, not conversions; Google suggests Maximize \"\n             \"conversions or Target CPA once conversion tracking works.\", \"\",\n             \"| Campaign | Bidding | Live keywords |\", \"|---|---|---|\"]\n    for c in ecpc + clicks:\n        label = \"Enhanced CPC (retired, now Manual CPC)\" if c in ecpc else nice(c[\"bidding\"])\n        v = book.count(f\"live keywords in {c['name']}\", sum(k[\"campaign_id\"] == c[\"id\"] for k in kws), \"\", c[\"name\"])\n        lines.append(f\"| {esc(c['name'])} | {label} | {v} |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(ecpc) + len(clicks), 'campaign')}\", lines)\n\n\ndef _display(book, camps, kws):\n    title, rule = \"Search campaigns on the Display Network\", \"struct-settings-consistency\"\n    if all(c[\"display_network\"] is None for c in camps.values()):\n        return _missing(title, rule, \"network settings\")\n    on = [c for c in camps.values() if c[\"display_network\"]]\n    if not on:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"live Search campaigns also showing on the Display Network\", len(on))\n    lines = [\"Practitioners keep Search campaigns off the Display Network: Display clicks are cheaper, convert \"\n             \"differently, and blur the Search numbers. Run Display in its own campaign.\", \"\",\n             \"| Campaign | Live keywords |\", \"|---|---|\"]\n    for c in on:\n        v = book.count(f\"live keywords in {c['name']}\", sum(k[\"campaign_id\"] == c[\"id\"] for k in kws), \"\", c[\"name\"])\n        lines.append(f\"| {esc(c['name'])} | {v} |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(on), 'campaign')}\", lines)\n\n\ndef _assets(book, camps, assets, top):\n    title, rule = \"Sitelinks, callouts and snippets\", \"assets-coverage\"\n    if assets is None:\n        return _missing(title, rule, \"assets\")\n    live = [a for a in assets if a[\"status\"] in (None, \"ENABLED\")]\n    base = Counter(a[\"type\"] for a in live if a[\"level\"] == \"ACCOUNT\")\n    short = []\n    for c in camps.values():\n        have = base + Counter(a[\"type\"] for a in live if a[\"level\"] == \"CAMPAIGN\" and a[\"owner_id\"] == c[\"id\"])\n        s, co, sn = have[\"SITELINK\"], have[\"CALLOUT\"], have[\"STRUCTURED_SNIPPET\"]\n        if s < MIN_SITELINKS or co < MIN_CALLOUTS or sn < MIN_SNIPPETS:\n            short.append((c, s, co, sn))\n    if not short:\n        return Check(title, rule, \"passed\", \"Passed\", [])\n    n = book.count(\"live Search campaigns short of sitelinks, callouts or snippets\", len(short))\n    lines = [f\"Google asks for at least {MIN_SITELINKS} sitelinks (6 for busy campaigns); Optmyzr's audit also wants \"\n             f\"{MIN_CALLOUTS} callouts and {MIN_SNIPPETS} structured snippet per Search campaign. Account-level assets \"\n             \"count for every campaign.\", \"\",\n             \"| Campaign | Sitelinks | Callouts | Structured snippets |\", \"|---|---|---|---|\"]\n    for c, s, co, sn in short[:top]:\n        cells = [book.count(f\"{kind} available to {c['name']}\", v, \"\", c[\"name\"])\n                 for kind, v in ((\"sitelinks\", s), (\"callouts\", co), (\"structured snippets\", sn))]\n        lines.append(f\"| {esc(c['name'])} | \" + \" | \".join(cells) + \" |\")\n    return Check(title, rule, \"found\", f\"{n} {plural(len(short), 'campaign')}\", lines)\n\n\ndef _location(book, camps):\n    title, rule = \"Location option\", \"set-location-presence\"\n    kinds = Counter(c[\"geo_target_type\"] for c in camps.values() if c[\"geo_target_type\"])\n    if not kinds:\n        return _missing(title, rule, \"location settings\")\n    parts = \", \".join(f\"{nice(k)} {book.count(f'live Search campaigns set to {nice(k)}', v)}\" for k, v in kinds.most_common())\n    return Check(title, rule, \"info\", f\"{parts} (see below)\", [])\n\n\ndef _disagreements(book, ads, camps, kws):\n    out = []\n    if ads:\n        strength = Counter(a[\"strength\"] for a in ads if a[\"strength\"])\n        mix = \", \".join(f\"{nice(s)} {book.count(f'live ads rated {nice(s)}', v)}\" for s, v in strength.most_common())\n        out.append(f\"- **Ad Strength.** Google says moving an ad from Poor to Excellent brings more conversions. \"\n                   f\"Optmyzr's study of thousands of accounts found Excellent ads had the worst cost per conversion \"\n                   f\"and Average ones the best. Judge ads on cost per conversion and conversions per impression. \"\n                   + (f\"Your live ads: {mix}.\" if mix else \"This file has no Ad Strength ratings.\"))\n        out.append(\"- **Pinning.** Google says most advertisers should not pin. Optmyzr found partial pinning had the \"\n                   \"best cost per conversion and full pinning the worst.\")\n    kinds = Counter(c[\"geo_target_type\"] for c in camps.values() if c[\"geo_target_type\"])\n    if kinds:\n        mix = \", \".join(f\"{nice(k)} {book.count(f'live Search campaigns set to {nice(k)}', v)}\" for k, v in kinds.most_common())\n        out.append(\"- **Location.** Google's default and recommendation is Presence or interest, which also reaches \"\n                   \"people who only searched about your area. Optmyzr's audit fails accounts that mostly use it and \"\n                   f\"wants Presence: people in or regularly in the area. Your live Search campaigns: {mix}.\")\n    types = Counter(k[\"match_type\"] for k in kws if k[\"match_type\"])\n    if types:\n        mix = \", \".join(f\"{nice(t)} {book.count(f'live keywords in {nice(t)} match', v, '')}\" for t, v in types.most_common())\n        out.append(\"- **Match types.** Google suggests simplifying to broad match under Smart Bidding. Optmyzr's study \"\n                   \"of tens of thousands of accounts found exact match the most efficient, phrase the workhorse, and \"\n                   f\"broad best for finding new searches. Your live keywords: {mix}.\")\n    return [\"\", \"## Where Google and practitioners disagree\", \"\"] + out if out else []\n\n\ndef _header(book, data):\n    meta = data.get(\"meta\", {})\n    bits = [f\"Source: `{os.path.basename(data.get('source', ''))}`\"]\n    if meta.get(\"account\"):\n        _named(book, meta[\"account\"])\n        bits.append(esc(meta[\"account\"]))\n    try:\n        d = date.fromisoformat(str(meta.get(\"captured\", \"\")))\n        bits.append(f\"captured {d:%B} {d.day}, {d.year}\")\n    except ValueError:\n        pass\n    bits.append(f\"currency {book.currency}\")\n    return [f\"# {TITLE}\", \"\", \" \u00b7 \".join(bits), \"\",\n            \"_Built by OpenPPC, read-only: computed from this file alone, with no network calls._\", \"\"]\n\n\ndef evaluate(data, brand=None, top=25):\n    \"\"\"Run every check. Returns (checks, book, live), where live counts what was judged.\"\"\"\n    book = FactBook((data.get(\"meta\", {}).get(\"currency\") or \"USD\").upper())\n    camps, groups, kws, ads_ = _live(data)\n    ads = None if data[\"ads\"] is None else ads_\n    checks = [_broad(book, camps, kws, top), _brand_mix(book, camps, kws, brand, top), _duplicates(book, groups, kws, top),\n              _conflicts(book, camps, groups, kws, data[\"negatives\"], top), _rsa_assets(book, groups, ads, top),\n              _rsa_per_group(book, groups, ads, top), _pinning(book, ads), _singles(book, groups, kws, top),\n              _rarely_served(book, groups, kws, top), _quality_parts(book, groups, kws, top),\n              _bidding(book, camps, kws), _display(book, camps, kws), _assets(book, camps, data[\"assets\"], top),\n              _location(book, camps)]\n    return checks, book, (camps, groups, kws, ads)\n\n\ndef run(data, brand=None, top=25, **_):\n    checks, book, (camps, groups, kws, ads) = evaluate(data, brand, top)\n    judged = [c for c in checks if c.status in (\"found\", \"passed\")]\n    found = [c for c in judged if c.status == \"found\"]\n    out = _header(book, data)\n    counts = [book.count(\"live Search campaigns\", len(camps)), book.count(\"live ad groups\", len(groups)),\n              book.count(\"live keywords\", len(kws), \"\"), book.count(\"live responsive search ads\", len(ads or []))]\n    out += [\"## Summary\", \"\",\n            f\"Live Search: {counts[0]} {plural(len(camps), 'campaign')}, {counts[1]} {plural(len(groups), 'ad group')}, \"\n            f\"{counts[2]} {plural(len(kws), 'keyword')} and {counts[3]} responsive search {plural(len(ads or []), 'ad')}.\", \"\",\n            f\"**{book.count('checks that found something', len(found))} of {book.count('checks run', len(judged))} \"\n            f\"checks found something.**\", \"\", \"| Check | Result | Rule |\", \"|---|---|---|\"]\n    out += [f\"| {c.title} | {c.summary} | `{c.rule}` |\" for c in checks]\n    for c in found:\n        out += [\"\", f\"### {c.title}\", \"\"] + c.lines\n    out += _disagreements(book, ads, camps, kws)\n    out += [\"\", \"## How this was computed\", \"\",\n            \"- Live means the keyword or ad, its ad group and its campaign are all enabled. Only Search campaigns \"\n            \"are judged; Performance Max and other campaign types are left out.\",\n            \"- Every check is a row in OpenPPC's rulebook (`rulebook/rules.csv`); the Rule column is its id, with \"\n            \"the source and the exact threshold.\",\n            \"- Negatives are compared with your keyword text: an exact negative must match the whole keyword, a \"\n            \"phrase negative its words in order, a broad negative every word in any order.\",\n            \"- A check marked \\\"not in this file\\\" was not run: the file lacks what it needs. It is not a pass.\"]\n    return out, book\n","openppc/templates/keyword_audit.py":"\"\"\"Keyword audit: where the budget goes by keyword and match type, and what it buys.\n\nInput: a Keywords report. Add the Quality Score column before you export if you want\nthe Quality Score section. Every figure below is computed from that file alone.\n\"\"\"\nfrom ..engine import benchmarks\nfrom ..facts import FactBook\nfrom ._common import brand_matcher, conv_dp, esc, header, min_cost_for, need, plural, totals, val\n\nNAME = \"keyword-audit\"\nTITLE = \"Keyword audit\"\nTIER = \"free\"\nINPUT_KIND = \"report\"\nINPUT = \"Keywords report (.csv)\"\nSUMMARY = (\"Keywords spending without converting, budget and results by match type, \"\n           \"and spend on low Quality Scores.\")\nHOW_TO_EXPORT = (\"In Google Ads: Campaigns > Audiences, keywords and content > Search keywords, pick the \"\n                 \"date range, then Download > .csv. Add the Quality Score column first for that section.\")\nTOP_CONVERTERS = 5\n\n\ndef accepts(report):\n    return report.has(\"keyword\", \"clicks\", \"cost\", \"conversions\")\n\n\ndef run(report, min_cost=None, industry=None, low_qs=4, top=25, brand=None, **_):\n    need(report, \"keyword\", \"Keywords report\", HOW_TO_EXPORT)\n    book = FactBook(report.currency)\n    known_default = True\n    if min_cost is None:\n        min_cost, known_default = min_cost_for(report.currency)\n    rows = [r for r in report.rows if r.get(\"keyword\")]\n    grand = totals(rows)\n    out = header(book, report, TITLE)\n    total_cost = book.money(\"total cost\", grand.cost)\n    min_s = book.money(\"minimum cost for a no-conversion flag (rule)\", min_cost, \"rule\")\n    cpa = grand.cost / grand.conversions if grand.conversions else None\n    if not known_default:\n        out += [f\"_OpenPPC has no default threshold for {report.currency}, so it used {min_s}. \"\n                \"Set your own with `--min-cost`._\", \"\"]\n\n    clicks = book.count(\"total clicks\", grand.clicks, \"clicks\")\n    convs = book.count(\"total conversions\", grand.conversions, \"conversions\", dp=conv_dp(grand.conversions))\n    line = f\"This export covers {total_cost} of cost, {clicks} clicks and {convs} conversions\"\n    if cpa:\n        line += f\", or {book.money('account cost per conversion', cpa, 'cpa')} per conversion\"\n    out += [\"## Summary\", \"\", line + \".\"]\n\n    is_brand = brand_matcher(brand)\n    spared = [r for r in rows if not val(r, \"conversions\") and val(r, \"cost\") >= min_cost and is_brand(r[\"keyword\"])]\n    zero = sorted((r for r in rows if not val(r, \"conversions\") and val(r, \"cost\") >= min_cost\n                   and not is_brand(r[\"keyword\"])), key=lambda r: -val(r, \"cost\"))\n    if spared:\n        sn = book.count(\"brand keywords left out of the zero-conversion list\", len(spared), \"terms\")\n        out += [\"\", f\"{sn} brand {plural(len(spared), 'keyword')} with zero conversions {'is' if len(spared) == 1 else 'are'} \"\n                    \"left out below: pausing brand keywords hands those searches to competitors.\"]\n    if zero and grand.cost:\n        zt = totals(zero)\n        n = book.count(\"keywords flagged (zero conversions, at or above the threshold)\", len(zero))\n        zc = book.money(\"cost of flagged zero-conversion keywords\", zt.cost)\n        share = book.pct(\"flagged zero-conversion cost as a share of total cost\", zt.cost / grand.cost * 100, \"cost\")\n        out += [\"\", f\"**{n} {plural(len(zero), 'keyword')} spent {zc} with zero conversions.** \"\n                    f\"That is {share} of total cost.\",\n                \"\", \"## Keywords spending without converting\", \"\",\n                \"| Keyword | Match type | Cost | Clicks | Quality Score |\", \"|---|---|---|---|---|\"]\n        for r in zero[:top]:\n            kw = r[\"keyword\"]\n            c = book.money(f\"cost of '{kw}'\", val(r, \"cost\"), \"cost\", kw)\n            k = book.count(f\"clicks of '{kw}'\", val(r, \"clicks\"), \"clicks\", kw)\n            qs = r.get(\"quality_score\")\n            q = book.count(f\"Quality Score of '{kw}'\", qs, \"quality\", kw) if qs is not None else \"--\"\n            out.append(f\"| {esc(kw)} | {esc(r.get('match_type', ''))} | {c} | {k} | {q} |\")\n\n    if report.has(\"match_type\") and grand.cost:\n        groups = {}\n        for r in rows:\n            groups.setdefault(r.get(\"match_type\") or \"unknown\", []).append(r)\n        out += [\"\", \"## Budget by match type\", \"\",\n                \"| Match type | Cost | Share of total cost | Conversions | Cost per conversion |\",\n                \"|---|---|---|---|---|\"]\n        for mt, members in sorted(groups.items(), key=lambda kv: -totals(kv[1]).cost):\n            t = totals(members)\n            c = book.money(f\"cost of {mt}\", t.cost, \"cost\", mt)\n            s = book.pct(f\"{mt} share of total cost\", t.cost / grand.cost * 100, \"cost\", mt)\n            v = book.count(f\"conversions of {mt}\", t.conversions, \"conversions\", mt, dp=conv_dp(t.conversions))\n            p = book.money(f\"cost per conversion of {mt}\", t.cost / t.conversions, \"cpa\", mt) if t.conversions else \"--\"\n            out.append(f\"| {esc(mt)} | {c} | {s} | {v} | {p} |\")\n\n    scored = [r for r in rows if r.get(\"quality_score\") is not None]\n    if scored:\n        low = sorted((r for r in scored if r[\"quality_score\"] <= low_qs), key=lambda r: -val(r, \"cost\"))\n        out += [\"\", \"## Quality Score\", \"\"]\n        if low and grand.cost:\n            lt = totals(low)\n            n = book.count(\"keywords at or below the Quality Score threshold\", len(low))\n            c = book.money(\"cost of low Quality Score keywords\", lt.cost)\n            s = book.pct(\"low Quality Score cost as a share of total cost\", lt.cost / grand.cost * 100, \"cost\")\n            out += [f\"{n} {plural(len(low), 'keyword')} with a Quality Score of {low_qs} or lower spent {c}. \"\n                    f\"That is {s} of total cost. \"\n                    \"Low scores usually mean paying more for the same ad position.\", \"\",\n                    \"| Keyword | Quality Score | Cost | Conversions |\", \"|---|---|---|---|\"]\n            for r in low[:top]:\n                kw = r[\"keyword\"]\n                q = book.count(f\"Quality Score of '{kw}'\", r[\"quality_score\"], \"quality\", kw)\n                c = book.money(f\"cost of '{kw}'\", val(r, \"cost\"), \"cost\", kw)\n                v = book.count(f\"conversions of '{kw}'\", val(r, \"conversions\"), \"conversions\", kw,\n                               dp=conv_dp(val(r, \"conversions\")))\n                out.append(f\"| {esc(kw)} | {q} | {c} | {v} |\")\n        else:\n            out.append(f\"No keyword has a Quality Score of {low_qs} or lower. Nothing to fix here.\")\n\n    converters = sorted((r for r in rows if val(r, \"conversions\")), key=lambda r: -val(r, \"conversions\"))\n    if converters:\n        out += [\"\", \"## Top converting keywords\", \"\",\n                \"| Keyword | Match type | Conversions | Cost per conversion |\", \"|---|---|---|---|\"]\n        for r in converters[:TOP_CONVERTERS]:\n            kw = r[\"keyword\"]\n            v = book.count(f\"conversions of '{kw}'\", val(r, \"conversions\"), \"conversions\", kw,\n                           dp=conv_dp(val(r, \"conversions\")))\n            p = book.money(f\"cost per conversion of '{kw}'\", val(r, \"cost\") / val(r, \"conversions\"), \"cpa\", kw)\n            out.append(f\"| {esc(kw)} | {esc(r.get('match_type', ''))} | {v} | {p} |\")\n\n    if industry:\n        out += benchmarks.section(book, industry, cost=grand.cost, clicks=grand.clicks,\n                                  impressions=grand.impressions, conversions=grand.conversions,\n                                  currency=report.currency)\n\n    out += [\"\", \"## How this was computed\", \"\",\n            f\"- Spending without converting: zero conversions and at least {min_s} in cost.\",\n            f\"- Low Quality Score: {low_qs} or lower, on keywords that have a score.\",\n            \"- Totals are recomputed from the rows. The Total lines in Google's export are ignored.\",\n            \"- A conversion is whatever this account counts as one. If that includes small actions such as \"\n            \"page views, zero conversions means something weaker here.\"]\n    return out, book\n","openppc/templates/search_term_waste.py":"\"\"\"Search-term waste: the searches you paid for that never converted.\n\nInput: a Search terms report. Every figure below is computed from that file alone and\nprinted only after it is registered as a fact the checker can trace.\n\"\"\"\nimport os\nimport re\n\nfrom ..engine import benchmarks, waste_model\nfrom ..facts import FactBook\nfrom ._common import (brand_matcher, conv_dp, esc, fingerprint, header, min_cost_for, month_label, need, period,\n                      plural, totals, val)\n\nNAME = \"search-term-waste\"\nTITLE = \"Search-term waste audit\"\nTIER = \"free\"\nINPUT_KIND = \"report\"\nINPUT = \"Search terms report (.csv)\"\nSUMMARY = (\"Search terms that spent money and never converted, ranked by cost, the words behind \"\n           \"the long tail, plus expensive converters and terms worth adding as keywords.\")\nHOW_TO_EXPORT = (\"In Google Ads: Campaigns > Insights and reports > Search terms, pick the date range, \"\n                 \"then Download > .csv.\")\nEXPENSIVE = 3          # converting, but at more than this multiple of the account's cost per conversion\nHARVEST_MIN = 2        # conversions needed before a search term is worth adding as a keyword\nTHEME_MIN_TERMS = 3    # a word counts as a theme when it shows up in at least this many search terms\nTHEME_MIN_COST = 5.0   # ...and those terms cost at least this much together\nTHEMES_SHOWN = 10\nTHEME_COVER = 0.8      # a phrase that carries this share of a word's cost stands in for the word\nALIKE_CLICKS = 2_000   # needing more clicks than this to be sure means the account's terms convert alike\nPMAX_NEGATIVES = 10_000  # Google's cap on negative keywords per Performance Max campaign\nCLIENT_TITLE = \"Search-term review\"  # the branded report's default title\nSTEP_TAGS = {\"negative\": \"Block\", \"watch\": \"Watch\", \"review\": \"Review\", \"add\": \"Grow\"}\nSTEP_COUNT = {1: \"One step to take.\", 2: \"Two steps, most useful first.\", 3: \"Three steps, most useful first.\"}\nLONG_NAMES = {\"CPC\": \"Cost per click\", \"CTR\": \"Click-through rate\", \"Conversion rate\": \"Conversion rate\",\n              \"Cost per conversion\": \"Cost per conversion\"}\nHOW_IT_COMPARES = {\"CPC\": (\"pays less per click\", \"pays more per click\"),\n                   \"CTR\": (\"gets clicked less often\", \"gets clicked more often\"),\n                   \"Conversion rate\": (\"converts less often\", \"converts more often\"),\n                   \"Cost per conversion\": (\"pays less per conversion\", \"pays more per conversion\")}\nSTOPWORDS = frozenset(\"a an and are at best by can do does for from get how i in is it me my near of on \"\n                      \"or the to what where who why with you your\".split())\n\n\ndef accepts(report):\n    return report.has(\"search_term\", \"clicks\", \"cost\", \"conversions\")\n\n\ndef _cpa(row):\n    conversions = val(row, \"conversions\")\n    return val(row, \"cost\") / conversions if conversions else None\n\n\ndef _not_yet_added(row):\n    return (row.get(\"added_excluded\") or \"none\").strip().lower() in (\"none\", \"\")\n\n\ndef _automated(row):\n    \"\"\"Performance Max and other automated campaigns, where negatives work differently from Search.\"\"\"\n    return (row.get(\"campaign_type\") or \"search\").strip().lower() not in (\"search\", \"\")\n\n\ndef _by_term(rows):\n    \"\"\"One row per search term. Google's report lists a term once for each campaign, ad group and match type it\n    showed in, so the rows are added up before anything is judged: a term that converts on any of its rows is\n    never waste, and one whose cost is split across rows is judged on its total.\"\"\"\n    merged = {}\n    for r in rows:\n        key = \" \".join(r[\"search_term\"].lower().split())\n        m = merged.get(key)\n        if m is None:\n            m = merged[key] = {\"search_term\": r[\"search_term\"].strip(), \"cost\": 0.0, \"clicks\": 0.0, \"impressions\": 0.0,\n                               \"conversions\": 0.0, \"search_cost\": 0.0, \"automated_cost\": 0.0, \"search_rows\": 0,\n                               \"automated_rows\": 0, \"_match\": [], \"_type\": [], \"_campaign\": [], \"_added\": []}\n        for k in (\"cost\", \"clicks\", \"impressions\", \"conversions\"):\n            m[k] += val(r, k)\n        side = \"automated\" if _automated(r) else \"search\"\n        m[side + \"_cost\"] += val(r, \"cost\")\n        m[side + \"_rows\"] += 1\n        for field, column in ((\"_match\", \"match_type\"), (\"_type\", \"campaign_type\"), (\"_campaign\", \"campaign\"),\n                              (\"_added\", \"added_excluded\")):\n            v = (r.get(column) or \"\").strip()\n            if v and v not in m[field]:\n                m[field].append(v)\n    terms = []\n    for m in merged.values():\n        m[\"group\"] = \"search\" if not m[\"automated_rows\"] else \"automated\" if not m[\"search_rows\"] else \"both\"\n        m[\"match_type\"] = \", \".join(m.pop(\"_match\"))\n        m[\"campaign_type\"] = \", \".join(m.pop(\"_type\"))\n        campaigns = m.pop(\"_campaign\")\n        m[\"campaign\"] = campaigns[0] if len(campaigns) == 1 else f\"{len(campaigns)} campaigns\" if campaigns else \"\"\n        added = [a for a in m.pop(\"_added\") if a.lower() != \"none\"]\n        m[\"added_excluded\"] = added[0] if added else \"None\"\n        terms.append(m)\n    return terms\n\n\ndef _themes(rows):\n    \"\"\"Words and two-word phrases that recur across search terms and never convert.\"\"\"\n    stats = {}\n    for r in rows:\n        words = re.findall(r\"[a-z]+(?:'[a-z]+)?\", r[\"search_term\"].lower())\n        grams = {w for w in words if len(w) >= 3 and w not in STOPWORDS}\n        grams |= {f\"{a} {b}\" for a, b in zip(words, words[1:])\n                  if len(a) >= 2 and len(b) >= 2 and a not in STOPWORDS and b not in STOPWORDS}\n        for g in grams:\n            s = stats.setdefault(g, [0, 0, 0.0, 0.0])  # search terms, clicks, cost, conversions\n            s[0] += 1\n            s[1] += val(r, \"clicks\")\n            s[2] += val(r, \"cost\")\n            s[3] += val(r, \"conversions\")\n    found = {g: s for g, s in stats.items()\n             if not s[3] and s[0] >= THEME_MIN_TERMS and s[2] >= THEME_MIN_COST}\n    phrases = [g for g in found if \" \" in g]\n    # \"riverside park\" says more than \"riverside\" or \"park\" alone: drop a word a phrase already covers\n    kept = [g for g in found if \" \" in g\n            or not any(g in p.split() and found[p][2] >= THEME_COVER * found[g][2] for p in phrases)]\n    shown = []\n    for g in sorted(kept, key=lambda g: (-found[g][2], -found[g][0], g)):\n        words = g.split()\n        if len(words) > 1 and any(  # a listed word already covers this phrase, or a listed phrase overlaps it\n                w in shown or any(w in s.split() and found[s][2] >= THEME_COVER * found[g][2] for s in shown if \" \" in s)\n                for w in words):\n            continue\n        shown.append(g)\n    return shown[:THEMES_SHOWN], found\n\n\ndef _chance_text(book, term, p):\n    if p is None:\n        return \"--\"\n    if p >= 0.995:  # never print 100%: the model is sure, not certain\n        return book.pct(f\"chance '{term}' is a bad search term, at least\", 99, \"\", term, dp=0) + \"+\"\n    return book.pct(f\"chance '{term}' is a bad search term\", p * 100, \"\", term, dp=0)\n\n\ndef _waste_table(book, members, grand, automated, chance):\n    cols = (\"| Search term | Cost | Clicks | Share of total cost | Chance it's bad | Match type |\"\n            + (\" Campaign type |\" if automated else \"\"))\n    out = [cols, \"|---|---|---|---|---|---|\" + (\"---|\" if automated else \"\")]\n    for r in members:\n        t = r[\"search_term\"]\n        c = book.money(f\"cost of '{t}'\", val(r, \"cost\"), \"cost\", t)\n        k = book.count(f\"clicks of '{t}'\", val(r, \"clicks\"), \"clicks\", t)\n        s = book.pct(f\"'{t}' share of total cost\", val(r, \"cost\") / grand.cost * 100, \"cost\", t)\n        b = _chance_text(book, t, chance.get(id(r)))\n        row = f\"| {esc(t)} | {c} | {k} | {s} | {b} | {esc(r.get('match_type', ''))} |\"\n        out.append(row + (f\" {esc(r.get('campaign_type', ''))} |\" if automated else \"\"))\n    return out\n\n\ndef _actions(book, waste, sure, chance, prior, needed, bar, pricey, harvest, cpa_s):\n    \"\"\"The report's to-do list. Each step reuses numbers the report already registered, so the\n    number check covers these sentences like any other.\"\"\"\n    out = []\n    if waste and prior:\n        if sure:\n            m = len(sure)\n            lead = max(sure, key=lambda r: val(r, \"cost\"))[\"search_term\"]\n            spent = book.money(\"cost of the waste terms the model is sure about\", totals(sure).cost)\n            rest = len(waste) - m\n            one = m == 1\n            detail = (f\"The waste model is at least {bar} sure about {'it' if one else 'them'}, and {'it' if one else 'they'} \"\n                      f\"spent {spent}. \\u201c{lead}\\u201d {'is the one' if one else 'leads'}.\")\n            if rest:\n                detail += f\" The other {book.count('waste terms too early to judge', rest)} are too early to judge.\"\n            m_s = book.count(\"waste terms the waste model is sure about\", m)\n            out.append({\"kind\": \"negative\", \"title\": f\"Add {m_s} negative {plural(m, 'keyword')}\", \"detail\": detail})\n        else:\n            n = len(waste)\n            n_s = book.count(\"search terms flagged as waste\", n)\n            if needed is None or needed > ALIKE_CLICKS:\n                detail = (\"Terms in this account convert at much the same rate, so a search term's missing conversions \"\n                          \"are most likely bad luck.\")\n            else:\n                best = max(waste, key=lambda r: chance.get(id(r), 0))\n                t = best[\"search_term\"]\n                pct = _chance_text(book, t, chance.get(id(best)))\n                clicks = book.count(f\"clicks of '{t}'\", val(best, \"clicks\"), \"clicks\", t)\n                need_s = book.count(\"clicks a search term needs before the waste model is sure it is bad\", needed, \"clicks\")\n                detail = (f\"None is proven bad yet. The closest, \\u201c{t}\\u201d, is {pct} likely bad after {clicks} clicks. \"\n                          f\"The waste model needs about {need_s} clicks with no conversion to be {bar} sure.\")\n            out.append({\"kind\": \"watch\", \"title\": f\"Give {n_s} {plural(n, 'term')} more clicks before adding negatives\",\n                        \"detail\": detail})\n    if pricey:\n        t = pricey[0][\"search_term\"]\n        p = book.money(f\"cost per conversion of '{t}'\", _cpa(pricey[0]), \"cpa\", t)\n        k = len(pricey)\n        k_s = book.count(\"search terms converting at an expensive rate\", k)\n        why = f\"it converts, but at {p} each, more than {EXPENSIVE} times the {cpa_s} average.\"\n        out.append({\"kind\": \"review\", \"title\": f\"Review \\u201c{t}\\u201d\" if k == 1 else f\"Review {k_s} expensive converters\",\n                    \"detail\": why[0].upper() + why[1:] if k == 1 else f\"\\u201c{t}\\u201d leads: {why}\"})\n    if harvest:\n        r = harvest[0]\n        t = r[\"search_term\"]\n        k = len(harvest)\n        k_s = book.count(\"search terms worth adding as keywords\", k)\n        v = book.count(f\"conversions of '{t}'\", val(r, \"conversions\"), \"conversions\", t, dp=conv_dp(val(r, \"conversions\")))\n        p = book.money(f\"cost per conversion of '{t}'\", _cpa(r), \"cpa\", t)\n        out.append({\"kind\": \"add\", \"title\": f\"Add {k_s} converting {plural(k, 'term')} as keywords\",\n                    \"detail\": f\"\\u201c{t}\\u201d leads with {v} conversions at {p} each.\"})\n    return out\n\n\ndef _cards(book, grand, waste, sure, chance, top, wc, share, d, y, cpa_s, industry, actions):\n    \"\"\"The same results as data for the web app. Every number is a string the FactBook printed.\"\"\"\n    bench = benchmarks.lookup(industry) if industry else None\n    dollars = (book.currency or \"USD\").upper() == \"USD\"  # the industry's cost per conversion is in US dollars\n    kpis = []\n    if wc:\n        n = book.count(\"search terms flagged as waste\", len(waste))\n        kpis.append({\"label\": \"Wasted spend\", \"value\": wc, \"note\": f\"{n} {plural(len(waste), 'term')}, zero conversions\"})\n        kpis.append({\"label\": \"Share of total cost\", \"value\": share, \"note\": f\"of {book.money('total cost', grand.cost)}\"})\n    if y:\n        kpis.append({\"label\": \"A year at this rate\", \"value\": y, \"note\": f\"{d} a day\"})\n    if cpa_s:\n        note = (f\"vs {book.money(bench['name'] + ' average Cost per conversion', bench['cpl'], 'cpa')} industry\"\n                if bench and dollars else \"account average\")\n        kpis.append({\"label\": \"Cost per conversion\", \"value\": cpa_s, \"note\": note})\n    if grand.impressions:\n        ctr = book.pct(\"CTR of the account\", grand.clicks / grand.impressions * 100, \"ctr\", dp=2)\n        note = f\"vs {book.pct(bench['name'] + ' average CTR', bench['ctr'], 'ctr', dp=2)} industry\" if bench else \"account average\"\n        kpis.append({\"label\": \"CTR\", \"value\": ctr, \"note\": note})\n    rows = []\n    for r in waste[:top]:\n        t = r[\"search_term\"]\n        p = chance.get(id(r))\n        rows.append({\"term\": t, \"cost\": book.money(f\"cost of '{t}'\", val(r, \"cost\"), \"cost\", t),\n                     \"clicks\": book.count(f\"clicks of '{t}'\", val(r, \"clicks\"), \"clicks\", t),\n                     \"share\": book.pct(f\"'{t}' share of total cost\", val(r, \"cost\") / grand.cost * 100, \"cost\", t),\n                     \"chance\": _chance_text(book, t, p), \"p\": p, \"sure\": any(r is x for x in sure),\n                     \"match_type\": r.get(\"match_type\", \"\"), \"campaign\": r.get(\"campaign\", \"\"),\n                     \"campaign_type\": r.get(\"campaign_type\", \"\"), \"automated\": r[\"group\"] != \"search\"})\n    return {\"template\": NAME, \"kpis\": kpis, \"actions\": actions, \"waste\": rows, \"waste_total\": len(waste)}\n\n\ndef _and(parts):\n    return parts[0] if len(parts) == 1 else \", \".join(parts[:-1]) + \" and \" + parts[-1]\n\n\ndef _client(book, report, x):\n    \"\"\"The branded client report: a cover headline and four sections of blocks, in the agency's voice.\n    The web app lays the blocks out on pages; every number is registered, and the app checks the text\n    of the finished pages against this FactBook before it lets the PDF out.\"\"\"\n    waste, sure, chance, prior, needed, bar = x[\"waste\"], x[\"sure\"], x[\"chance\"], x[\"prior\"], x[\"needed\"], x[\"bar\"]\n    wc, cpa_s, min_s, top = x[\"wc\"], x[\"cpa_s\"], x[\"min_s\"], x[\"top\"]\n    n = len(waste)\n    n_s = book.count(\"search terms flagged as waste\", n) if n else None\n\n    stats = [(x[\"share\"], \"of total cost\"), (x[\"y\"], \"a year at this rate\"), (cpa_s, \"per conversion\")]\n    if wc:\n        headline = {\"value\": wc, \"text\": f\"went to {n_s} {plural(n, 'search term')} that never converted.\",\n                    \"stats\": [{\"value\": v, \"label\": label} for v, label in stats if v]}\n    else:\n        headline = {\"value\": None, \"text\": f\"No search term with zero conversions reached {min_s} in cost.\",\n                    \"stats\": [{\"value\": v, \"label\": label} for v, label in\n                              ((x[\"total_cost\"], \"total cost\"), (cpa_s, \"per conversion\")) if v]}\n\n    found = []\n    if wc:\n        text = (f\"That is {x['share']} of the {x['total_cost']} total cost in this export, and each one cost at \"\n                f\"least {min_s}.\")\n        if x[\"d\"]:\n            text += f\" At the same rate that is {x['d']} a day, or {x['y']} a year.\"\n        found.append({\"type\": \"lead\", \"strong\": f\"{n_s} {plural(n, 'search term')} spent {wc} and never converted.\",\n                      \"text\": text})\n        if x[\"sw\"] and x[\"aw\"]:\n            found.append({\"type\": \"p\", \"text\": f\"Of that, {x['sw']} is in Search campaigns and {x['aw']} in Performance \"\n                                               \"Max and other automated campaigns, which take negatives differently.\"})\n        if prior:\n            if needed is None or needed > ALIKE_CLICKS:\n                why = (\"Search terms in this account convert at much the same rate, so one term's missing \"\n                       \"conversions are most likely bad luck.\")\n            elif sure:\n                m_s = book.count(\"waste terms the waste model is sure about\", len(sure))\n                mc = book.money(\"cost of the waste terms the model is sure about\", totals(sure).cost)\n                why = f\"We are at least {bar} sure about {m_s} of them, which spent {mc}.\"\n                if n > len(sure):\n                    rest = book.count(\"waste terms too early to judge\", n - len(sure))\n                    why += f\" The other {rest} have too few clicks yet to tell a bad term from bad luck.\"\n            else:\n                why = (\"None of them has had enough clicks yet to prove it is bad rather than unlucky, so these are \"\n                       \"terms to watch, not to block yet.\")\n            found.append({\"type\": \"p\", \"text\": why})\n        most = val(waste[0], \"cost\") or 1\n        rows = []\n        for r in waste[:top]:\n            t = r[\"search_term\"]\n            p_bad = chance.get(id(r))\n            rows.append({\"label\": t, \"value\": book.money(f\"cost of '{t}'\", val(r, \"cost\"), \"cost\", t),\n                         \"width\": round(val(r, \"cost\") / most * 100, 1),\n                         \"tag\": f\"{_chance_text(book, t, p_bad)} likely bad\" if p_bad is not None else \"\",\n                         \"strong\": any(r is s for s in sure)})\n        caption = \"Bar length is cost.\"\n        if bar:\n            caption += (\" Likely bad is the chance a term converts at under half the account's rate, given its \"\n                        f\"clicks so far. We add a negative once a term reaches {bar}.\")\n        found.append({\"type\": \"bars\", \"title\": \"Wasted spend, ranked\", \"cols\": [\"Cost\", \"Likely bad\" if bar else \"\"],\n                      \"rows\": rows, \"caption\": caption})\n        if n > top:\n            k = book.count(\"waste terms beyond the table\", n - top)\n            c = book.money(\"cost of waste terms beyond the table\", totals(waste[top:]).cost)\n            found.append({\"type\": \"note\", \"text\": f\"Plus {k} more {plural(n - top, 'term')} that spent {c} in total.\"})\n    else:\n        found.append({\"type\": \"lead\", \"strong\": f\"No search term with zero conversions reached {min_s} in cost.\",\n                      \"text\": \"There is nothing to cut one term at a time at this threshold.\"})\n    if x[\"small\"]:\n        st = totals(x[\"small\"])\n        k = book.count(\"zero-conversion terms below the threshold\", len(x[\"small\"]))\n        c = book.money(\"cost of zero-conversion terms below the threshold\", st.cost)\n        found.append({\"type\": \"note\", \"text\": f\"Below the {min_s} threshold, {k} more zero-conversion \"\n                                              f\"{plural(len(x['small']), 'term')} spent {c} in total.\"})\n    if x[\"brand_rows\"]:\n        bt = totals(x[\"brand_rows\"])\n        bn = book.count(\"search terms that match your brand\", len(x[\"brand_rows\"]), \"terms\")\n        bc = book.money(\"cost of search terms that match your brand\", bt.cost, \"cost\")\n        bv = book.count(\"conversions of search terms that match your brand\", bt.conversions, \"conversions\",\n                        dp=conv_dp(bt.conversions))\n        found.append({\"type\": \"note\", \"text\": f\"Searches for the brand are never counted as waste: {bn} \"\n                                              f\"{plural(len(x['brand_rows']), 'search term')} matched it, cost {bc} \"\n                                              f\"and brought {bv} conversions.\"})\n    if x[\"names\"]:\n        found.append({\"type\": \"h2\", \"text\": \"Words that never convert\"})\n        found.append({\"type\": \"p\", \"text\": \"These words show up across several search terms that spent money without \"\n                                           \"a single conversion. Each is a candidate negative keyword once it is \"\n                                           \"checked against what the business sells.\"})\n        table = []\n        for g in x[\"names\"]:\n            terms, clicks_g, cost_g, _ = x[\"found\"][g]\n            label = f'search terms containing \"{g}\"'\n            table.append([g, book.count(f\"number of {label}\", terms, \"terms\", g),\n                          book.count(f\"clicks of {label}\", clicks_g, \"clicks\", g),\n                          book.money(f\"cost of {label}\", cost_g, \"cost\", g)])\n        found.append({\"type\": \"table\", \"cols\": [\"Word or phrase\", \"Search terms\", \"Clicks\", \"Cost\"],\n                      \"align\": [\"left\", \"right\", \"right\", \"right\"], \"rows\": table})\n    totals_row = [{\"value\": x[\"total_cost\"], \"label\": \"cost\"}, {\"value\": x[\"clicks\"], \"label\": \"clicks\"},\n                  {\"value\": x[\"convs\"], \"label\": \"conversions\"}]\n    if cpa_s:\n        totals_row.append({\"value\": cpa_s, \"label\": \"per conversion\"})\n    found.append({\"type\": \"stats\", \"title\": \"Account totals in this export\", \"items\": totals_row})\n\n    steps = []\n    if waste and prior:\n        if sure:\n            m, one = len(sure), len(sure) == 1\n            lead = max(sure, key=lambda r: val(r, \"cost\"))[\"search_term\"]\n            spent = book.money(\"cost of the waste terms the model is sure about\", totals(sure).cost)\n            text = (f\"We are at least {bar} sure {'it is' if one else 'they are'} bad, and {'it' if one else 'they'} \"\n                    f\"spent {spent}. \u201c{lead}\u201d {'is the one' if one else 'leads'}.\")\n            if n > m:\n                text += f\" The other {book.count('waste terms too early to judge', n - m)} are too early to judge.\"\n            m_s = book.count(\"waste terms the waste model is sure about\", m)\n            steps.append({\"kind\": \"negative\", \"title\": f\"Add {m_s} negative {plural(m, 'keyword')}\", \"text\": text})\n        else:\n            title = f\"Watch the {n_s} {plural(n, 'term')} before adding negatives\"\n            if needed is None or needed > ALIKE_CLICKS:\n                text = (\"Terms in this account convert at much the same rate, so a search term's missing conversions \"\n                        \"are most likely bad luck.\")\n            else:\n                best = max(waste, key=lambda r: chance.get(id(r), 0))\n                t = best[\"search_term\"]\n                pct = _chance_text(book, t, chance.get(id(best)))\n                clicks_b = book.count(f\"clicks of '{t}'\", val(best, \"clicks\"), \"clicks\", t)\n                if n == 1:\n                    text = f\"\\u201c{t}\\u201d spent {wc} with no conversions, and it is {pct} likely bad after {clicks_b} clicks.\"\n                else:\n                    text = (f\"They spent {wc} with no conversions, but none is {bar} likely bad yet. The closest, \"\n                            f\"\u201c{t}\u201d, is {pct} likely bad after {clicks_b} clicks.\")\n                text += (f\" A term needs about {x['need_s']} clicks (about {x['need_cost']}) with no conversion before \"\n                         f\"we can be {bar} sure.\")\n            steps.append({\"kind\": \"watch\", \"title\": title, \"text\": text})\n    if x[\"pricey\"]:\n        pricey = x[\"pricey\"][:top]\n        t = pricey[0][\"search_term\"]\n        if len(x[\"pricey\"]) == 1:\n            r = pricey[0]\n            p = book.money(f\"cost per conversion of '{t}'\", _cpa(r), \"cpa\", t)\n            c = book.money(f\"cost of '{t}'\", val(r, \"cost\"), \"cost\", t)\n            v = book.count(f\"conversions of '{t}'\", val(r, \"conversions\"), \"conversions\", t,\n                           dp=conv_dp(val(r, \"conversions\")))\n            steps.append({\"kind\": \"review\", \"title\": f\"Review \u201c{t}\u201d\",\n                          \"text\": f\"\\u201c{t}\\u201d converts, but at {p} each, more than {EXPENSIVE} times the account's \"\n                                  f\"{cpa_s} per conversion. It spent {c} for {v} \"\n                                  f\"{plural(val(r, 'conversions'), 'conversion')}.\"})\n        else:\n            k_s = book.count(\"search terms converting at an expensive rate\", len(x[\"pricey\"]))\n            rows = []\n            for r in pricey:\n                rt = r[\"search_term\"]\n                rows.append([rt, book.money(f\"cost of '{rt}'\", val(r, \"cost\"), \"cost\", rt),\n                             book.count(f\"conversions of '{rt}'\", val(r, \"conversions\"), \"conversions\", rt,\n                                        dp=conv_dp(val(r, \"conversions\"))),\n                             book.money(f\"cost per conversion of '{rt}'\", _cpa(r), \"cpa\", rt)])\n            steps.append({\"kind\": \"review\", \"title\": f\"Review {k_s} expensive converters\",\n                          \"text\": f\"They convert, but at more than {EXPENSIVE} times the account's {cpa_s} per \"\n                                  \"conversion.\",\n                          \"table\": {\"cols\": [\"Search term\", \"Cost\", \"Conversions\", \"Cost per conversion\"],\n                                    \"align\": [\"left\", \"right\", \"right\", \"right\"], \"rows\": rows}})\n    if x[\"harvest\"]:\n        k = len(x[\"harvest\"])\n        k_s = book.count(\"search terms worth adding as keywords\", k)\n        rows = []\n        for r in x[\"harvest\"][:top]:\n            rt = r[\"search_term\"]\n            rows.append([rt, book.count(f\"conversions of '{rt}'\", val(r, \"conversions\"), \"conversions\", rt,\n                                        dp=conv_dp(val(r, \"conversions\"))),\n                         book.money(f\"cost per conversion of '{rt}'\", _cpa(r), \"cpa\", rt), r.get(\"match_type\", \"\")])\n        steps.append({\"kind\": \"add\", \"title\": f\"Add {k_s} converting search {plural(k, 'term')} as keywords\",\n                      \"text\": f\"{'It' if k == 1 else 'They'} converted at or below the account's {cpa_s} per \"\n                              f\"conversion and {'is not a keyword' if k == 1 else 'are not keywords'} yet.\",\n                      \"table\": {\"cols\": [\"Search term\", \"Conversions\", \"Cost per conversion\", \"Match type\"],\n                                \"align\": [\"left\", \"right\", \"right\", \"left\"], \"rows\": rows}})\n    for i, step in enumerate(steps, 1):\n        step.update(type=\"step\", n=i, tag=STEP_TAGS[step[\"kind\"]])\n    recommend = ([{\"type\": \"p\", \"text\": STEP_COUNT.get(len(steps), f\"{len(steps)} steps, most useful first.\")}]\n                 + steps) if steps else [{\"type\": \"p\", \"text\": \"Nothing needs changing at this threshold.\"}]\n\n    sections = [{\"id\": \"found\", \"title\": \"What we found\", \"blocks\": found},\n                {\"id\": \"recommend\", \"title\": \"What we recommend\", \"blocks\": recommend}]\n    grand = x[\"grand\"]\n    if x[\"industry\"]:\n        b, rows = benchmarks.compare(book, x[\"industry\"], cost=grand.cost, clicks=grand.clicks,\n                                     impressions=grand.impressions, conversions=grand.conversions,\n                                     currency=report.currency)\n        compare = []\n        for r in rows:\n            most = max(r[\"yours\"], r[\"average\"]) or 1\n            compare.append({\"type\": \"compare\", \"name\": LONG_NAMES[r[\"name\"]],\n                            \"read\": f\"{r['side'].capitalize()}, {'better' if r['better'] else 'worse'}\",\n                            \"better\": r[\"better\"], \"yours\": r[\"yours_text\"], \"average\": r[\"average_text\"],\n                            \"yours_width\": round(r[\"yours\"] / most * 100, 1),\n                            \"average_width\": round(r[\"average\"] / most * 100, 1)})\n        if rows:\n            ways = [HOW_IT_COMPARES[r[\"name\"]][r[\"side\"] == \"higher\"] for r in rows]\n            blocks = [{\"type\": \"lead\", \"strong\": \"\", \"text\": f\"Against the {b['name']} average, the account {_and(ways)}.\"}]\n            blocks += compare\n            blocks.append({\"type\": \"note\", \"text\": f\"Industry averages: {benchmarks.SOURCE}. A ballpark, not a target: \"\n                                                   \"US-only, averaged over a year, and every advertiser counts \"\n                                                   \"conversions differently. The industry figure for cost per \"\n                                                   \"conversion is cost per lead.\"})\n            sections.append({\"id\": \"benchmarks\", \"title\": \"How the account compares\", \"blocks\": blocks})\n\n    file = os.path.basename(report.source or \"\")\n    data = f\"One export from Google Ads: `{file}`, the search terms report\"\n    if report.start and report.end:\n        days = book.count(\"days in the date range\", report.days, \"days\")\n        data += f\" for {period(report)} ({days} days)\"\n    data += f\", in {report.currency}. Nothing in the Google Ads account was changed: this report only reads the export.\"\n    rules = [f\"Waste: search terms with zero conversions and at least {min_s} in cost. Each term's rows are added \"\n             \"up first, so a term that converts anywhere in the account is never waste.\"]\n    if x[\"brand\"]:\n        rules.append(\"Searches for the brand, including close misspellings, are never counted as waste.\")\n    if x[\"in_auto\"]:\n        rules.append(\"Performance Max and other automated campaigns are listed apart from Search, because negatives \"\n                     \"there only block Search and Shopping ads.\")\n    if bar:\n        rules.append(\"Likely bad: the chance a term truly converts at less than half the account's rate, learned from \"\n                     f\"how much this account's own search terms differ. {bar} is the bar for adding a negative.\")\n    if x[\"names\"]:\n        rules.append(f\"Words that never convert: words and two-word phrases found in at least {THEME_MIN_TERMS} search \"\n                     \"terms that together spent money and got no conversions.\")\n    rules += [f\"Converting, but expensive: cost per conversion above {EXPENSIVE} times the account average.\",\n              f\"Worth adding: {HARVEST_MIN} or more conversions, cost per conversion at or below the account \"\n              \"average, and not a keyword yet.\",\n              \"Totals are recomputed from the rows of the export.\",\n              \"A conversion is whatever this account counts as one.\"]\n    method = [{\"type\": \"h2\", \"text\": \"The data\"}, {\"type\": \"p\", \"text\": data}]\n    sha = fingerprint(report.source)\n    if sha:\n        method.append({\"type\": \"fingerprint\", \"value\": sha})\n    method += [{\"type\": \"h2\", \"text\": \"How the numbers were computed\"}, {\"type\": \"list\", \"items\": rules},\n               {\"type\": \"check\", \"file\": file}]\n    sections.append({\"id\": \"method\", \"title\": \"How this report was made\", \"blocks\": method})\n    return {\"template\": NAME, \"title\": CLIENT_TITLE, \"period\": period(report, compact=True),\n            \"month\": month_label(report), \"file\": file, \"headline\": headline, \"sections\": sections}\n\n\ndef run(report, min_cost=None, industry=None, top=25, brand=None, **_):\n    need(report, \"search_term\", \"Search terms report\", HOW_TO_EXPORT)\n    book = FactBook(report.currency)\n    known_default = True\n    if min_cost is None:\n        min_cost, known_default = min_cost_for(report.currency)\n    is_brand = brand_matcher(brand)\n    rows = [r for r in report.rows if r.get(\"search_term\")]\n    by_term = _by_term(rows)\n    brand_rows = [t for t in by_term if is_brand(t[\"search_term\"])]\n    others = [t for t in by_term if not is_brand(t[\"search_term\"])]\n    grand = totals(rows)\n    out = header(book, report, TITLE)\n    total_cost = book.money(\"total cost\", grand.cost)\n    min_s = book.money(\"minimum cost for a waste flag (rule)\", min_cost, \"rule\")\n    cpa = grand.cost / grand.conversions if grand.conversions else None\n    zero = [t for t in others if not val(t, \"conversions\")]  # not one conversion on any of the term's rows\n    waste = sorted((t for t in zero if val(t, \"cost\") >= min_cost), key=lambda t: -val(t, \"cost\"))\n    small = [t for t in zero if 0 < val(t, \"cost\") < min_cost]\n    wasted = totals(waste)\n    in_search = [t for t in waste if t[\"group\"] == \"search\"]\n    names, found = _themes(others)\n    prior = waste_model.fit_prior((val(r, \"clicks\"), val(r, \"conversions\")) for r in others)\n    chance = {id(r): waste_model.p_bad(val(r, \"clicks\"), 0, prior) for r in waste} if prior else {}\n    sure = [r for r in waste if chance.get(id(r), 0) >= waste_model.CONFIDENT]\n    in_auto = [t for t in waste if t[\"group\"] == \"automated\"]\n    in_both = [t for t in waste if t[\"group\"] == \"both\"]\n\n    out += [\"## Summary\", \"\"]\n    if not known_default:\n        out += [f\"_OpenPPC has no default waste threshold for {report.currency}, so it used {min_s}. \"\n                \"Set your own with `--min-cost`._\", \"\"]\n    wc = share = d = y = cpa_s = bar = needed = sw = aw = need_s = need_cost = None\n    pricey = harvest = []\n    if waste and grand.cost:\n        n = book.count(\"search terms flagged as waste\", len(waste))\n        wc = book.money(\"wasted cost (zero conversions, at or above the threshold)\", wasted.cost)\n        share = book.pct(\"wasted cost as a share of total cost\", wasted.cost / grand.cost * 100, \"cost\")\n        out.append(f\"**{n} {plural(len(waste), 'search term')} spent {wc} and never converted.** That is \"\n                   f\"{share} of the {total_cost} total cost in this export, and each one cost at least {min_s}.\")\n        search_cost, auto_cost = sum(t[\"search_cost\"] for t in waste), sum(t[\"automated_cost\"] for t in waste)\n        if search_cost and auto_cost:\n            sw = book.money(\"wasted cost in Search campaigns\", search_cost, \"cost\")\n            aw = book.money(\"wasted cost in Performance Max and other automated campaigns\", auto_cost, \"cost\")\n            out += [\"\", f\"Of that, {sw} is in Search campaigns and {aw} in Performance Max and other \"\n                        \"automated campaigns, which take negatives differently.\"]\n        if report.days:\n            per_day = wasted.cost / report.days\n            d = book.money(\"wasted cost per day\", per_day)\n            y = book.money(\"wasted cost per year at the same daily rate\", per_day * 365)\n            out += [\"\", f\"At the same rate that is {d} a day, or {y} a year.\"]\n        if prior:\n            bar = book.pct(\"waste model: sure enough to add a negative (rule)\", waste_model.CONFIDENT * 100, \"rule\", dp=0)\n            if sure:\n                m = book.count(\"waste terms the waste model is sure about\", len(sure))\n                mc = book.money(\"cost of the waste terms the model is sure about\", totals(sure).cost)\n                doubt = round(sum(1 - chance[id(r)] for r in sure))\n                maybe = (f\" (about {book.count('sure waste terms that may still be fine', doubt)} of them may still turn \"\n                         \"out fine)\" if doubt else \"\")\n                out += [\"\", f\"The waste model is at least {bar} sure about {m} of them, which spent {mc}{maybe}: add \"\n                            f\"{'it as a negative' if len(sure) == 1 else 'those as negatives'}. The other {book.count('waste terms too early to judge', len(waste) - len(sure))} \"\n                            \"have too few clicks to tell a bad term from bad luck.\"]\n            else:\n                out += [\"\", f\"None of them has enough clicks for the waste model to be {bar} sure it is bad rather \"\n                            \"than unlucky, so give them more clicks before adding negatives.\"\n                            + (\" The words they share are below.\" if names else \"\")]\n    else:\n        out.append(f\"No search term with zero conversions reached {min_s} in cost. \"\n                   \"Nothing to cut one term at a time at this threshold.\")\n    clicks = book.count(\"total clicks\", grand.clicks, \"clicks\")\n    convs = book.count(\"total conversions\", grand.conversions, \"conversions\", dp=conv_dp(grand.conversions))\n    line = f\"Account totals in this export: {total_cost} cost, {clicks} clicks, {convs} conversions\"\n    if cpa:\n        cpa_s = book.money(\"account cost per conversion\", cpa, \"cpa\")\n        line += f\", {cpa_s} per conversion\"\n    out += [\"\", line + \".\"]\n    if brand_rows:\n        bt = totals(brand_rows)\n        bn = book.count(\"search terms that match your brand\", len(brand_rows), \"terms\")\n        bc = book.money(\"cost of search terms that match your brand\", bt.cost, \"cost\")\n        bv = book.count(\"conversions of search terms that match your brand\", bt.conversions, \"conversions\",\n                        dp=conv_dp(bt.conversions))\n        verb = \"matches\" if len(brand_rows) == 1 else \"match\"\n        out += [\"\", f\"Brand terms are left out of the waste list: {bn} {plural(len(brand_rows), 'search term')} \"\n                    f\"{verb} your brand, cost {bc} and brought {bv} conversions. Never add them as negatives.\"]\n\n    todo_at = len(out)  # \"What to do\" goes here, once everything it sums up is computed\n    if waste:\n        out += [\"\", \"## Wasted spend, ranked\"]\n        if not (in_auto or in_both):\n            out += [\"\"] + _waste_table(book, waste[:top], grand, False, chance)\n        else:\n            cap = book.count(\"negative keywords a Performance Max campaign can hold (Google's limit)\",\n                             PMAX_NEGATIVES, \"rule\")\n            for title, members, note, auto in (\n                    (\"In Search campaigns\", in_search, \"Add these as negative keywords in their campaigns.\", False),\n                    (\"In Performance Max and other automated campaigns\", in_auto,\n                     f\"Performance Max takes negative keywords in the campaign (up to {cap}) or from an \"\n                     \"account-level negative keyword list, and there they only block Search and Shopping ads, \"\n                     \"not YouTube, Display or Gmail.\", True),\n                    (\"In both Search and automated campaigns\", in_both,\n                     \"These spent in both. An account-level negative keyword list blocks a term in both places; \"\n                     \"otherwise add it in each campaign.\", True)):\n                if members:\n                    out += [\"\", f\"### {title}\", \"\", note, \"\"] + _waste_table(book, members[:top], grand, auto, chance)\n        if len(waste) > top:\n            rest = totals(waste[top:])\n            k = book.count(\"waste terms beyond the table\", len(waste) - top)\n            c = book.money(\"cost of waste terms beyond the table\", rest.cost)\n            out += [\"\", f\"Plus {k} more {plural(len(waste) - top, 'term')} that spent {c} in total.\"]\n    if small:\n        st = totals(small)\n        k = book.count(\"zero-conversion terms below the threshold\", len(small))\n        c = book.money(\"cost of zero-conversion terms below the threshold\", st.cost)\n        out += [\"\", f\"Below the {min_s} threshold, {k} more zero-conversion {plural(len(small), 'term')} \"\n                    f\"spent {c} in total.\" + (\" The words they share are below.\" if names else \"\")]\n    if prior:\n        needed = waste_model.clicks_to_flag(prior)\n        if needed is None or needed > ALIKE_CLICKS:\n            out += [\"\", \"Search terms in this account convert at much the same rate, so one term's missing conversions \"\n                        \"are most likely bad luck.\" + (\" Judge the words below, not single terms.\" if names else \"\")]\n        else:\n            need_s = book.count(\"clicks a search term needs before the waste model is sure it is bad\", needed, \"clicks\")\n            need_cost = book.money(\"cost of that many clicks at the account's average CPC\",\n                                   needed * grand.cost / grand.clicks, \"cost\")\n            r_s = book.pct(\"account conversion rate\", grand.conversions / grand.clicks * 100, \"cvr\")\n            out += [\"\", f\"At this account's {r_s} conversion rate, and given how much its search terms differ, a term \"\n                        f\"needs about {need_s} clicks (about {need_cost}) with no conversion before the waste model is sure it is \"\n                        \"bad.\" + (\" Below that, judge words, not single terms.\" if names else \"\")]\n\n    if names:\n        out += [\"\", \"## Words that never convert\", \"\",\n                \"These words show up across several search terms that spent money without a single \"\n                \"conversion. Each one is a candidate negative keyword: check it against what you sell first.\",\n                \"\", \"| Word or phrase | Search terms | Clicks | Cost |\", \"|---|---|---|---|\"]\n        for g in names:\n            terms, clicks_g, cost_g, _ = found[g]\n            label = f'search terms containing \"{g}\"'  # the word is the row: its figures only count where it is named\n            n = book.count(f\"number of {label}\", terms, \"terms\", g)\n            k = book.count(f\"clicks of {label}\", clicks_g, \"clicks\", g)\n            c = book.money(f\"cost of {label}\", cost_g, \"cost\", g)\n            out.append(f\"| {esc(g)} | {n} | {k} | {c} |\")\n\n    if cpa:\n        pricey = sorted((r for r in by_term if val(r, \"conversions\") and val(r, \"cost\") >= min_cost\n                         and _cpa(r) > EXPENSIVE * cpa), key=lambda r: -val(r, \"cost\"))\n        if pricey:\n            out += [\"\", \"## Converting, but expensive\", \"\",\n                    f\"These converted, but at more than {EXPENSIVE} times the account's {cpa_s} per conversion.\",\n                    \"\", \"| Search term | Cost | Conversions | Cost per conversion |\", \"|---|---|---|---|\"]\n            for r in pricey[:top]:\n                t = r[\"search_term\"]\n                c = book.money(f\"cost of '{t}'\", val(r, \"cost\"), \"cost\", t)\n                v = book.count(f\"conversions of '{t}'\", val(r, \"conversions\"), \"conversions\", t,\n                               dp=conv_dp(val(r, \"conversions\")))\n                p = book.money(f\"cost per conversion of '{t}'\", _cpa(r), \"cpa\", t)\n                out.append(f\"| {esc(t)} | {c} | {v} | {p} |\")\n        harvest = sorted((r for r in by_term if val(r, \"conversions\") >= HARVEST_MIN and _cpa(r) <= cpa\n                          and _not_yet_added(r)), key=lambda r: (-val(r, \"conversions\"), _cpa(r)))\n        if harvest:\n            out += [\"\", \"## Worth adding as keywords\", \"\",\n                    f\"These converted at or below the account's {cpa_s} per conversion and are not keywords yet.\",\n                    \"\", \"| Search term | Conversions | Cost per conversion | Match type |\", \"|---|---|---|---|\"]\n            for r in harvest[:top]:\n                t = r[\"search_term\"]\n                v = book.count(f\"conversions of '{t}'\", val(r, \"conversions\"), \"conversions\", t,\n                               dp=conv_dp(val(r, \"conversions\")))\n                p = book.money(f\"cost per conversion of '{t}'\", _cpa(r), \"cpa\", t)\n                out.append(f\"| {esc(t)} | {v} | {p} | {esc(r.get('match_type', ''))} |\")\n\n    actions = _actions(book, waste, sure, chance, prior, needed, bar, pricey, harvest, cpa_s)\n    if actions:\n        out[todo_at:todo_at] = [\"\", \"## What to do\", \"\"] + [\n            f\"{i}. **{a['title']}.** {a['detail']}\" for i, a in enumerate(actions, 1)]\n    book.cards = _cards(book, grand, waste, sure, chance, top, wc, share, d, y, cpa_s, industry, actions)\n\n    if industry:\n        out += benchmarks.section(book, industry, cost=grand.cost, clicks=grand.clicks,\n                                  impressions=grand.impressions, conversions=grand.conversions,\n                                  currency=report.currency)\n    book.client = _client(book, report, {\n        \"waste\": waste, \"sure\": sure, \"chance\": chance, \"prior\": prior, \"needed\": needed, \"bar\": bar, \"wc\": wc,\n        \"share\": share, \"d\": d, \"y\": y, \"cpa_s\": cpa_s, \"min_s\": min_s, \"total_cost\": total_cost, \"clicks\": clicks,\n        \"convs\": convs, \"sw\": sw, \"aw\": aw, \"need_s\": need_s, \"need_cost\": need_cost, \"small\": small,\n        \"brand_rows\": brand_rows, \"brand\": brand, \"names\": names, \"found\": found, \"pricey\": pricey,\n        \"harvest\": harvest, \"in_auto\": in_auto + in_both, \"grand\": grand, \"industry\": industry, \"top\": top})\n\n    rule_bar = book.pct(\"waste model: sure enough to add a negative (rule)\", waste_model.CONFIDENT * 100, \"rule\", dp=0)\n    out += [\"\", \"## How this was computed\", \"\",\n            f\"- Waste: search terms with zero conversions and at least {min_s} in cost. \"\n            \"Change the threshold with `--min-cost`.\",\n            \"- Each search term's rows are added up first: Google lists a term once for every campaign, ad group \"\n            \"and match type it showed in, and a term that converts on any of its rows is never waste.\",\n            \"- Brand terms (from `--brand`, including close misspellings) are never counted as waste.\",\n            \"- Performance Max and other automated campaign types are listed apart from Search, because \"\n            \"negatives there only block Search and Shopping ads.\",\n            f\"- Words that never convert: words and two-word phrases found in at least {THEME_MIN_TERMS} \"\n            \"search terms that together spent money and got no conversions.\",\n            \"- Chance it's bad: the waste model learns how much this account's search terms differ in \"\n            \"conversion rate (a beta-binomial prior fit on your own terms), then works out for each term the chance \"\n            f\"that it truly converts at less than half the account's rate. {rule_bar} is \"\n            \"the bar for adding a negative; the dollar threshold only decides what is worth listing.\",\n            f\"- Converting, but expensive: cost per conversion above {EXPENSIVE} times the account average.\",\n            f\"- Worth adding: {HARVEST_MIN} or more conversions, cost per conversion at or below the account \"\n            \"average, and not already added or excluded.\",\n            \"- Totals are recomputed from the rows. The Total lines in Google's export are ignored.\",\n            \"- A conversion is whatever this account counts as one. If that includes small actions such as \"\n            \"page views, zero conversions means something weaker here.\"]\n    return out, book\n","openppc/webapi.py":"\"\"\"Browser bridge. The web app runs this package inside Pyodide and calls these functions.\n\nArguments are plain strings (paths inside the in-browser file system, or text) and every\nfunction returns a JSON string, except count_numbers. Nothing here touches the network.\n\"\"\"\nimport itertools\nimport json\nimport os\nfrom dataclasses import asdict\n\nfrom . import __version__\nfrom .checkfacts import facts_for_paths\nfrom .engine import benchmarks\nfrom .engine.trace import render_check, trace\nfrom .ingest import load_report\nfrom .ingest.account import is_snapshot, read_json, snapshot\nfrom .templates import TEMPLATES, account_read, load_input, run_template, run_template_book\nfrom .facts import SYMBOLS\nfrom .templates._common import fingerprint, min_cost_for\n\nREAD_ERRORS = (ValueError, KeyError, TypeError, UnicodeDecodeError, OSError)\nKEEP_AUDITS = 8  # recent audits whose facts the app can still check a branded PDF against\n_BOOKS = {}\n_TOKENS = itertools.count(1)\nWRONG_FILE = (\"Export a Search terms or Keywords report from Google Ads: Campaigns > Insights and \"\n              \"reports > Search terms, pick the date range, then Download > .csv.\")\n\n\ndef _json(obj):\n    return json.dumps(obj, default=str)\n\n\ndef _clean(error, paths):\n    \"\"\"Error text without the in-browser folder names.\"\"\"\n    text = str(error)\n    for p in paths:\n        text = text.replace(p, os.path.basename(p))\n    return text\n\n\ndef meta():\n    \"\"\"Version, templates and industries for the page's pickers.\"\"\"\n    return _json({\n        \"version\": __version__,\n        \"templates\": [{\"name\": t.NAME, \"title\": t.TITLE, \"input\": t.INPUT, \"summary\": t.SUMMARY,\n                       \"kind\": t.INPUT_KIND} for t in TEMPLATES.values()],\n        \"industries\": [{\"key\": k, \"name\": row[0]} for k, row in benchmarks.TABLE.items()],\n    })\n\n\ndef inspect_file(path):\n    \"\"\"What the file chip shows, and which templates can read the file.\"\"\"\n    name = os.path.basename(path)\n    try:\n        if path.lower().endswith(\".json\"):\n            raw = read_json(path)\n            if is_snapshot(raw):\n                data = snapshot(raw, source=path)\n                fits = [t.NAME for t in TEMPLATES.values() if t.INPUT_KIND == \"account\" and t.accepts(data)]\n                return _json({\"ok\": True, \"name\": name, \"kind\": \"Account snapshot\", \"rows\": len(data[\"campaigns\"]),\n                              \"start\": None, \"end\": None, \"days\": None,\n                              \"currency\": (data[\"meta\"].get(\"currency\") or None), \"templates\": fits})\n            data = account_read.load_metrics(path)\n            fits = [t.NAME for t in TEMPLATES.values() if t.INPUT_KIND == \"metrics\" and t.accepts(data)]\n            return _json({\"ok\": True, \"name\": name, \"kind\": \"Two-period totals\", \"rows\": None, \"start\": None,\n                          \"end\": None, \"days\": None, \"currency\": None, \"templates\": fits})\n        report = load_report(path)\n    except READ_ERRORS as e:\n        error = _clean(e, [path])\n        if error.startswith(name + \": \"):  # the file chip already shows the name, right above the error\n            error = error[len(name) + 2:]\n        return _json({\"ok\": False, \"name\": name, \"error\": error, \"hint\": WRONG_FILE})\n    if report.has(\"search_term\"):\n        kind = \"Search terms report\"\n    elif report.has(\"keyword\"):\n        kind = \"Keywords report\"\n    else:\n        kind = \"Google Ads report\"\n    fits = [t.NAME for t in TEMPLATES.values() if t.INPUT_KIND == \"report\" and t.accepts(report)]\n    return _json({\"ok\": True, \"name\": name, \"kind\": kind, \"rows\": len(report.rows),\n                  \"start\": report.start.isoformat() if report.start else None,\n                  \"end\": report.end.isoformat() if report.end else None,\n                  \"days\": report.days, \"currency\": report.currency, \"templates\": fits,\n                  \"currency_sign\": SYMBOLS.get((report.currency or \"\").upper(), \"\"),\n                  \"min_cost\": min_cost_for(report.currency)[0]})\n\n\ndef count_numbers(text):\n    \"\"\"How many numbers in the text the check will judge.\"\"\"\n    claims, _ = trace(text, [])\n    return len(claims)\n\n\ndef check(text, paths_json, industry=\"\"):\n    \"\"\"Check every number in an audit against the files (and optionally an industry's averages).\"\"\"\n    paths = json.loads(paths_json)\n    try:\n        facts = facts_for_paths(paths, industry or None)\n    except READ_ERRORS as e:\n        return _json({\"ok\": False, \"error\": _clean(e, paths)})\n    claims, contradictions = trace(text, facts)\n    counts = {\n        \"total\": len(claims),\n        \"traced\": sum(c.verdict == \"traced\" for c in claims),\n        \"mismatch\": sum(c.verdict == \"mismatch\" for c in claims),\n        \"not_in_data\": sum(c.verdict == \"not in data\" for c in claims),\n        \"cant_check\": sum(c.verdict == \"can't check\" for c in claims),\n        \"contradictions\": len(contradictions),\n    }\n    return _json({\"ok\": True, \"counts\": counts, \"claims\": [asdict(c) for c in claims],\n                  \"contradictions\": [{\"line\": n, \"problem\": p, \"context\": ctx} for n, p, ctx in contradictions],\n                  \"markdown\": render_check(claims, contradictions)})\n\n\ndef audit(name, path, industry=\"\", min_cost=None, brand=\"\"):\n    \"\"\"Run a template on a file. The report has already passed its own number check when passed is true.\"\"\"\n    template = TEMPLATES.get(name)\n    if template is None:\n        return _json({\"ok\": False, \"error\": f\"unknown template '{name}'\"})\n    wrong = _json({\"ok\": False, \"error\": f\"{os.path.basename(path)} is not a {template.INPUT}.\"})\n    try:\n        data = load_input(template, path)\n    except READ_ERRORS:\n        return wrong\n    if not template.accepts(data):\n        return wrong\n    try:\n        cost = None if min_cost in (None, \"\") else float(min_cost)  # unset: the default in the export's currency\n        markdown, book, passed = run_template_book(name, path, industry=industry or None, min_cost=cost,\n                                                   brand=brand or None)\n    except READ_ERRORS as e:\n        return _json({\"ok\": False, \"error\": _clean(e, [path])})\n    token = f\"audit-{next(_TOKENS)}\"\n    _BOOKS[token] = book\n    while len(_BOOKS) > KEEP_AUDITS:\n        _BOOKS.pop(next(iter(_BOOKS)))\n    return _json({\"ok\": True, \"title\": template.TITLE, \"markdown\": markdown, \"passed\": passed,\n                  \"facts\": len(book.facts), \"cards\": book.cards, \"client\": book.client or None, \"token\": token,\n                  \"fingerprint\": fingerprint(path)})\n\n\ndef verify(token, text, names_json=\"[]\"):\n    \"\"\"Check the text of a finished branded PDF against the audit it was made from.\n\n    The names the user typed (agency, client, report title) are set aside first: they are words\n    on the page, not claims about the account, even when they hold digits.\"\"\"\n    book = _BOOKS.get(token)\n    if book is None:\n        return _json({\"ok\": False, \"error\": \"This audit is no longer loaded. Run it again, then make the PDF.\"})\n    names = {n.strip() for n in json.loads(names_json or \"[]\") if isinstance(n, str) and n.strip()}\n    for name in sorted(names, key=len, reverse=True):\n        text = text.replace(name, \"Name\")\n    claims, contradictions = trace(text, book.facts)\n    bad = [c for c in claims if c.verdict != \"traced\"]\n    problems = [{\"written\": c.written, \"verdict\": c.verdict, \"detail\": c.detail, \"context\": c.context} for c in bad]\n    problems += [{\"written\": \"\", \"verdict\": \"contradiction\", \"detail\": p, \"context\": ctx} for _, p, ctx in contradictions]\n    return _json({\"ok\": True, \"total\": len(claims), \"traced\": len(claims) - len(bad), \"problems\": problems})\n"},"samples":{"account_acme.json":"","account_structure_acme.json":"","ai_audit_sample.md":"","keywords_acme.csv":"","search_terms_acme.csv":""},"templates":[{"input":"Search terms report (.csv)","module":"search_term_waste","name":"search-term-waste","summary":"Search terms that spent money and never converted, ranked by cost, the words behind the long tail, plus expensive converters and terms worth adding as keywords.","tier":"free","title":"Search-term waste audit"},{"input":"Keywords report (.csv)","module":"keyword_audit","name":"keyword-audit","summary":"Keywords spending without converting, budget and results by match type, and spend on low Quality Scores.","tier":"free","title":"Keyword audit"},{"input":"Account snapshot (.json)","module":"account_structure","name":"account-structure","summary":"How the account is built: broad match without Smart Bidding, brand mixed with non-brand, duplicate keywords, negatives that block your own keywords, thin or pinned ads, missing sitelinks, retired bidding and more.","tier":"free","title":"Account structure audit"},{"input":"two-period totals (.json)","module":"account_read","name":"account-read","summary":"What changed between two periods, classified by explicit rules: efficiency win, over-expansion, broken tracking, and more. Every direction is computed, never guessed.","tier":"free","title":"Account read: period over period"}]};
